// #define UPDATE_GUI if(gui_up)while(g_main_context_pending(NULL)) g_main_context_iteration(NULL,FALSE);
// Universal GTK4 Synchronous Paint Flush Macro
// This queries the GListModel interface natively to force ALL open 
// windows and active dialog boxes to update their GPU structures.
#define UPDATE_GUI \
    do { \
        if (gui_up) { \
            GListModel *tl_model = gtk_window_get_toplevels(); \
            if (tl_model != NULL) { \
                unsigned int n_tl = g_list_model_get_n_items(tl_model); \
                for (unsigned int idx_tl = 0; idx_tl < n_tl; idx_tl++) { \
                    gpointer tl_item = g_list_model_get_item(tl_model, idx_tl); \
                    if (GTK_IS_WIDGET(tl_item)) { \
                        gtk_widget_queue_allocate(GTK_WIDGET(tl_item)); \
                    } \
                    if (tl_item != NULL) g_object_unref(tl_item); \
                } \
            } \
        } \
        while (g_main_context_pending(NULL)) { \
            g_main_context_iteration(NULL, FALSE); \
        } \
    } while (0);

#define PUMP_INPUT_EVENTS_ONLY \
    do { \
        while (g_main_context_pending(NULL)) { \
            g_main_context_iteration(NULL, FALSE); \
        } \
    } while (0);

