// Structure for a scan point node
typedef struct {
    uint32_t x, y, z;           // The coordinates of the scan point
    int    hastissue;           // Whether there is tissue at that point or not (is there an image to read from file?)
    char  *name;                // The path name of the image
    double wgt;                 // Weighting factor (= 1.0 by default)
    int    tmpx,tmpy;           // Work variables to calculate neighbours
    int    l,r,f,b,u,d;         // The indices of elements in the list of ScanPoints that contain scan image data for the images immediately
    int    po_x,pe_x,po_y,pe_y; // Tile position in preview image corresponding to this scan point
} ScanPoint;

typedef struct {
 int32_t maxmsdenom[3];
 int32_t msdenom[3];
 uint32_t x_homed_switch;
 uint32_t y_homed_switch;
 int x_dirn1;
 int x_dirn2;
 int y_dirn1;
 int y_dirn2;
 int UnitType;
 char unitname[32];      // Stage calibration units name
 double maxcalibri_x;    // Stage calibration factor for X
 double maxcalibri_y;    // Stage calibration factor for Y
 double maxcalibri_z;    // Stage calibration factor for Z
 uint8_t Synced_stage;   // 0 = Unsynced, 1 = Calibration Confirmed
 int32_t acc_isd[2];
 double  acc_acp;
 struct {
    uint8_t maxms : 1;
    uint8_t msden : 1;
    uint8_t xhome : 1;
    uint8_t yhome : 1;
    uint8_t xdir1 : 1;
    uint8_t xdir2 : 1;
    uint8_t ydir1 : 1;
    uint8_t ydir2 : 1; // --- End of first 8-bit container ---
    uint8_t uname : 1;
    uint8_t utype : 1;
    uint8_t calix : 1;
    uint8_t caliy : 1;
    uint8_t caliz : 1;
    uint8_t accel : 1; // --- 6 bits used in second container ---
 } syncneeded;
} StageParam;

typedef struct {
    char Scan_filename[PCS_PATH_MAX];
    char Scan_basepath[PCS_PATH_MAX]; // Absolute folder prefix tracking
    double xyzs_coords_s[3]; // The start coordinates of an XYZ scan
    double xyzs_coords_f[2]; // The finish coordinates of an XYZ scan  
    double xyzs_calib_x;     // The field calibrations for an XYZ scan
    double xyzs_calib_y;     // (in whatever units
    double xyzs_calib_z;     // the scan used)
    int32_t xyzs_semino_z;  // (Half) thenumber of Z planes (beyond the 1)
    int32_t curr_z;         // The currently viewed Z plane
    void *img;              // A pointer to the blob that hold the image data 
    size_t img_sz;          // Current size of the image blob in bytes
    int   Saveas_Fmt;       // Indicates the format of the scan images
    char *ImRoot;           // Forms part of saved image file name
    int ImWidth;
    int ImHeight;
    int ImWidth_stride;
    int ImSize;
    int RGBSize;
    uint32_t sp_stride;    // Scan point stride.
    uint8_t  neighbours_found; // Have scan point neighbours been calculated?
    uint8_t  Synced_cam;   // 0 = Unsynced, 1 = Synced & Validated
    StageParam  Stage;     // Stage parameters
    ScanPoint  *SPlist;    // List of scan points and their weights
    uint32_t    NSPs;      // The number of scan points in the list.
    size_t      SizeSPs;   // The current size of the scan points list
    uint32_t    RenderIdx; // The XYSlist index of the member being rendered.
} ScanParam;

ScanParam   *XYSlist;      // To store XY scans (live or loaded from disc)
uint32_t     NXYSs = 0;    // The number of scans in the list.
size_t       SizeXYSs = 0; // The current size of the XY scans list 

#define SC_CURR 0  // The rendered scan will always be from list member 0
#define SC_LIVE 1  // Data for a live scan will always be in list member 1
unsigned int SC_ViewIdx = 0; // This must be >=2 to be valid and represents the
                             // list member of the currently selected loaded
                             // scan to be / that is being rendered.

// Return values for loop_new()
#define SPE_SUCCESS 0 // No error. Scan point created OK
#define SPE_MEMFAIL 1 // Failed. Couldn't get memory for the new scan point.

int sp_new(uint32_t x, uint32_t y, uint32_t z, char *name,uint32_t idx)
// Adds a new scan point node to the XYSlist[idx].SPlist.
{
    ScanPoint *newmem;
    size_t newsize, nomlen;
    unsigned int pdx;
    char *new_name;

    // 1. Pre-calculate name length and allocate the string buffer first
    nomlen = strlen(name) + 1;
    new_name = malloc(nomlen);
    if(new_name == NULL){
        show_message("Failed to get memory for scan point name.\n", "sp_new: ",
                                                                     MT_ERR, 1);
        return SPE_MEMFAIL;
    }

    // 2. Attempt the master structure array list allocation pass
    newsize = XYSlist[idx].SizeSPs + sizeof(ScanPoint);
    newmem = realloc(XYSlist[idx].SPlist, newsize);
    if(newmem == NULL){
        show_message("Failed to get memory for scan point structure.\n",
                                                         "sp_new: ", MT_ERR, 1);
        free(new_name); // Clean up the isolated string copy to prevent leaks!
        return SPE_MEMFAIL;
    }

    // 3. TRANSACTION SUCCESS HANDSHAKE: Commit everything to global tracking
    // states simultaneously
    XYSlist[idx].SPlist = newmem;
    XYSlist[idx].SizeSPs = newsize;
    pdx = XYSlist[idx].NSPs;
    XYSlist[idx].NSPs++;

    // 4. Safely populate the verified memory nodes
    XYSlist[idx].SPlist[pdx].name = new_name;
    memcpy(XYSlist[idx].SPlist[pdx].name, name, nomlen);
    
    XYSlist[idx].SPlist[pdx].x = x;
    XYSlist[idx].SPlist[pdx].y = y;
    XYSlist[idx].SPlist[pdx].z = z;
    XYSlist[idx].SPlist[pdx].hastissue = strcmp("NoTissue", name) ? 1 : 0;
    
    XYSlist[idx].SPlist[pdx].wgt = 1.0; 
    XYSlist[idx].SPlist[pdx].l = XYSlist[idx].SPlist[pdx].r =
                                 XYSlist[idx].SPlist[pdx].f = -1; // -1='unset' 
    XYSlist[idx].SPlist[pdx].b = XYSlist[idx].SPlist[pdx].u =
                                 XYSlist[idx].SPlist[pdx].d = -1; // -1='unset'
    XYSlist[idx].SPlist[pdx].tmpx = XYSlist[idx].SPlist[pdx].tmpy = -1;

    return SPE_SUCCESS;
}

void sp_listfree(uint32_t idx)
// Frees the list of scan points in scan idx
{
 uint32_t pdx;
 if(XYSlist[idx].NSPs == 0) return;
 for(pdx = 0; pdx < XYSlist[idx].NSPs; pdx++)
    if(XYSlist[idx].SPlist[pdx].name!=NULL) free(XYSlist[idx].SPlist[pdx].name);
 free(XYSlist[idx].SPlist);
 XYSlist[idx].SPlist = NULL;
 XYSlist[idx].SizeSPs = 0;
 XYSlist[idx].NSPs = 0;
 return;
}

// Return values for xyzs_new()
#define XYE_SUCCESS 0 // No error. Scan parameters node created OK
#define XYE_MEMFAIL 1 // Failed. Couldn't get memory for the new node.

int xyzs_new(void)
// Adds a new scan parameters node to the XYSlist.
{
 ScanParam* newmem;
 size_t newsize;
 uint32_t idx;

 // 1. Test string placeholder allocation in safe isolation first
 char *tmp_root = calloc(PCS_PATH_MAX, sizeof(char));
 if(tmp_root == NULL){
   show_message("No RAM available for image root name.", "Error: ", MT_ERR, 0);
   return XYE_MEMFAIL;
 }

 // 2. Attempt the master scan profile structure reallocation
 newsize = SizeXYSs + sizeof(ScanParam);
 newmem = realloc(XYSlist, newsize);
 if(newmem == NULL){
   show_message(": Failed to get memory for XYZ Scan parameters struct.\n",
                                                                fnn, MT_ERR, 1);
   free(tmp_root); // Clean up the string copy to prevent memory leaks!
   return XYE_MEMFAIL;
 }

 // 3. TRANSACTION SUCCESS HANDSHAKE: Commit trackers cleanly
 XYSlist = newmem;
 SizeXYSs = newsize;
 idx = NXYSs;
 NXYSs++;

 // 4. Populate clean structural nodes
 XYSlist[idx].Scan_filename[0] = '\0';
 XYSlist[idx].Scan_basepath[0] = '\0';
 XYSlist[idx].ImRoot = tmp_root;
 XYSlist[idx].ImHeight = 0;
 XYSlist[idx].ImWidth = 0;
 XYSlist[idx].ImWidth_stride = 0;
 XYSlist[idx].Saveas_Fmt     = -1;   // -1 = unset   
 XYSlist[idx].ImSize = 0;
 XYSlist[idx].RGBSize = 0;
 XYSlist[idx].xyzs_coords_s[0] = 0; 
 XYSlist[idx].xyzs_coords_s[1] = 0; 
 XYSlist[idx].xyzs_coords_s[2] = 0; 
 XYSlist[idx].xyzs_coords_f[0] = 0; 
 XYSlist[idx].xyzs_coords_f[1] = 0; 
 XYSlist[idx].xyzs_calib_x = 1;
 XYSlist[idx].xyzs_calib_y = 1;
 XYSlist[idx].xyzs_calib_z = 1;
 XYSlist[idx].xyzs_semino_z = 0;
 XYSlist[idx].sp_stride = 1;
 XYSlist[idx].curr_z = 0;
 XYSlist[idx].neighbours_found = 0;
 XYSlist[idx].RenderIdx = 0;


 XYSlist[idx].Stage.maxcalibri_x = 1;
 XYSlist[idx].Stage.maxcalibri_y = 1;
 XYSlist[idx].Stage.maxcalibri_z = 1;
 snprintf(XYSlist[idx].Stage.unitname, 32, "%s", "Unknown");
 XYSlist[idx].Stage.UnitType = 0;
 XYSlist[idx].Stage.Synced_stage = 0;
 for(int m = 0; m < 3; m++) {
     XYSlist[idx].Stage.maxmsdenom[m] = 0;
     XYSlist[idx].Stage.msdenom[m] = 0;
 }
 XYSlist[idx].Stage.x_homed_switch = LIM_UNSET;
 XYSlist[idx].Stage.y_homed_switch = LIM_UNSET;
 XYSlist[idx].Stage.x_dirn1 = XYSlist[idx].Stage.x_dirn2 = -1;
 XYSlist[idx].Stage.y_dirn1 = XYSlist[idx].Stage.y_dirn2 = -1;
 XYSlist[idx].Stage.acc_isd[0]=0;
 XYSlist[idx].Stage.acc_isd[1]=0;
 XYSlist[idx].Stage.acc_acp=0.0;

 // Establish safe un-synchronized hardware defaults!
 XYSlist[idx].Synced_cam = 0;

 // Externally managed pointer reference, must not free()ed inside destructor!
 XYSlist[idx].img = NULL; 
 XYSlist[idx].img_sz = 0;

 // Scan points list 
 XYSlist[idx].SPlist = NULL;
 XYSlist[idx].NSPs = 0;
 XYSlist[idx].SizeSPs = 0;

 return XYE_SUCCESS;
}

void xyzs_delete(uint32_t vidx)
// Safely deletes a single node from the XYSlist array by shifting
// subsequent nodes down.
{
 ScanParam* newmem;
 size_t newsize;

 // 1. Safety Boundary Check
 if (vidx >= NXYSs) {
     show_message(": Attempted to delete an out-of-bounds scan node handle.\n",
                                                                fnn, MT_ERR, 1);
     return;
 }

 // 2. Delete dynamic inner allocations belonging strictly to THIS targeted node
 if(XYSlist[vidx].ImRoot != NULL) {
     free(XYSlist[vidx].ImRoot);
     XYSlist[vidx].ImRoot = NULL;
 }
 sp_listfree(vidx); // Clear any associated scan point matrices inside this node 

 // 3. SHIFT GAP COLLAPSE: Move all elements following vidx down by one slot position!
 // This cleanly closes the array gap before altering the memory allocation boundaries.
 for(uint32_t i = vidx; i < (NXYSs - 1); i++){
     XYSlist[i] = XYSlist[i + 1];
 }

 // 4. Update the structural counter bounds indicator immediately after shifting
 NXYSs--;

 // 5. If we only have SC_CURR and SC_LIVE left, we don't need to shrink
 // further, just return
 if(NXYSs == 0) {
     free(XYSlist);
     XYSlist = NULL;
     SizeXYSs = 0;
     return;
 }

 // 6. Attempt memory truncation safely using our transaction-safe rules
 newsize = NXYSs * sizeof(ScanParam);
 newmem = realloc(XYSlist, newsize);
 if(newmem == NULL){
   // Shrinking failure is entirely harmless! The array elements are already
   // perfectly aligned and closed.
   // We leave XYSlist pointing to the slightly larger buffer safely.
   return;
 }
 
 XYSlist = newmem;
 SizeXYSs = newsize;
 return;
}

void xyzs_listfree(void)
// Frees the list of XY scan parameters
{
 uint32_t idx;

 if(NXYSs == 0) return;
 // We know indeces SC_CURR and SC_LIVE must exist or the program will never
 // have got past the initialisation stages of main. Also we have divested
 // SC_CURR of all internal memory so trying to free internal memory in SC_CURR
 // may well cause a double free error. Thus it is both safe and necessary to
 // start the internal memory freeing loop at SC_LIVE
 for(idx = SC_LIVE; idx < NXYSs; idx++){
    if(XYSlist[idx].ImRoot != NULL) free(XYSlist[idx].ImRoot);
    sp_listfree(idx);          // Clear any pre-existing scan points
 }
 free(XYSlist);
 XYSlist = NULL;
 SizeXYSs = 0;
 NXYSs = 0;
 return;
}

