    int   Frame_Number;  // Forms part of saved image file name
    char *ImRoot;        // Forms part of saved image file name
    int   Frames_to_skip;// Frames to discard before capture.
    int   Av_denom;      // Frames to average.
    int   Imroot_set;    // Lets program know if user has selected an ImRoot.
    int   Saveas_Fmt;    // Indicates the format of grabbed images
    int   PrevCD_Loaded; // Is a preview colour dark field file is loaded? We
                         // use only two flags for this: MASK_NONE and MASK_YRGB
                         // both of which are in pardcapdefs.h 
    int   PrevMask_Loaded;  // Similar to PrevCD_Loaded but for the preview mask
    char Prevfile[PCS_PATH_MAX]; // File name (+/-path] to save preview image
    int  Prevfile_set; // Preview image resolution number
