// Global for TMC DRV_STATUS register
// This is not a 'System reserved variable' because PCS users cannot access this
// directly at all (it is unsigned) but this is used in the TMC_Status_parse()
// function to enable the tmc_status_parse <info_id> <receptor> command to work.
// The TMC_Status_Reg varible is updated with a call to the act_get command when
// the INFO_TMCSTATUS argument is used. The user-supplied receptor variable in
// that case is set with the value cast into a signed int32_t (and the sign of
// that value will indicate the standstill status) but the original unsigned
// value is put into this global so all the other status values can be properly
// parsed.
uint32_t TMC_Status_Reg = 0;
int32_t TMC_Status_parse(int status_item)
// Extracts info_item from the global TMC_Status_Reg and returns it as an
// int32_t assuming the bits have the meanings of the TMC2209 DRV_STATUS
// register.
{
 int32_t presult=0;

 switch(status_item){
  // Normalize single-bit flags to exactly 1 or 0
  case TMC_SI_OVER_TEMP: presult = (TMC_Status_Reg & 0x01) != 0; break;
  case TMC_SI_PREO_TEMP: presult = (TMC_Status_Reg & 0x02) != 0; break;
  case TMC_SI_SHORTGNDA: presult = (TMC_Status_Reg & 0x04) != 0; break;
  case TMC_SI_SHORTGNDB: presult = (TMC_Status_Reg & 0x08) != 0; break;
  case TMC_SI_SHORTSUPA: presult = (TMC_Status_Reg & 0x10) != 0; break;
  case TMC_SI_SHORTSUPB: presult = (TMC_Status_Reg & 0x20) != 0; break;
  case TMC_SI_OPENLOADA: presult = (TMC_Status_Reg & 0x40) != 0; break;
  case TMC_SI_OPENLOADB: presult = (TMC_Status_Reg & 0x80) != 0; break;

  // Multi-bit values
  case TMC_SI_CS_ACTUAL:
   presult = (int32_t)((TMC_Status_Reg >> 16) & 0x1F);
  break;
  case TMC_SI_TEMP_THRS:
   presult = (int32_t)((TMC_Status_Reg >> 8) & 0x0F);
  break;

  // Ensure Bit 31 returns 1, not a negative overflow
  case TMC_SI_STNDSTILL:
   presult = (TMC_Status_Reg & (1UL << 31)) != 0;
  break;

  // If Bit 30 is 0, we are in SpreadCycle (return 1)
  case TMC_SI_SPRDCYCLE:
   presult = (TMC_Status_Reg & (1UL << 30)) == 0;
  break;

  default: break;
 }

 return presult;
}

// Global for TMC CHOPCONF register (analogous to the TMC_Status_Reg variable).
uint32_t TMC_ChopConf_Reg = 0;
int32_t TMC_ChopConf_parse(int chopconf_item)
// Extracts chopconf_item from the global TMC_ChopConf_Reg and returns it as an
// int32_t assuming the bits have the meanings of the TMC2209 CHOPCONF register.
{
  int32_t presult = 0;

  switch(chopconf_item) {
    // Basic 4-bit value (0-15)
    case TMC_CI_TOFFLEVEL:
      presult = (int32_t)(TMC_ChopConf_Reg & 0x0F);
      break;

    // Hysteresis Start: Bits 4-6. Datasheet: Add 1 to value (result 1-8)
    case TMC_CI_HYSTSTART:
      presult = (int32_t)(((TMC_ChopConf_Reg >> 4) & 0x07) + 1);
      break;

    // Hysteresis End: Bits 7-10. Datasheet: Subtract 3 (result -3 to 12)
    case TMC_CI_HYST__END:
      presult = (int32_t)(((TMC_ChopConf_Reg >> 7) & 0x0F) - 3);
      break;

    // Blank Time: Bits 15-16. (0=16, 1=24, 2=36, 3=54 clocks)
    case TMC_CI_CPBLANKTM:
      presult = (int32_t)((TMC_ChopConf_Reg >> 15) & 0x03);
      break;

    // VSENSE: Bit 17. (0=Low sensitivity, 1=High sensitivity)
    case TMC_CI_VSENSITIV:
      presult = (TMC_ChopConf_Reg & (1UL << 17)) != 0;
      break;

    // Microstep Resolution Denominator: Bits 24-27 (MRES)
    // Corrects the TMCStepper lib bug by manually calculating: 256 / (2^MRES)
    case TMC_CI_MRESMSDEN:
      {
        uint8_t mres = (uint8_t)((TMC_ChopConf_Reg >> 24) & 0x0F);
        presult = (int32_t)(256 >> mres);
      }
      break;

    // Interpolation: Bit 28
    case TMC_CI_INTERPOLN:
      presult = (TMC_ChopConf_Reg & (1UL << 28)) != 0;
      break;

    // Double Edge: Bit 29
    case TMC_CI_DOUBLEDGE:
      presult = (TMC_ChopConf_Reg & (1UL << 29)) != 0;
      break;

    // Short to GND Protection Disable: Bit 30
    case TMC_CI_DISSHRTTG:
      presult = (TMC_ChopConf_Reg & (1UL << 30)) != 0;
      break;

    // Short to Vcc Protection Disable: Bit 31
    case TMC_CI_DISSHRTTL:
      presult = (TMC_ChopConf_Reg & (1UL << 31)) != 0;
      break;

    default:
      break;
  }

  return presult;
}

void var_millis_update(void)
// Update the system Millis integer
{
 static struct timespec start_ts;
 static int initialized = 0;
 struct timespec current_ts;

 if (!initialized) {
     clock_gettime(CLOCK_MONOTONIC, &start_ts);
     initialized = 1;
 }

 clock_gettime(CLOCK_MONOTONIC, &current_ts);

 // 1. Calculate total nanoseconds for both as 64-bit integers
 // This avoids the subtraction underflow that caused your ~2 billion ms jumps
 uint64_t start_ns = (uint64_t)start_ts.tv_sec * 1000000000ULL + start_ts.tv_nsec;
 uint64_t current_ns = (uint64_t)current_ts.tv_sec * 1000000000ULL + current_ts.tv_nsec;

 // 2. Subtract to get elapsed nanoseconds, then convert to milliseconds
 uint64_t diff_ms = (current_ns - start_ns) / 1000000;

 // 3. Mask to 31 bits. 
 // This ensures the value is always 0 to 2,147,483,647.
 // When cast to int32_t, the MSB (sign bit) will always be 0.
 Millis = (int32_t)(diff_ms & 0x7FFFFFFF);
}
             
void var_datetime_update(void)
// Update the system variable DateTime string 
{
 time_t tmt   = time(NULL);
 struct tm ct = *localtime(&tmt);

 if(tmt==-1)
  sprintf(DateTime,"Sys.clock_error");
 else {
   if(strftime(DateTime, 16,"%Y%m%d_%H%M%S",&ct) == 0){
     sprintf(DateTime,"strftime__error");
   }
  }

  return;
}

void cmd_milliduration(int32_t before, int32_t *var_val_ptr)
// Calculates the number of milliseconds that have elapsed from before to now.
{
 // 1. Get the absolute current time using the Millis updated update function
 var_millis_update(); 
 int32_t current = Millis;

 // 2. Calculate the difference
 // If current < before (rollover occurred), the result of subtraction
 // will be negative. The mask & 0x7FFFFFFF fixes this automatically.
 int32_t duration = (current - before) & 0x7FFFFFFF;

 // 3. Store it back into the script's variable
 *var_val_ptr = duration;
}

int32_t var_preval_update(void)
// Returns the required value from PreviewImg at position PreviewPos and
// increments PreviewPos according to PreviewInc
{
 int32_t retval;
 retval = (int32_t)PreviewImg[PreviewPos];
 PreviewPos += PreviewInc;
 // Wrap if reaches PreviewImg_rgb_size
 if (PreviewPos >= PreviewImg_rgb_size) {
     PreviewPos -= PreviewImg_rgb_size;
 }
 return retval;
}

