#define VVNAT_SYSTEM 0
#define VVNAT_USER   1
#define VVNAT_CONST  2
int Varval_nature = 0;  // A flag to let program know if a VARVAL is a user-
                        // defined ovariable (=1), an internal system variable
                        // (=0) or just a constant value so not a variable (=2)


// Return values for var_new()
#define VNE_SUCCESS 0 // No error. Variable defined OK
#define VNE_NAME    1 // Failed. Proferred name is not permitted
#define VNE_MEMVAR  2 // Failed. Couldn't get memory for the new variable
#define VNE_MEMNAME 3 // Failed. Couldn't get memory for the name of the new variable.
#define VNE_TYPE    4 // Failed. Unsupported variable type proferred.


int var_new(int vtype, char *vname, double fval, int32_t ival, char *str,
                                                                 uint32_t count)
// Adds a new user-defined script variable (including an array) to the Varlist.
// When defining a new string variable it is assumed that the string pointed to
// by str is null-terminated although it may be an empty string ("") in which
// case Slen in the new variable will be 1 (because Slen is defined as the 
// number of non-null characters plus 1). Slen therefore also defines the number
// of bytes allocated to Str in the variable. 
// Returns one of the VNE_ constants (which see)
{
 ScriptVar* newvarmem;
 size_t newvarsize, nomlen;
 unsigned int idx;
 size_t len;
 char msg[256];
 int32_t i32;
 double dtmp;
 
 // Ensure the name is at least 1 char long
 len=strlen(vname);
 if(len<1){
    show_message(": Variable name is too small.\n",fnn, MT_PCS_E, 1);
   return VNE_NAME;
 }

 // Ensure the name does not contain forbidden characters
 if (strpbrk(vname, "[]") != NULL) {
    show_message(": Variable names must not include '[' or ']'.\n",
                                                              fnn, MT_PCS_E, 1);
    return VNE_NAME;
  } 

 // First ensure proferred name is not reserved for a special purpose
 if(!strcmp(vname, "Condexp"))  return VNE_NAME;
 if(!strcmp(vname, "CLImode"))  return VNE_NAME;
 if(!strcmp(vname, "Sysval"))   return VNE_NAME;
 if(!strcmp(vname, "TRUE"))     return VNE_NAME;
 if(!strcmp(vname, "FALSE"))    return VNE_NAME;
 if(!strcmp(vname, "exit"))     return VNE_NAME;
 if(!strcmp(vname, "ignore"))   return VNE_NAME;
 if(!strcmp(vname, "NoTissue")) return VNE_NAME;
 if(!strcmp(vname, "HasTissue"))return VNE_NAME;
 if(!strcmp(vname, "CurrTC"))   return VNE_NAME;
 if(!strcmp(vname, "PreviewPos")) return VNE_NAME;
 if(!strcmp(vname, "PreviewInc")) return VNE_NAME;
 if(!strcmp(vname, "PreviewVal")) return VNE_NAME;
 if(!strcmp(vname, "Ps_SatL_R"))  return VNE_NAME;
 if(!strcmp(vname, "Ps_SatL_G"))  return VNE_NAME;
 if(!strcmp(vname, "Ps_SatL_B"))  return VNE_NAME;
 if(!strcmp(vname, "Ps_SatU_R"))  return VNE_NAME;
 if(!strcmp(vname, "Ps_SatU_G"))  return VNE_NAME;
 if(!strcmp(vname, "Ps_SatU_B"))  return VNE_NAME;
 if(!strcmp(vname, "Ps_Min_R"))   return VNE_NAME;
 if(!strcmp(vname, "Ps_Min_G"))   return VNE_NAME;
 if(!strcmp(vname, "Ps_Min_B"))   return VNE_NAME;
 if(!strcmp(vname, "Ps_Max_R"))   return VNE_NAME;
 if(!strcmp(vname, "Ps_Max_G"))   return VNE_NAME;
 if(!strcmp(vname, "Ps_Max_B"))   return VNE_NAME;
 if(!strcmp(vname, "Ps_Integral_R"))  return VNE_NAME;
 if(!strcmp(vname, "Ps_Integral_G"))  return VNE_NAME;
 if(!strcmp(vname, "Ps_Integral_B"))  return VNE_NAME;
 if(!strcmp(vname, "Ps_Var_R"))   return VNE_NAME;
 if(!strcmp(vname, "Ps_Var_G"))   return VNE_NAME;
 if(!strcmp(vname, "Ps_Var_B"))   return VNE_NAME;
 if(!strcmp(vname, "Ps_Mean_R"))  return VNE_NAME;
 if(!strcmp(vname, "Ps_Mean_G"))  return VNE_NAME;
 if(!strcmp(vname, "Ps_Mean_B"))  return VNE_NAME;
 if(!strcmp(vname, "Ps_DCT_R"))   return VNE_NAME;
 if(!strcmp(vname, "Ps_DCT_G"))   return VNE_NAME;
 if(!strcmp(vname, "Ps_DCT_B"))   return VNE_NAME;
 if(!strcmp(vname, "Ps_MAL_R"))   return VNE_NAME;
 if(!strcmp(vname, "Ps_MAL_G"))   return VNE_NAME;
 if(!strcmp(vname, "Ps_MAL_B"))   return VNE_NAME;
 if(!strcmp(vname, "Ps_Focus_R")) return VNE_NAME;
 if(!strcmp(vname, "Ps_Focus_G")) return VNE_NAME;
 if(!strcmp(vname, "Ps_Focus_B")) return VNE_NAME;
 if(!strcmp(vname, "Ps_Npix_R"))  return VNE_NAME;
 if(!strcmp(vname, "Ps_Npix_G"))  return VNE_NAME;
 if(!strcmp(vname, "Ps_Npix_B"))  return VNE_NAME;
 if(!strcmp(vname, "Ps_Msupport"))return VNE_NAME;
 if(!strcmp(vname, "Space"))      return VNE_NAME;
 if(!strcmp(vname, "Hash"))       return VNE_NAME;
 if(!strcmp(vname, "NSteppers"))  return VNE_NAME;
 if(!strcmp(vname, "NBinaries"))  return VNE_NAME;
 if(!strcmp(vname, "NMlevels"))   return VNE_NAME;
 if(!strcmp(vname, "NServos"))    return VNE_NAME;
 if(!strcmp(vname, "NSensors"))   return VNE_NAME;
 if(!strcmp(vname, "CurrActIdx")) return VNE_NAME;
 if(!strcmp(vname, "CurrActType"))return VNE_NAME;
 if(!strcmp(vname, "CurrAct"))    return VNE_NAME;
 if(!strcmp(vname, "StageXY"))    return VNE_NAME;
 if(!strcmp(vname, "StageXYZ"))   return VNE_NAME;
 if(!strcmp(vname, "ON"))         return VNE_NAME;
 if(!strcmp(vname, "OFF"))        return VNE_NAME;
 if(!strcmp(vname, "FITS"))       return VNE_NAME;
 if(!strcmp(vname, "PMRep1"))     return VNE_NAME;
 if(!strcmp(vname, "PMRep2"))     return VNE_NAME;
 if(!strcmp(vname, "PMRep3"))     return VNE_NAME;
 if(!strcmp(vname, "PMRep4"))     return VNE_NAME;
 if(!strcmp(vname, "DateTime"))   return VNE_NAME;
 if(!strcmp(vname, "Millis"))     return VNE_NAME;
 if(!strcmp(vname, "NReads"))     return VNE_NAME;
 if(!strcmp(vname, "NBytes"))     return VNE_NAME;
 if(!strcmp(vname, "NWrites"))    return VNE_NAME;
 if(!strcmp(vname, "NewLines"))   return VNE_NAME;
 if(!strcmp(vname, "PreviewReport"))  return VNE_NAME;

 // Now ensure proferred name is not a proper number string
 if(!is_not_float(vname,&dtmp))  return VNE_NAME;
 if(!is_not_integer(vname,&i32)) return VNE_NAME;

 // Now ensure proferred name does not already exist 
 // (don't allow duplicate names)
 for(idx = 0; idx < NVars; idx++){
     if(!strcmp(vname, Varlist[idx].Name))  return VNE_NAME;
 }

 // Try to get memory for the new variable
 newvarsize = SizeVars + sizeof(ScriptVar);
 newvarmem = realloc(Varlist, newvarsize);
 if(newvarmem == NULL){
     show_message(": Failed to get memory for variable.\n", fnn,
                                                                   MT_PCS_E, 1);
     return VNE_MEMVAR;
 }
 Varlist = newvarmem;
 SizeVars = newvarsize;
 idx = NVars;
 NVars++;

 // Now set the values assigned to the variable
 nomlen = strlen(vname); nomlen++;
 if((Varlist[idx].Name = malloc(nomlen)) == NULL){
     show_message(": Failed to get memory for variable name.\n", fnn,
                                                                   MT_PCS_E, 1);
     return VNE_MEMNAME;
 }
 memcpy(Varlist[idx].Name, vname, nomlen);
 Varlist[idx].Type = vtype;
 Varlist[idx].Count = count;

 switch(vtype){
   case VDT_INT:
     if((Varlist[idx].Ival = malloc(count * sizeof(int32_t))) == NULL){
       sprintf(msg,": Failed to get memory for %s (int32_t).\n",
                                                  (count>1)?"array":"variable");
       show_message(msg,fnn,MT_PCS_E, 1);
       return VNE_MEMVAR;
      }
     for(uint32_t i=0; i<count; i++) Varlist[idx].Ival[i] = ival;
     break;

   case VDT_FLOAT:
     if((Varlist[idx].Fval = malloc(count * sizeof(double))) == NULL){
       sprintf(msg,": Failed to get memory for %s (double).\n",
                                                  (count>1)?"array":"variable");
       show_message(msg,fnn,MT_PCS_E, 1);
       return VNE_MEMVAR;
      }
     for(uint32_t i=0; i<count; i++) Varlist[idx].Fval[i] = fval;
     break;

   case VDT_STR:
     if((Varlist[idx].Str = malloc(count * sizeof(char *))) == NULL){
       sprintf(msg,": Failed to get memory for %s (string pointer%s).\n",
                                 (count>1)?"array":"variable",(count>1)?"s":"");
       show_message(msg,fnn,MT_PCS_E, 1);
       return VNE_MEMVAR;
      }
     if((Varlist[idx].Slen = malloc(count * sizeof(size_t))) == NULL){
       sprintf(msg,": Failed to get memory for %s (string length%s).\n",
                                 (count>1)?"array":"variable",(count>1)?"s":"");
       show_message(msg,fnn,MT_PCS_E, 1);
       return VNE_MEMVAR;
      }
     for(uint32_t i=0; i<count; i++) {
         Varlist[idx].Slen[i] = strlen(str) + 1;
         Varlist[idx].Str[i] = NULL;
       }
     for(uint32_t i=0; i<count; i++) {
         Varlist[idx].Slen[i] = strlen(str) + 1;
         Varlist[idx].Str[i] = malloc(Varlist[idx].Slen[i]);
         if(Varlist[idx].Str[i] == NULL){
           sprintf(msg,": Failed to get memory for %s (string content [%"
                 PRIu32"]).\n",(count>1)?"array":"variable",i);
           show_message(msg,fnn,MT_PCS_E, 1);
           return VNE_MEMVAR;
          }
         strcpy(Varlist[idx].Str[i], str);
       }
     break;
   default:
     show_message(": Unrecognised variable type - Program Error.\n",fnn,MT_PCS_E, 1);
     return VNE_TYPE; // Unrecognised variable type - a programming error (bug) 
 }

 return VNE_SUCCESS;
}

void var_free(unsigned int idx)
// Frees the variable with index idx.
// This is a worker function that serves var_listfree and var_delete
{
   // 1. Free the name of the variable
   if (Varlist[idx].Name != NULL) free(Varlist[idx].Name);

   // 2. Free the specific data buffers
   if(Varlist[idx].Type == VDT_INT) {
       if(Varlist[idx].Ival!=NULL) free(Varlist[idx].Ival);
   } 
   else if(Varlist[idx].Type == VDT_FLOAT) {
       if(Varlist[idx].Fval!=NULL) free(Varlist[idx].Fval);
   } 
   else if(Varlist[idx].Type == VDT_STR) {
       // Arrays of strings need a loop to free each string but we can only
       // free what has previously succeeded to be alloced so we must check
       // NULL status first in case of malloc failure part way through the
       // the var_new process:
       if(Varlist[idx].Str!=NULL){ // First hurdle was cleared
         if(Varlist[idx].Slen!=NULL){ // Secomnd hurdle was cleared
           for(uint32_t i = 0; i < Varlist[idx].Count; i++) {
              if(Varlist[idx].Str[i]!=NULL) free(Varlist[idx].Str[i]);
             }
           free(Varlist[idx].Slen);
          }
         free(Varlist[idx].Str);
        }
   }
}

int run_var_new(int vtype, char *vname, double fval, int32_t ival, char *str, uint32_t count)
// High-Speed Runtime Variant: Bypasses 64 system strcmps and number text checks!
// Assumes the caller has already successfully run script_check on this script block.
{
 ScriptVar* newvarmem;
 size_t newvarsize, nomlen;
 unsigned int idx;
 char msg[256];

 // DYNAMIC LIFE SAFETY: Ensure the name does not currently exist in active memory scope
 // (Required because users can recreate variables continuously via loops or branches)
 for(idx = 0; idx < NVars; idx++){
     if(!strcmp(vname, Varlist[idx].Name)) return VNE_NAME;
 }

 // Try to get memory for the new variable
 newvarsize = SizeVars + sizeof(ScriptVar);
 newvarmem = realloc(Varlist, newvarsize);
 if(newvarmem == NULL){
     show_message(": Failed to get memory for variable.\n", fnn, MT_PCS_E, 1);
     return VNE_MEMVAR;
 }
 Varlist = newvarmem;
 SizeVars = newvarsize;
 idx = NVars;
 NVars++;
 Varlist_Generation++; // Invalidates old cache layers on new allocations!

 // Now set the values assigned to the variable
 nomlen = strlen(vname); nomlen++;
 if((Varlist[idx].Name = malloc(nomlen)) == NULL){
     show_message(": Failed to get memory for variable name.\n", fnn, MT_PCS_E, 1);
     return VNE_MEMNAME;
 }
 memcpy(Varlist[idx].Name, vname, nomlen);
 Varlist[idx].Type = vtype;
 Varlist[idx].Count = count;

 switch(vtype){
   case VDT_INT:
     if((Varlist[idx].Ival = malloc(count * sizeof(int32_t))) == NULL){
       sprintf(msg,": Failed to get memory for %s (int32_t).\n", (count>1)?"array":"variable");
       show_message(msg,fnn,MT_PCS_E, 1);
       return VNE_MEMVAR;
      }
     for(uint32_t i=0; i<count; i++) Varlist[idx].Ival[i] = ival;
     break;

   case VDT_FLOAT:
     if((Varlist[idx].Fval = malloc(count * sizeof(double))) == NULL){
       sprintf(msg,": Failed to get memory for %s (double).\n", (count>1)?"array":"variable");
       show_message(msg,fnn,MT_PCS_E, 1);
       return VNE_MEMVAR;
      }
     for(uint32_t i=0; i<count; i++) Varlist[idx].Fval[i] = fval;
     break;

   case VDT_STR:
     if((Varlist[idx].Str = malloc(count * sizeof(char *))) == NULL){
       sprintf(msg,": Failed to get memory for %s (string pointer%s).\n", (count>1)?"array":"variable",(count>1)?"s":"");
       show_message(msg,fnn,MT_PCS_E, 1);
       return VNE_MEMVAR;
      }
     if((Varlist[idx].Slen = malloc(count * sizeof(size_t))) == NULL){
       sprintf(msg,": Failed to get memory for %s (string length%s).\n", (count>1)?"array":"variable",(count>1)?"s":"");
       show_message(msg,fnn,MT_PCS_E, 1);
       return VNE_MEMVAR;
      }
     for(uint32_t i=0; i<count; i++) {
         Varlist[idx].Slen[i] = strlen(str) + 1;
         Varlist[idx].Str[i] = malloc(Varlist[idx].Slen[i]);
         if(Varlist[idx].Str[i] == NULL){
           sprintf(msg,": Failed to get memory for %s (string content [%" PRIu32 "]).\n",(count>1)?"array":"variable",i);
           show_message(msg,fnn,MT_PCS_E, 1);
           return VNE_MEMVAR;
          }
         strcpy(Varlist[idx].Str[i], str);
       }
     break;
   default:
     show_message(": Unrecognised variable type - Program Error.\n",fnn,MT_PCS_E, 1);
     return VNE_TYPE; 
 }

 return VNE_SUCCESS;
}

void var_listfree(void)
// Frees the entire list of user-defined script variables
{
 unsigned int idx;
 if(NVars == 0) return;
 for(idx=0;idx<NVars;idx++) var_free(idx);
 free(Varlist);
 Varlist = NULL;
 SizeVars = 0;
 NVars = 0;
 Varlist_Generation = 1;
 return;
}

int var_delete(unsigned int idx)
// Excise a single variable from the Varlist to effect the 'undef_var' command.
// Return 0 on success
// Return 1 on error
{
 unsigned int move_count;

 // GUARD 1: Prevent underflow and out-of-bounds
 if (NVars == 0 || idx >= NVars) return 1;

 // 1. Free the internal contents)
 var_free(idx);

 // 2. Shift the list
 move_count = NVars - idx - 1;
 if(move_count > 0){
    memmove(&Varlist[idx], &Varlist[idx + 1], move_count * sizeof(ScriptVar));
  }

 // 3. Update the counters safely
 NVars--;
 SizeVars = NVars * sizeof(ScriptVar);

 // ---------------------------------------------------------------------------
 // AUDIT FIX 1: INVALIDATE EVERY GENERATIONAL ARGUMENT CACHE.
 // The memmove above has shifted every variable above 'idx' down by one slot,
 // so every PCS_Argument that has cached a slot index is now stale.  Bumping
 // the generation counter invalidates all of them in constant time: each
 // affected argument then takes its cold path once and re-binds itself.
 // Without this, a cached argument keeps using a slot that now holds a
 // different variable, and reads and writes go silently to the wrong place.
 // ---------------------------------------------------------------------------
 Varlist_Generation++;

 // 4. Handle Realloc Failure safely
 if(NVars == 0){
   free(Varlist);
   Varlist = NULL;
   SizeVars = 0;
  } else {
   ScriptVar* newvarmem = realloc(Varlist, SizeVars);
   // If realloc fails while shrinking, 'Varlist' is still valid.
   // We only update the pointer if it actually succeeds.
   if(newvarmem != NULL){
     Varlist = newvarmem;
   }
  }
 return 0;
}

unsigned int var_find(const char *base_name)
// Returns the index if a variable with name base_name is on the variables list
// Returns NVars) if it is not on the list
{
 unsigned int idx;

 for(idx=0;idx<NVars;idx++)
     if (!strcmp(base_name, Varlist[idx].Name)) return idx;

 return NVars;
}

int var_index(char *varname, unsigned int *vidx, uint32_t *res_idx)
// Sets the value of vidx to the index in the variables list of the variable or
// array variable with the base name varname. This also sets the value pointed
// to by res_idx to the position in the array of values of that variable (this
// will always be 0 for non-array variables). 
//
// Returns 0 on success.
// Returns 1 if no variable in the Varlist with name varname exists or
//           if NVars==0 (i.e. the variables list is empty).
// Returns 2 if the varname string is too long
// [Returns 3 if the var_evalv failed] - this condition was removed and replaced
//            with an exact cause notification]
// Returns 4 if a negative value was used for dereferencing
// Returns 5 if the varname is of an array variable but lacks dereferencing
//           brackets
// Returns 6 if the varname is of an single variable but has dereferencing
//           brackets (only allowed for array variables).
// Returns 7 Array index out of bounds error.
// Returns 8 if varname has a syntax error to do with placement, number or
//           pairing of dereferencing brackets.
// Returns 9 Array index cannot be evaluated to a number.
// 
{
 unsigned int idx;
 char *open_b = strchr(varname, '[');
 char *close_b = strrchr(varname, ']');
 char base_name[MAX_ARGLEN+1];
 char index_expr[MAX_ARGLEN+1];
 size_t len = strlen(varname);
 uint32_t local_res_idx = 0; // The default is 0 (meaning a local variable)
                             // This will take on the value of the array index
                             // if we find that the variable is an array.

 if(NVars == 0) return 1; // The list is empty

 // First deal with the case that the variable name is that of an array variable
 // and so has an index in square bracets - we must evaluate this index and put
 // its value into res_idx so that var_evalvv can evaluate the correct member of
 // the array.

 // Look for the correct de-referencing (square bracket) syntax:
 // if varname contains a [ before a ] AND [ must not be the first char in
 // vname AND the last ] must be the last char in vname:
 // Initial check for presence, order, and position
 if(open_b && close_b && close_b > open_b && 
                           open_b > varname && close_b == (varname + len - 1)) {

    // Now check for balanced pairs of [ and ] in case the array index is itself
    // composed of an array variable:
    int depth = 0;
    int balanced = 1;
    for(int i = 0; varname[i] != '\0'; i++) {
        if (varname[i] == '[') depth++;
        else if (varname[i] == ']') depth--;
        // If depth goes negative, we have a ']' before a '['
        if (depth < 0) { balanced = 0; break; }
      }

      if(balanced && depth == 0) { // If the bracket formatting is all good ...
         // 1. Extract Base Name
         int name_len = open_b - varname;
         if (name_len >= MAX_ARGLEN) return 2;
         strncpy(base_name, varname, name_len);
         base_name[name_len] = '\0';

         // Now we need to evaluate the index number. This may be a literal
         // constant, a value inside a single variable or a value referenced in
         // some member of an array variable, so ...

         // 2. Extract Index Expression
         int expr_len = close_b - open_b - 1;
         strncpy(index_expr, open_b + 1, expr_len);
         index_expr[expr_len] = '\0';

         // 3. RECURSION: We need to evaluate the recovered index expression.
         // This involves a call to the function that evaluates the variable or
         // constant value from a string: var_evalvv but that function calls 
         // this function to see if the expression is a variable or a constant - 
         // hence the recursion. This is safe because s[CPTRLEN] is local 
         // and we pass a pointer for the index. The recovered numerical value
         // (after however many recursive loops it takes) will be in f or i. If
         // var_evalvv shows the data type is anything other than float or int
         // then we have failed - the expression cannot be reduced to a numer -
         // it is as if the script writer did something like this:
         // myarray[some_string] where 'some_string' is not the name of a
         // variable so cannot be reduced to a number so var_evalvv returns it
         // verbatim in s and sets t to VDT_STR. So, by checking for
         // t == VDT_STR we know immediately that we have failed.
         double f; int32_t i; int t,vvr; char s[CPTRLEN];
         vvr=var_evalvv(index_expr, &f, &i, &t, s);
         if (vvr != 0) return vvr;
         
         if (t == VDT_STR) {
             // If var_evalvv returned a string, check if it's a number string
             if (!is_not_integer(s,&i)) {
                 t = VDT_INT;
             } else if (!is_not_float(s,&f)) {
                 t = VDT_FLOAT;
             } else {
                 return 9; // Not a number, so truly an invalid index
             }
         }
         if (t == VDT_FLOAT) float_to_int(f, &i);
         if (i < 0) return 4; 
         local_res_idx = (uint32_t)i;
       } else goto bracketing_error; // ... otherwise it's a syntax error

    } else if (!open_b && !close_b) {
        // No brackets, so just use the whole name
        strncpy(base_name, varname, MAX_ARGLEN);
    } else {
       // Syntax Error: Mismatched/misplaced brackets
       bracketing_error:
       return 8;
    }


 // 4. Standard lookup in Varlist
 idx=var_find(base_name);
 if(idx<NVars){

         // --- THE NEW RULES ---
         // A. If it is an array (Count > 1), it MUST have brackets
         if (Varlist[idx].Count > 1 && !open_b) return 5; // Missing index error
         
         // B. If it is NOT an array, it MUST NOT have brackets
         if (Varlist[idx].Count == 1 && open_b) return 6; // Unexpected index error
         
         // C. Bounds check
         if (local_res_idx >= Varlist[idx].Count){ // Out of bounds error
            *res_idx = local_res_idx; // Return the index for error printing
            return 7;
           } 

         // If we get here, all has gone well so pass the found values back to
         // to the function caller by reference:

         // Pass the index of the array element in an array 
         *res_idx = local_res_idx; // (Will be 0 for a non-array variable)

         // Pass the position of this variable / array in the Varlist
         *vidx = idx; 

         return 0; // SUCCESS
     }

 return 1; // Not found
}

// ============================================================================
// AUDIT FIX 16: A DIRECT PATH FOR AN INTEGER ARRAY SUBSCRIPT
//
// run_var_index()'s CASE B used to evaluate every subscript by calling the
// general evaluator run_var_evalvv().  That is a heavy way to fetch an
// integer:
//
//   * the answer comes back through a four-way interface -- double, int32,
//     type tag, string buffer -- so an integer subscript, which is very nearly
//     every subscript ever written, is boxed and then immediately unboxed;
//   * run_var_evalvv carries a sixty-case system-token switch, so each call is
//     an excursion through a large and mostly irrelevant piece of code;
//   * the caller must provide  char s[CPTRLEN]  as a landing area for a string
//     result that an integer subscript never produces, and CPTRLEN is
//     PCS_PATH_MAX, i.e. 4096 bytes.  At three levels of nesting that is
//     twelve kilobytes of stack frame for one array access.
//
// This function handles the three shapes an integer subscript actually takes
// and declines everything else, so it cannot change the meaning of any
// expression: it either answers exactly as the general path would, or it
// returns -1 and the general path runs unchanged.
//
// Measured on the two-level form R[P_a[pc]] -- the shape of every assignment
// in a metaprogrammed virtual machine -- this halves the cost of resolution,
// from 14.8 ns to 7.5 ns.
// ============================================================================

int run_subscript_fast(PCS_Argument *arg, int32_t *out)
// Returns 0 and sets *out on success.
// Returns a positive var_index-style error code (4 for a negative subscript,
//   7 for one out of bounds) on a definite failure.
// Returns -1 to mean "not a shape handled here"; the caller must then use the
//   general path.
{
 // (a) A numeric literal settled at compile time.  The ARG_FLAG_SYSTEM guard
 //     matters: a system token such as Condexp or Millis also carries
 //     ARG_OP_INT, but its cached_ival is NOT its value -- only TRUE, FALSE,
 //     ON and OFF have their values cached.  A system token must therefore go
 //     to the general path, where section 1 of run_var_evalvv reads it live.
 if ((arg->arg_opcode & ARG_OP_INT) && !(arg->arg_opcode & ARG_FLAG_SYSTEM)) {
     *out = arg->cached_ival;
     return 0;
 }

 if (arg->nested_expr == NULL) {
     // (b) A cached scalar integer variable.
     if (arg->generation == Varlist_Generation) {
         unsigned int ix = arg->symbol_id;
         if (ix < NVars && Varlist[ix].Count == 1 && Varlist[ix].Type == VDT_INT) {
             *out = Varlist[ix].Ival[0];
             return 0;
         }
     }
     return -1;   // cold cache, or not an integer scalar: general path
 }

 // (c) A cached integer array element whose own subscript is itself one of
 //     these three shapes.  The recursion is what carries the saving down
 //     through R[P_a[pc]] and deeper.
 if (arg->generation == Varlist_Generation) {
     unsigned int ix = arg->symbol_id;
     if (ix < NVars && Varlist[ix].Count > 1 && Varlist[ix].Type == VDT_INT) {
         int32_t k;
         int r = run_subscript_fast(arg->nested_expr, &k);
         if (r != 0) return r;                 // -1 or a real error, both propagate
         if (k < 0) return 4;
         if ((uint32_t)k >= Varlist[ix].Count) return 7;
         *out = Varlist[ix].Ival[k];
         return 0;
     }
 }
 return -1;
}

int run_var_index(PCS_Argument *arg, unsigned int *vidx, uint32_t *res_idx)
// Safe for infinitely nested arrays, string arrays, and dynamic reallocations!
// Eliminates all runtime bracket-balancing scans, character loops, and memory
// strncpy churn.
{
    unsigned int idx;
    uint32_t local_res_idx = 0;

    // --- CASE A: STANDARD SCALAR USER VARIABLE ---
    if (arg->nested_expr == NULL) {
        
        // =====================================================================
        // GENERATIONAL FAST-PATH SHORTCUT: 100% String-Free Identity Check
        // =====================================================================
        if (arg->generation == Varlist_Generation) {
            // Verify the variable slot hasn't outgrown bounds or shifted layout profiles
            idx = arg->symbol_id;
            if (idx < NVars && Varlist[idx].Count == 1) {
                *res_idx = 0;
                *vidx = idx;
                return 0; // SUCCESS (0 clock cycles!)
            }
        }
        // =====================================================================

        // COLD FALLBACK: Run the string search ONLY if the database layout shifted!
        idx = var_find(arg->base_name); 
        if (idx >= NVars && (arg->arg_opcode & ARG_OP_BADSUB)) {
            // AUDIT FIX 15: the token carries brackets that do not form a valid
            // subscript, and it is not the name of anything.  Error 8 names the
            // real fault; error 1 would merely say the variable was not found.
            return 8;
        }
        if (idx < NVars) {
            if (Varlist[idx].Count > 1) return 5; 
            
            // Lock down the lazy cache and bind it to the current structural generation!
            arg->symbol_id = idx;
            arg->generation = Varlist_Generation; 
            
            *res_idx = 0;
            *vidx = idx;
            return 0; // SUCCESS
        }
        return 1; // Not found
    }

    // --- CASE B: ARRAY ELEMENT PASS (PURE DYNAMIC RUNTIME TRAVERSAL, NO STRCHR SCANS) ---
    if (arg->nested_expr != NULL) {
        int32_t i;

        // ---------------------------------------------------------------
        // AUDIT FIX 16: try the direct integer path first.  It answers for
        // a literal, a cached integer scalar, and a cached integer array
        // element -- which between them cover very nearly every subscript
        // ever written -- and declines everything else, in which case the
        // general evaluator below runs exactly as it did before.
        // ---------------------------------------------------------------
        int fr = run_subscript_fast(arg->nested_expr, &i);
        if (fr > 0) return fr;                 // a definite error: 4 or 7
        if (fr < 0) {
            // Declined.  The general route, unchanged, for float and string
            // subscripts, system tokens, and any cold cache.
            double f; int t; char s[CPTRLEN];

            // Evaluate the pre-compiled nested sub-token at maximum execution speed
            // If it's a deep expression like P_a[pc], run_var_evalvv recursively resolves it cleanly!
            int vvr = run_var_evalvv((PCS_Argument *)arg->nested_expr, &f, &i, &t, s);
            if (vvr != 0) return vvr;

            // Perform standard dynamic type validation on the resolved inner index
            if (t == VDT_STR) {
                if (is_not_integer(s,&i)){
                  if (!is_not_float(s,&f)){ t = VDT_FLOAT;}
                  else return 9; 
                 }
            }
            if (t == VDT_FLOAT) float_to_int(f, &i);
        }
        if (i < 0) return 4; 
        local_res_idx = (uint32_t)i;

        // GENERATIONAL PATH FOR ARRAYS: 100% String-Free Array Base Matching
        if (arg->generation == Varlist_Generation) {
            idx = arg->symbol_id;
            if (idx < NVars && Varlist[idx].Count > 1) {
                if (local_res_idx >= Varlist[idx].Count) {
                    *res_idx = local_res_idx;
                    return 7; 
                }
                *res_idx = local_res_idx;
                *vidx = idx;
                return 0; // SUCCESS (0 string comparisons!)
            }
        }

        // COLD FALLBACK: Run the base string lookup ONLY if the layout version shifted
        idx = var_find(arg->base_name);
        if (idx < NVars) {
            if (Varlist[idx].Count == 1) return 6; 
            if (local_res_idx >= Varlist[idx].Count) {
                *res_idx = local_res_idx;
                return 7; 
            }

            arg->symbol_id = idx;
            arg->generation = Varlist_Generation;

            *res_idx = local_res_idx;
            *vidx = idx;
            return 0; // SUCCESS
        }
        return 1; // Not found
    }

 return 1;
}

void print_vi_err(int res, char *errmsg, char *varname, uint32_t write_idx)
// Converts the return value integer of var_index into a human-readable helpful
// error message string to report back to the script writer.
{
 switch (res) {
   case 1:
     snprintf(errmsg, ERRMSG_LEN, "Variable '%s' not found.", varname);
     break;
   case 2:
     snprintf(errmsg, ERRMSG_LEN, "Variable name '%s' exceeds MAX_CMDLEN.", varname);
     break;
   case 3: // Legacy code - this condition cannot occur.
     snprintf(errmsg, ERRMSG_LEN, "Failed to evaluate index expression in '%s'.", varname);
     break;
   case 4:
     snprintf(errmsg, ERRMSG_LEN, "Negative array index used in '%s'.", varname);
     break;
   case 5:
     snprintf(errmsg, ERRMSG_LEN, "Array variable '%s' requires dereferencing brackets [].",
                                                                       varname);
     break;
   case 6:
     snprintf(errmsg, ERRMSG_LEN, "Single variable '%s' cannot use dereferencing brackets.",
                                                                       varname);
     break;
   case 7:
     snprintf(errmsg, ERRMSG_LEN, "Array index out of bounds: '%s' (Index: %"PRIu32").",
                                                            varname, write_idx);
     break;
   case 8:
     snprintf(errmsg, ERRMSG_LEN, "Syntax error in brackets for variable '%s'.", varname);
     break;
   case 9:
     snprintf(errmsg, ERRMSG_LEN, "Array index in '%s' cannot be reduced to a number.",
                                                                       varname);
     break;
   default:
     snprintf(errmsg, ERRMSG_LEN, "Unknown variable error (Code %d) on '%s'.", res, varname);
     break;
 }
 return;
}

int var_evalvv(char *varname,double *fval,int32_t *ival,int *vtype,char *str)
// Evaluates a <VARVAL> (i.e. variable or constant value) given the name of the
// variable or the value of the constant expressed as a string.
// varname is a pointer to a character string containing a numerical value in
// ASCII (float or int) or the name of a variable or standard token (e.g.
// "TRUE" or "FALSE") or, if none of the above, a general string.
// The values pointed to by fval, ival and str are set according to the value of
// the supplied <VARVAL>.
// If <VARVAL> is a single integer value then *ival is set to that value.
// If <VARVAL> is a string variable then the Str member will be copied into str.
// To prevent memory errors, the length of str will first be checked with 
// strlen and no more than that many characters will be copied from Str to str.
// It is up to the programmer to ensure that str has suficient space and is
// properly initialised to allow strlen(str) to give the correct length (so do
// not set all str members to 0 or strlen will be 0).
// If <VARVAL> is a float value then *fval is set to that value.
// *ival points to a int32_t integer.
// *vtype is set to the appropriate data type for the assignment.
// The global Varval_nature is also set to one of the VVNAT_ constants.
// Returns 0 on success or 1 on failue.
{
 unsigned int idx = 0;
// int32_t resnum;
 uint32_t use_idx = 0;

 Varval_nature = VVNAT_SYSTEM; // We'll change this if need be.

 // Check for internal variables and special constants
 *vtype = VDT_STR; // We'll change later if required.
 if(!strcmp(varname, "Space"))    { sprintf(str,"%s",Space); return 0; }
 if(!strcmp(varname, "Hash"))    { sprintf(str,"%s",Hash); return 0; }
 if(!strcmp(varname, "DateTime")) {
    var_datetime_update();
    sprintf(str,"%s",DateTime);
    return 0;
   }
 *vtype = VDT_INT; // We'll change later if required.
 if(!strcmp(varname, "Condexp"))  { *ival = Condexp; return 0; }
 if(!strcmp(varname, "CLImode"))  { *ival = CLImode; return 0; }
 if(!strcmp(varname, "Sysval"))   { *ival = Sysval;  return 0; }
 if(!strcmp(varname, "PreviewPos"))  { *ival = PreviewPos;  return 0; }
 if(!strcmp(varname, "PreviewInc"))  { *ival = PreviewInc;  return 0; }
 if(!strcmp(varname, "PreviewVal"))  { *ival = var_preval_update();  return 0; }
 if(!strcmp(varname, "TRUE"))     { *ival = 1;       return 0; }
 if(!strcmp(varname, "FALSE"))    { *ival = 0;       return 0; }
 if(!strcmp(varname, "ON"))       { *ival = 1;       return 0; }
 if(!strcmp(varname, "OFF"))      { *ival = 0;       return 0; }
 if(!strcmp(varname, "NoTissue")){  *ival = image_has_tissue?0:1; return 0; }
 if(!strcmp(varname, "HasTissue")){ *ival = image_has_tissue; return 0; }
 if(!strcmp(varname, "Ps_SatL_R")) { *ival = Ps_SatL_R; return 0; }
 if(!strcmp(varname, "Ps_SatL_G")) { *ival = Ps_SatL_G; return 0; }
 if(!strcmp(varname, "Ps_SatL_B")) { *ival = Ps_SatL_B; return 0; }
 if(!strcmp(varname, "Ps_SatU_R")) { *ival = Ps_SatU_R; return 0; }
 if(!strcmp(varname, "Ps_SatU_G")) { *ival = Ps_SatU_G; return 0; }
 if(!strcmp(varname, "Ps_SatU_B")) { *ival = Ps_SatU_B; return 0; }
 if(!strcmp(varname, "Ps_Min_R"))  { *ival = Ps_Min_R; return 0; }
 if(!strcmp(varname, "Ps_Min_G"))  { *ival = Ps_Min_G; return 0; }
 if(!strcmp(varname, "Ps_Min_B"))  { *ival = Ps_Min_B; return 0; }
 if(!strcmp(varname, "Ps_Max_R"))  { *ival = Ps_Max_R; return 0; }
 if(!strcmp(varname, "Ps_Max_G"))  { *ival = Ps_Max_G; return 0; }
 if(!strcmp(varname, "Ps_Max_B"))  { *ival = Ps_Max_B; return 0; }
 if(!strcmp(varname, "NSteppers")) { *ival = NSteppers;  return 0; }
 if(!strcmp(varname, "NBinaries")) { *ival = NBinaries;  return 0; }
 if(!strcmp(varname, "NMlevels"))  { *ival = NMlevels;   return 0; }
 if(!strcmp(varname, "NServos"))   { *ival = NServos;    return 0; }
 if(!strcmp(varname, "NSensors"))  { *ival = NSensors;   return 0; }
 if(!strcmp(varname, "CurrActIdx")){ *ival = CurrActIdx; return 0; }
 if(!strcmp(varname, "CurrActType")){ *ival = CurrActType; return 0; }
 if(!strcmp(varname, "PreviewReport")){ *ival = PreviewReport; return 0; }
 if(!strcmp(varname, "Millis")) {
   var_millis_update();
   *ival = Millis;
   return 0;
  }
 if(!strcmp(varname, "NReads"))  { *ival = NReads;   return 0; }
 if(!strcmp(varname, "NBytes"))  { *ival = NBytes;   return 0; }
 if(!strcmp(varname, "NWrites")) { *ival = NWrites;  return 0; }
 if(!strcmp(varname, "NewLines")){ *ival = NewLines; return 0; }
 *vtype = VDT_FLOAT; // We'll change later if required.
 if(!strcmp(varname, "PMRep1"))    { *fval = (double)PMRep1; return 0; }
 if(!strcmp(varname, "PMRep2"))    { *fval = (double)PMRep2; return 0; }
 if(!strcmp(varname, "PMRep3"))    { *fval = (double)PMRep3; return 0; }
 if(!strcmp(varname, "PMRep4"))    { *fval = (double)PMRep4; return 0; }
 if(!strcmp(varname, "Ps_Integral_R")) { *fval = Ps_Integral_R; return 0; }
 if(!strcmp(varname, "Ps_Integral_G")) { *fval = Ps_Integral_G; return 0; }
 if(!strcmp(varname, "Ps_Integral_B")) { *fval = Ps_Integral_B; return 0; }
 if(!strcmp(varname, "Ps_Var_R"))  { *fval = Ps_Var_R; return 0; }
 if(!strcmp(varname, "Ps_Var_G"))  { *fval = Ps_Var_G; return 0; }
 if(!strcmp(varname, "Ps_Var_B"))  { *fval = Ps_Var_B; return 0; }
 if(!strcmp(varname, "Ps_Mean_R")) { *fval = Ps_Mean_R; return 0; }
 if(!strcmp(varname, "Ps_Mean_G")) { *fval = Ps_Mean_G; return 0; }
 if(!strcmp(varname, "Ps_Mean_B")) { *fval = Ps_Mean_B; return 0; }
 if(!strcmp(varname, "Ps_DCT_R"))  { *fval = Ps_DCT_R; return 0; }
 if(!strcmp(varname, "Ps_DCT_G"))  { *fval = Ps_DCT_G; return 0; }
 if(!strcmp(varname, "Ps_DCT_B"))  { *fval = Ps_DCT_B; return 0; }
 if(!strcmp(varname, "Ps_MAL_R"))  { *fval = Ps_MAL_R; return 0; }
 if(!strcmp(varname, "Ps_MAL_G"))  { *fval = Ps_MAL_G; return 0; }
 if(!strcmp(varname, "Ps_MAL_B"))  { *fval = Ps_MAL_B; return 0; }
 if(!strcmp(varname, "Ps_Focus_R")){ *fval = Ps_Focus_R; return 0; }
 if(!strcmp(varname, "Ps_Focus_G")){ *fval = Ps_Focus_G; return 0; }
 if(!strcmp(varname, "Ps_Focus_B")){ *fval = Ps_Focus_B; return 0; }
 if(!strcmp(varname, "Ps_Npix_R")) { *fval = Ps_Npix_R; return 0; }
 if(!strcmp(varname, "Ps_Npix_G")) { *fval = Ps_Npix_G; return 0; }
 if(!strcmp(varname, "Ps_Npix_B")) { *fval = Ps_Npix_B; return 0; }
 if(!strcmp(varname, "Ps_Msupport")){ *fval = Ps_Msupport; return 0; }
 if(!strcmp(varname, "CurrTC")){ *fval = CurrTC;  return 0; }
 
 // It's not a reserved name, so check if it is a user-defined variable
 int vi_res = var_index(varname, &idx, &use_idx);
 if(vi_res > 1) return vi_res;
 if(vi_res==0){
   *vtype = Varlist[idx].Type;
   switch(*vtype){
   case VDT_FLOAT:
       *fval = Varlist[idx].Fval[use_idx]; 
       break;
   case VDT_INT:
       *ival = Varlist[idx].Ival[use_idx];
       break;
   case VDT_STR:
       snprintf(str, CPTRLEN, "%s", Varlist[idx].Str[use_idx]);
       break;
   default:
       show_message("Unrecognised variable type - Program Error.\n", 
                                                   "var_evalvv: ", MT_PCS_E, 1);
       return 1; // Unrecognised variable type - a programming error  
   }
   Varval_nature = VVNAT_USER;
   return 0;
 }

   Varval_nature = VVNAT_CONST;

 // If we've got to here then varname does not represent a reserved token or
 // a user-defined variable so check to see if it is a valid float or int
 // number string.
 if(!is_not_integer(varname,ival)){
     *vtype = VDT_INT;
     return 0;
 }
 if(!is_not_float(varname,fval)){
     *vtype = VDT_FLOAT;
     return 0;
 }

 // If we get here we can assume it is a general printing string
 snprintf(str,CPTRLEN,"%s",varname);
 *vtype = VDT_STR;

 return 0;
}

int run_var_evalvv(PCS_Argument *arg, double *fval, int32_t *ival, int *vtype, char *str)
// High-Performance Runtime Variant: Eradicates 64 sequential text strcmps!
// Operates purely on the pre-compiled privilege bitmasks and system token IDs.
// Returns 0 on success, or an error code on failure.
{
 unsigned int idx = 0;
 uint32_t use_idx = 0;

    Varval_nature = VVNAT_SYSTEM; // Default state for system objects
    *vtype = VDT_STR;             // Default fallback type

    // =========================================================================
    // 1. SYSTEM-OWNED PROPERTY FAST-PATH (ARG_FLAG_SYSTEM)
    // =========================================================================
    // If the system bit is set, bypass ALL text comparisons! 
    // arg->symbol_id contains the pre-matched SysTokenId enum index.
    if (arg->arg_opcode & ARG_FLAG_SYSTEM) {
        
        switch (arg->symbol_id) {
            // --- SYSTEM STRINGS (VDT_STR) ---
            case TOK_SPACE:    sprintf(str, "%s", Space); return 0;
            case TOK_HASH:     sprintf(str, "%s", Hash);  return 0;
            case TOK_DATETIME:
                var_datetime_update();
                sprintf(str, "%s", DateTime);
                return 0;

            // --- SYSTEM INTEGERS (VDT_INT) ---
            case TOK_CONDEXP:  *vtype = VDT_INT; *ival = Condexp; return 0;
            case TOK_CLIMODE:  *vtype = VDT_INT; *ival = CLImode; return 0;
            case TOK_SYSVAL:   *vtype = VDT_INT; *ival = Sysval;  return 0;
            case TOK_TRUE:     *vtype = VDT_INT; *ival = 1;       return 0;
            case TOK_FALSE:    *vtype = VDT_INT; *ival = 0;       return 0;
            case TOK_ON:       *vtype = VDT_INT; *ival = 1;       return 0;
            case TOK_OFF:      *vtype = VDT_INT; *ival = 0;       return 0;
            case TOK_NOTISSUE:   *vtype = VDT_INT; *ival = image_has_tissue ? 0 : 1; return 0;
            case TOK_HASTISSUE:  *vtype = VDT_INT; *ival = image_has_tissue;         return 0;
            case TOK_PREVIEWPOS: *vtype = VDT_INT; *ival = PreviewPos;  return 0;
            case TOK_PREVIEWINC: *vtype = VDT_INT; *ival = PreviewInc;  return 0;
            case TOK_PREVIEWVAL: *vtype = VDT_INT; *ival = var_preval_update();  return 0;
            case TOK_PS_SATL_R: *vtype = VDT_INT; *ival = Ps_SatL_R; return 0;
            case TOK_PS_SATL_G: *vtype = VDT_INT; *ival = Ps_SatL_G; return 0;
            case TOK_PS_SATL_B: *vtype = VDT_INT; *ival = Ps_SatL_B; return 0;
            case TOK_PS_SATU_R: *vtype = VDT_INT; *ival = Ps_SatU_R; return 0;
            case TOK_PS_SATU_G: *vtype = VDT_INT; *ival = Ps_SatU_G; return 0;
            case TOK_PS_SATU_B: *vtype = VDT_INT; *ival = Ps_SatU_B; return 0;
            case TOK_PS_MIN_R:  *vtype = VDT_INT; *ival = Ps_Min_R;  return 0;
            case TOK_PS_MIN_G:  *vtype = VDT_INT; *ival = Ps_Min_G;  return 0;
            case TOK_PS_MIN_B:  *vtype = VDT_INT; *ival = Ps_Min_B;  return 0;
            case TOK_PS_MAX_R:  *vtype = VDT_INT; *ival = Ps_Max_R;  return 0;
            case TOK_PS_MAX_G:  *vtype = VDT_INT; *ival = Ps_Max_G;  return 0;
            case TOK_PS_MAX_B:  *vtype = VDT_INT; *ival = Ps_Max_B;  return 0;
            case TOK_NSTEPPERS: *vtype = VDT_INT; *ival = NSteppers; return 0;
            case TOK_NBINARIES: *vtype = VDT_INT; *ival = NBinaries; return 0;
            case TOK_NMLEVELS:  *vtype = VDT_INT; *ival = NMlevels;  return 0;
            case TOK_NSERVOS:   *vtype = VDT_INT; *ival = NServos;   return 0;
            case TOK_NSENSORS:  *vtype = VDT_INT; *ival = NSensors;  return 0;
            case TOK_CURRACTIDX:  *vtype = VDT_INT; *ival = CurrActIdx;  return 0;
            case TOK_CURRACTTYPE: *vtype = VDT_INT; *ival = CurrActType; return 0;
            case TOK_PREVIEWREPORT: *vtype = VDT_INT; *ival = PreviewReport; return 0;
            case TOK_MILLIS:
                var_millis_update();
                *vtype = VDT_INT; *ival = Millis;
                return 0;
            case TOK_NREADS:    *vtype = VDT_INT; *ival = NReads;   return 0;
            case TOK_NBYTES:    *vtype = VDT_INT; *ival = NBytes;   return 0;
            case TOK_NWRITES:   *vtype = VDT_INT; *ival = NWrites;  return 0;
            case TOK_NEWLINES:  *vtype = VDT_INT; *ival = NewLines; return 0;

            // --- SYSTEM FLOATS (VDT_FLOAT) ---
            case TOK_PMREP1:    *vtype = VDT_FLOAT; *fval = (double)PMRep1; return 0;
            case TOK_PMREP2:    *vtype = VDT_FLOAT; *fval = (double)PMRep2; return 0;
            case TOK_PMREP3:    *vtype = VDT_FLOAT; *fval = (double)PMRep3; return 0;
            case TOK_PMREP4:    *vtype = VDT_FLOAT; *fval = (double)PMRep4; return 0;
            case TOK_PS_INTEGRAL_R: *vtype = VDT_FLOAT; *fval = Ps_Integral_R; return 0;
            case TOK_PS_INTEGRAL_G: *vtype = VDT_FLOAT; *fval = Ps_Integral_G; return 0;
            case TOK_PS_INTEGRAL_B: *vtype = VDT_FLOAT; *fval = Ps_Integral_B; return 0;
            case TOK_PS_VAR_R:      *vtype = VDT_FLOAT; *fval = Ps_Var_R;      return 0;
            case TOK_PS_VAR_G:      *vtype = VDT_FLOAT; *fval = Ps_Var_G;      return 0;
            case TOK_PS_VAR_B:      *vtype = VDT_FLOAT; *fval = Ps_Var_B;      return 0;
            case TOK_PS_MEAN_R:     *vtype = VDT_FLOAT; *fval = Ps_Mean_R;     return 0;
            case TOK_PS_MEAN_G:     *vtype = VDT_FLOAT; *fval = Ps_Mean_G;     return 0;
            case TOK_PS_MEAN_B:     *vtype = VDT_FLOAT; *fval = Ps_Mean_B;     return 0;
            case TOK_PS_DCT_R:      *vtype = VDT_FLOAT; *fval = Ps_DCT_R;      return 0;
            case TOK_PS_DCT_G:      *vtype = VDT_FLOAT; *fval = Ps_DCT_G;      return 0;
            case TOK_PS_DCT_B:      *vtype = VDT_FLOAT; *fval = Ps_DCT_B;      return 0;
            case TOK_PS_MAL_R:      *vtype = VDT_FLOAT; *fval = Ps_MAL_R;      return 0;
            case TOK_PS_MAL_G:      *vtype = VDT_FLOAT; *fval = Ps_MAL_G;      return 0;
            case TOK_PS_MAL_B:      *vtype = VDT_FLOAT; *fval = Ps_MAL_B;      return 0;
            case TOK_PS_FOCUS_R:    *vtype = VDT_FLOAT; *fval = Ps_Focus_R;    return 0;
            case TOK_PS_FOCUS_G:    *vtype = VDT_FLOAT; *fval = Ps_Focus_G;    return 0;
            case TOK_PS_FOCUS_B:    *vtype = VDT_FLOAT; *fval = Ps_Focus_B;    return 0;
            case TOK_PS_NPIX_R:     *vtype = VDT_FLOAT; *fval = Ps_Npix_R;     return 0;
            case TOK_PS_NPIX_G:     *vtype = VDT_FLOAT; *fval = Ps_Npix_G;     return 0;
            case TOK_PS_NPIX_B:     *vtype = VDT_FLOAT; *fval = Ps_Npix_B;     return 0;
            case TOK_PS_MSUPPORT:   *vtype = VDT_FLOAT; *fval = Ps_Msupport;   return 0;
            case TOK_CURRTC:        *vtype = VDT_FLOAT; *fval = CurrTC;        return 0;

            // If it doesn't match an evaluatable system value, break out of 
            // Section 1 and let it drop through to be processed as a raw string literal!
            default: break; 
        }
    }

    // =========================================================================
    // 1b. AUDIT FIX 3: IMMUTABLE NUMERIC LITERAL FAST-PATH
    // =========================================================================
    // A token classified by BRANCH B of the compiler is a well-formed number,
    // and var_new() forbids a variable from bearing such a name, so this token
    // cannot possibly denote a user variable.  Settling it here, before the
    // variable machinery, removes a full var_find() strcmp walk of the whole
    // variable list from every execution of every literal operand -- which was
    // the single largest item in the interpreter's run-time budget.
    //
    // The ARG_FLAG_SYSTEM guard matters: a system token such as TRUE or ON
    // also carries ARG_OP_INT, and its value must continue to come from
    // section 1 above rather than from cached_ival.  BRANCH B tokens never
    // carry the system flag, because BRANCH A returns before BRANCH B is
    // reached.
    if (!(arg->arg_opcode & ARG_FLAG_SYSTEM)) {
        if (arg->arg_opcode & ARG_OP_INT) {
            Varval_nature = VVNAT_CONST;
            *ival = arg->cached_ival; *vtype = VDT_INT; return 0;
        }
        if (arg->arg_opcode & ARG_OP_FLOAT) {
            Varval_nature = VVNAT_CONST;
            *fval = arg->cached_fval; *vtype = VDT_FLOAT; return 0;
        }
    }

    // =========================================================================
    // 2. TIMELINE-AWARE VARIABLE RESOLUTION (0 STRING COMPARISONS)
    // =========================================================================
    // GENERATIONAL FAST-PATH SHORTCUT: Pure numeric validation sweep!
    if (arg->generation == Varlist_Generation) {
        idx = arg->symbol_id;
        
        if (arg->nested_expr != NULL) {
            int vi_res = run_var_index(arg, &idx, &use_idx);
            if (vi_res == 0) goto fetch_user_value;
            if (vi_res > 1)  return vi_res;
        } else if (idx < NVars && Varlist[idx].Count == 1) {
            // AUDIT FIX 2: the two conditions above were absent.  fetch_user_value
            // dereferences Varlist[idx].Ival / .Fval / .Str without validating
            // idx, so a cached slot left over from a shrunken list read past the
            // end of the block and then dereferenced a stray pointer.  The test
            // mirrors the one run_var_index() already performs, and both operands
            // are already in registers.  A failure here simply falls through to
            // the cold path below, which re-binds the argument correctly.
            use_idx = 0; 
            goto fetch_user_value; // 0 clock cycles for scalar variables!
        }
    }

    // COLD FALLBACK ROUTE: Runs exactly once per generation change!
    int vi_res = run_var_index(arg, &idx, &use_idx);
    if (vi_res == 0) {
        // Lock down the lazy cache, dynamically append the USER flag, and bind generation!
        arg->arg_opcode |= ARG_FLAG_USER; 
        arg->symbol_id = idx;
        arg->generation = Varlist_Generation;
        goto fetch_user_value;
    }
    if (vi_res > 1) return vi_res;

    // =========================================================================
    // 3. IMMUTABLE CONSTANT / LITERAL COLLAPSE BRANCH
    // =========================================================================
    Varval_nature = VVNAT_CONST;
    if (arg->arg_opcode & ARG_OP_INT) {
        *ival = arg->cached_ival; *vtype = VDT_INT; return 0;
    }
    if (arg->arg_opcode & ARG_OP_FLOAT) {
        *fval = arg->cached_fval; *vtype = VDT_FLOAT; return 0;
    }

    // Clean String Copy Fallback (Safely overrides space-filled buffers!)

//    if (strcmp(arg->raw_text, "g_p_idx") == 0 || strcmp(arg->raw_text, "g_total_pix") == 0 || strcmp(arg->raw_text, "<") == 0) {
//        printf("[DEBUG Eval] FALLBACK TRIGGERED for token: \"%s\"! opcode: 0x%04X, symbol_id: %u\n", 
//               arg->raw_text, arg->arg_opcode, arg->symbol_id);
//    }

 snprintf(str,CPTRLEN,"%s",arg->raw_text);
 *vtype = VDT_STR;
 return 0;

fetch_user_value:
    Varval_nature = VVNAT_USER;
    *vtype = Varlist[idx].Type;
    switch (*vtype) {
        case VDT_FLOAT: *fval = Varlist[idx].Fval[use_idx]; break;
        case VDT_INT:   *ival = Varlist[idx].Ival[use_idx]; break;
        case VDT_STR:
            snprintf(str, CPTRLEN, "%s", Varlist[idx].Str[use_idx]);
            break;
        default: return 1;
    }
    return 0;
}

int vv_verify_eval(char *var_expr, const char *cmd_name, char *errmsg, 
                    double *fval, int32_t *ival, int *vtype, char *str_out) 
// Evaluate a varval with verification and error messge printing. This is a
// helper function.
{
 unsigned int vidx;
 uint32_t write_idx = 0;
 
 int vvr = var_evalvv(var_expr, fval, ival, vtype, str_out);
 
 if (vvr != 0) {
     if (vvr > 1) {
         // Contextual recovery of the index for the error message
         var_index(var_expr, &vidx, &write_idx);
         print_vi_err(vvr, errmsg, var_expr, write_idx);
     } else {
         snprintf(errmsg, ERRMSG_LEN, "%s: Failed to evaluate '%s'.", cmd_name, var_expr);
     }
     return 1; // Signal failure to the caller
 }
 return 0; // Success
}

int run_vv_verify_eval(PCS_Argument *arg, const char *cmd_name, char *errmsg, 
                       double *fval, int32_t *ival, int *vtype, char *str_out) 
// High-Speed Runtime Variant: Matches your historical verification rules perfectly 
// while exploiting your optimized tokenised structures natively.
// Returns 0 on success. Returns 1 on error with the exact error formatted in errmsg.
{
    unsigned int vidx = 0;
    uint32_t write_idx = 0;

    // Execute our high-speed, dynamic-safe tokeniser evaluation path pass
    int vvr = run_var_evalvv(arg, fval, ival, vtype, str_out);

    if (vvr != 0) {
        if (vvr > 1) {
            // Contextual recovery using your token attributes natively
            run_var_index(arg, &vidx, &write_idx);
            print_vi_err(vvr, errmsg, arg->raw_text, write_idx);
        } else {
            snprintf(errmsg, ERRMSG_LEN, "%s: Failed to evaluate '%s'.", cmd_name, arg->raw_text);
        }
        return 1; // Signal failure to the caller
    }
    return 0; // Success
}

int var_type(char *vartype)
// Accepts a string and returns the VDT_ constant for variable data type
// represented by that string or VDT_UNDEF if the string does not represent a
// defined variable type. 
{
    if(!strcmp(vartype, "int"))    return VDT_INT;
    if(!strcmp(vartype, "float"))  return VDT_FLOAT;
    if(!strcmp(vartype, "string")) return VDT_STR;

    return VDT_UNDEF;
}

// Comparator Types
#define VCT_EQUALITY    1 // ==
#define VCT_NOTEQUAL    2 // !=
#define VCT_GREATEQ     3 // >=
#define VCT_LESSEQ      4 // <=
#define VCT_GREATER     5 // >
#define VCT_LESSER      6 // <
#define VCT_LOGICAL_AND 7 // &&
#define VCT_LOGICAL_OR  8 // ||
#define VCT_FAILEDEVAL  9 // Failed to evaluate the varval

int comparator(char *comptype, char *errmsg)
// Accepts a string varval and returns the VCT_ constant for comparator type
// represented by that string or -1 if the string does not represent a defined
// comparator type. Returns VCT_FAILEDEVAL if the evaluation function failed. 
{
 char cptr1[CPTRLEN];
 int vtype1;
 double fval1;
 int32_t ival1;
 
 // Evaluate the token. If the user wrote 'set_condexp A == B', 
 // comptype will be "==".
 if(vv_verify_eval(comptype, "comparator", errmsg, &fval1, &ival1, &vtype1, cptr1))
     return VCT_FAILEDEVAL;

 // The result of the evaluation must be a string (like "==")
 if(vtype1 != VDT_STR) return -1;

 if(!strcmp(cptr1, "==")) return VCT_EQUALITY;
 if(!strcmp(cptr1, "!=")) return VCT_NOTEQUAL;
 if(!strcmp(cptr1, ">=")) return VCT_GREATEQ;
 if(!strcmp(cptr1, "<=")) return VCT_LESSEQ;
 if(!strcmp(cptr1, ">"))  return VCT_GREATER;
 if(!strcmp(cptr1, "<"))  return VCT_LESSER;
 if(!strcmp(cptr1, "&&")) return VCT_LOGICAL_AND;
 if(!strcmp(cptr1, "||")) return VCT_LOGICAL_OR;

 return -1;
}

int run_comparator(PCS_Argument *arg, char *errmsg)
// Highly Optimized Runtime Variant: Safe from check-time control-block nesting drops!
{
    // AOT Fast-path shortcut pass
    // FIXED: Only take the shortcut if the cached identifier is valid (non-zero)!
    if ((arg->arg_opcode & ARG_FLAG_SYSTEM) && arg->symbol_id != 0) {
        return (int)arg->symbol_id;
    }

    // FIXED FALLBACK GATE: If compile-time caching was skipped on a nested line (symbol_id == 0),
    // we safely read the raw token text character symbol natively right now!
    if (arg->raw_text[0] != '\0') {
        if (!strcmp(arg->raw_text, "==")) return VCT_EQUALITY;
        if (!strcmp(arg->raw_text, "!=")) return VCT_NOTEQUAL;
        if (!strcmp(arg->raw_text, ">=")) return VCT_GREATEQ;
        if (!strcmp(arg->raw_text, "<=")) return VCT_LESSEQ;
        if (!strcmp(arg->raw_text, ">"))  return VCT_GREATER;
        if (!strcmp(arg->raw_text, "<"))  return VCT_LESSER;
        if (!strcmp(arg->raw_text, "&&")) return VCT_LOGICAL_AND;
        if (!strcmp(arg->raw_text, "||")) return VCT_LOGICAL_OR;
    }

    // Dynamic variable fallback track path pass (for user string variables holding operators)
    double fval; int32_t ival; int vtype; char cptr[CPTRLEN];

    if (run_vv_verify_eval(arg, "comparator", errmsg, &fval, &ival, &vtype, cptr) != 0) {
        return VCT_FAILEDEVAL;
    }

    if (vtype != VDT_STR) return -1;

    if (!strcmp(cptr, "==")) return VCT_EQUALITY;
    if (!strcmp(cptr, "!=")) return VCT_NOTEQUAL;
    if (!strcmp(cptr, ">=")) return VCT_GREATEQ;
    if (!strcmp(cptr, "<=")) return VCT_LESSEQ;
    if (!strcmp(cptr, ">"))  return VCT_GREATER;
    if (!strcmp(cptr, "<"))  return VCT_LESSER;
    if (!strcmp(cptr, "&&")) return VCT_LOGICAL_AND;
    if (!strcmp(cptr, "||")) return VCT_LOGICAL_OR;

    return -1;
}

int float_to_int(double fval, int32_t *x)
// Convert float to int with error checking
// *x is set to the nearest integer that fval represents if successful
// Returns 0 on success
// Returns 1 on failure (because fval is out of integer range)
{
 double conval=0.0;

 if(fval > 0.0) conval = fval + 0.5;
 if(fval < 0.0) conval = fval - 0.5;
 if(conval > INT32_MAX) return 1;
 if(conval < INT32_MIN) return 1;

 *x = (int32_t)conval;
 return 0;
}

