    case INFO_MSDENOM:                     // LG
    case INFO_FASTMSD:                     // LG
    case INFO_MSDEMAX:     // Server only  // LG
    case INFO_BLSTEPS:                     // LG        // Read only
    case INFO_BLSTMAX:     // Server only  // LG
