     case OP_DEF_VAR:   // Local command
        // def_var <vartype> <varname> <VARVAL>
        if(pcs_argc_check(argcount, 4, 4, 0, tline->args[0].raw_text, errmsg))
                                         { returnvalue = PCHK_E_SYNTAX; break; }

        // Check the <vartype> is valid (allow it to be a string variable or a
        // string constant - but it must be a string)
        if(vv_verify_eval(tline->args[1].raw_text, tline->args[0].raw_text, errmsg,
           &fval, &ival, &vtype, cptr1)) { returnvalue = PCHK_E_SYNTAX; break; }
        if(vtype != VDT_STR){
          returnvalue = PCHK_E_SYNTAX; 
          snprintf(errmsg, ERRMSG_LEN, "%s: <vartype> must be a string ('%s' is not).",
          tline->args[0].raw_text,tline->args[1].raw_text);
          break;
         }

        vtype = var_type(cptr1);
        if(vtype == VDT_UNDEF){
          returnvalue = PCHK_E_SYNTAX; 
          snprintf(errmsg, ERRMSG_LEN, "%s: '%s' (='%s') is not a valid <vartype>.",
          tline->args[0].raw_text,tline->args[1].raw_text,cptr1);
          break;
         }

        // Check if <VARVAL> can be evaluated
        if (vv_verify_eval(tline->args[3].raw_text, tline->args[0].raw_text, errmsg, &fval, &ival, &choice, cptr1)){
          returnvalue = PCHK_E_SYNTAX; break;
         }

        // Because the code below is shared with the def_array command we need
        // to set some variables to harmonise the code for both uses.
        // Set the <VARVAL> argument index for the syntax of a single variable
        vaidx = 3;
        // Set the variable/array string to "variable"
        sprintf(vastr,"variable");
        // Set the array size to 1
        vasz = 1;

       
        varray_check:
        // If we got this far, we can create the newly requested variable.
        // We do that now to check for its use later in the script and to see if
        // there are any errors in creating it.

        // First make any adjustments or casts if the source and destination
        // data types differ and ensure that all values that need to be given to
        // the new variable are in fval or ival or cptr1.
        // The requested type for the new variable will be in vtype and the type
        // for the variable supplying the value(s) will be in 'choice'.
        switch(vtype){ 
         case VDT_INT:
            if(choice == VDT_FLOAT){
               try_floatval:
               if(float_to_int(fval, &i32)){
                 returnvalue = PCHK_E_SYNTAX;
                 snprintf(errmsg, ERRMSG_LEN, "%s: Cannot convert float '%s' to int (it is out"
                                   " of int range).",tline->args[0].raw_text,tline->args[vaidx].raw_text);
                 goto end_check;
                } else ival=i32;
             } else if(choice == VDT_STR){
               // Can the string be represented as an int?
               if(is_not_integer(cptr1,&ival)){
                 // What about a float that can be converted to an int?
                  if(!is_not_float(cptr1,&fval)){
                   goto try_floatval;
                  } else {
                   returnvalue = PCHK_E_SYNTAX;
                   snprintf(errmsg, ERRMSG_LEN,"%s: Cannot convert string value '%s' to int.",
                            tline->args[0].raw_text, tline->args[vaidx].raw_text);
                   goto end_check;
                  }
                }
             }
            break;
         case VDT_FLOAT:
            switch(choice){
             case VDT_FLOAT: // The value is already in fval
             break;
             case VDT_INT:   // is in ival so pass it into fval
              fval = (double)ival;
             break;
             case VDT_STR: // See if this can be cast to a float else error
              if(is_not_float(cptr1,&fval)){
                returnvalue = PCHK_E_SYNTAX;
                snprintf(errmsg, ERRMSG_LEN, "%s: '%s' is of type 'string' and the string it"
                            " contains does not represent a valid float value.",
                                                    tline->args[0].raw_text, tline->args[vaidx].raw_text);
                goto end_check;
               }
             break;
            }
         break;
         case VDT_STR:    // If the source is a string, cast the donor into
          switch(choice){ // a string (cptr1)
            // AUDIT FIX 38: a numeric LITERAL is stored as written ("5e+"
            // stays "5e+", "007" stays "007"); only a numeric VARIABLE or
            // system value is formatted from its binary value.
            case VDT_INT:
                  if(!numeric_literal_copy(&tline->args[vaidx], cptr1))
                    sprintf(cptr1,"%"PRId32,ival);
            break;
            case VDT_FLOAT:
                  if(!numeric_literal_copy(&tline->args[vaidx], cptr1))
                    sprintf(cptr1,"%.9g",fval);
            break;
            case VDT_STR:
            break;
           }
         break;       
       }
        // Create the variable / array and get its index.
        idx = var_new(vtype, tline->args[2].raw_text, fval, ival, cptr1, vasz);
        if(idx != VNE_SUCCESS){
            returnvalue = PCHK_E_SYNTAX;
            switch(idx){
            case VNE_MEMNAME:
                snprintf(errmsg, ERRMSG_LEN, "%s: Failed to define %s %s (%s).",
                        tline->args[0].raw_text, vastr, tline->args[2].raw_text,
                                           "failed to get memory for the name");
                break;
            case VNE_MEMVAR:
                snprintf(errmsg, ERRMSG_LEN, "%s: Failed to define %s %s (%s).",
                        tline->args[0].raw_text, vastr, tline->args[2].raw_text,
                                                        "failed to get memory");
                break;
            case VNE_NAME:
                snprintf(errmsg, ERRMSG_LEN, "%s: Failed to define %s %s (%s).",
                        tline->args[0].raw_text, vastr, tline->args[2].raw_text,
                                                 "duplicate or protected name");
                break;
            case VNE_TYPE:
                snprintf(errmsg, ERRMSG_LEN, "%s: Failed to define %s %s (%s).",
                        tline->args[0].raw_text, vastr, tline->args[2].raw_text,
                                                     "data type not supported");
                break;
            default:
                snprintf(errmsg, ERRMSG_LEN, "%s: Failed to define %s %s (%s).",
                        tline->args[0].raw_text, vastr, tline->args[2].raw_text, "for some reason");
                break;
            }
            break;
        }
     break;

     case OP_DEF_ARRAY:   // Local command // New
