        if(pcs_int_check(tline->args[0].raw_text,tline->args[3].raw_text, errmsg, &i32,PCS_IGTEQ,1))
                                         { returnvalue = PCHK_E_SYNTAX; break; }
    
        // 3. Evaluate the <initial_VARVAL> (tline->args[4].raw_text)
        if (vv_verify_eval(tline->args[4].raw_text,tline->args[0].raw_text, errmsg, &fval, &ival, &choice, cptr1)){
          returnvalue = PCHK_E_SYNTAX; 
          break;
         }
         
        // Because the code below is shared with the def_var command we need
        // to set some variables to harmonise the code for both uses.
        // Set the <VARVAL> argument index for the syntax of a single variable
        vaidx = 4;
        // Set the variable/array string to "array"
        sprintf(vastr,"array");
        // Set the array size to i32
        vasz = (uint32_t)i32;

        // 4. Create the array
