     case OP_CAT_CHAR:       // Local command // New
        // cat_char <STR_VAR> <char_as_int>
        if(pcs_argc_check(argcount, 3, 3, 0, tline->args[0].raw_text, errmsg))
                                         { returnvalue = PCHK_E_SYNTAX; break; }

        // 1. VALIDATE RECEPTOR STRING VARIABLE: Runs your exact historical verification rules!
        if(pcs_string_check(tline->args[1].raw_text, tline->args[0].raw_text, cptr1, errmsg, 1, 0, 1)){
            returnvalue = PCHK_E_SYNTAX;
            break;
        }
        // Check if <char_as_int> exists on the list of extant variables
        vidx = var_find(tline->args[2].raw_text); // Look for the base name directly
        if(vidx >= NVars) { 
         // If it is not, let us see if the literal string can be interpreted as a UTF
         // code point number:

            // Extract the correct parameter slot for our hex evaluator
            PCS_Argument *char_arg = &tline->args[2]; // <char_as_int>

            // ===================================================================
            // AHEAD-OF-TIME UTF-16/HEX LITERAL COMPILATION PASS
            // ===================================================================
            // If the char code is a hardcoded hex string, bake it into binary right now!
            if (g_ascii_strncasecmp(char_arg->raw_text, "U+", 2) == 0 ||
                g_ascii_strncasecmp(char_arg->raw_text, "0x", 2) == 0) 
            {
                char *endptr;
                const char *hex_part = char_arg->raw_text + 2; // Skip the "U+" or "0x"
                long val = strtol(hex_part, &endptr, 16);

                if (endptr == hex_part || *endptr != '\0') {
                    snprintf(errmsg, ERRMSG_LEN, "%s: Invalid UTF-16/Hex format (%s).", tline->args[0].raw_text, char_arg->raw_text);
                    returnvalue = PCHK_E_SYNTAX;
                    break;
                }

                // SUCCESS: Save directly into our high-speed cached literal value slots!
                char_arg->arg_opcode |= ARG_OP_INT;
                i32 = (int32_t)val;
                char_arg->cached_ival = i32;
                char_arg->cached_fval = (double)val;
            } else if(!is_not_integer((const char *)tline->args[2].raw_text,&i32)){
             //  It's not a base 16 UTF value, so is it a 'normal' integer
                char_arg->arg_opcode |= ARG_OP_INT;
                char_arg->cached_ival = i32;
                char_arg->cached_fval = (double)i32;
            } else { // It's not a variable and it is not a valid integer so ...
                returnvalue = PCHK_E_SYNTAX;
                snprintf(errmsg, ERRMSG_LEN, "%s failed. String '%s' is not interpretable as a legal UTF integer.", tline->args[0].raw_text, tline->args[2].raw_text);
                break;
            }
            // If we get here then some value integer has been read into i32 - so check its range
            if (i32<1 || i32 > 1114111) {
                returnvalue = PCHK_E_SYNTAX;
                snprintf(errmsg, ERRMSG_LEN, "%s failed. Value %d out of legal UTF bounds (1-1114111).", tline->args[0].raw_text, i32);
                break;
            }

        }


     break;


     case OP_SET_VAR:   // Local command
