        // <stats_func> options are basic, spatial, distro, texture.
        // For basic the receptor args are: <len> <rec_mean> <rec_integral> <rec_min> <rec_max> <rec_range> <rec_var> <rec_SD> <rec_energy> <rec_sparsity>
        // For spatial the receptor args are: <height> <width/rec_com_c>  <rec_com_r> <rec_bb_r> <rec_bb_c> <rec_bb_ht> <rec_bb_wd> <rec_orient> <rec_eccent>
        // For distro  the receptor args are: <len> <rec_mdn> <rect_lquart> <rec_uquart> <rec_iqr> <ptile> <rec_mode> <rec_peak> <rec_entropy>
        // for texture the receptor args are: <height> <width> <tv> <gradenergy> 
 
        if(stats_array_check(tline, errmsg))
                                         { returnvalue = PCHK_E_SYNTAX; break; }
                                         
        // =====================================================================
        // AOT STATS FUNCTION COMPILATION GATE
        // =====================================================================
        // The function argument is now evaluated ON ITS OWN, immediately before
        // the decision, so Varval_nature describes the argument being decided.
        {
            double   g_fval;
            int32_t  g_ival;
            int      g_vtype;
            char     g_str[CPTRLEN];
            if (vv_verify_eval(tline->args[2].raw_text, tline->args[0].raw_text, errmsg,
                               &g_fval, &g_ival, &g_vtype, g_str)) {
                returnvalue = PCHK_E_SYNTAX; break;
            }
            if (Varval_nature == VVNAT_CONST && g_vtype == VDT_STR) {
                uint8_t pre_fnum;
                int pre_nargs = stats_func_argreq(g_str, &pre_fnum);
                // stats_array_check() has already rejected an unknown literal, so
                // pre_nargs is 1 or 2 here; the test is a guard, not a filter.
                if (pre_nargs > 0) {
                    tline->args[2].arg_opcode |= ARG_OP_SFUNC;
                    tline->args[2].symbol_id   = (uint32_t)pre_fnum;
                    tline->args[2].cached_ival = (int32_t)pre_nargs;
                }
            }
            // Otherwise the function is named by a variable: nothing is
            // cached, and stats_op resolves the variable's CURRENT string 
            // on every execution, which is what makes a run-time operator possible.
        }
        // =====================================================================
     break;

