     case OP_CAMERA_SET: // Ported
      // camera_set <Control_ID> <VARVAL>

      // Ensure <Control_ID> is a valid integer >= 0 and put it in i32
      if(run_pcs_int_check(tline->args[0].raw_text, &tline->args[1], errmsg, &i32,PCS_IGTEQ,0))
                                            { returnvalue = PRUN_ERROR; break; }
      // Ensure <VARVAL> is a valid integer and put it in j32
      if(run_pcs_int_check(tline->args[0].raw_text, &tline->args[2], errmsg, &j32,0,0))
                                            { returnvalue = PRUN_ERROR; break; }
      // Check <VARVAL> is valid for the current camera
      choice = check_camera_setting((uint32_t)i32, j32, &udx);
      switch(choice){
          case CSC_OK: break;
          case CSC_NOCS:
            returnvalue = PRUN_ERROR;
            snprintf(errmsg, ERRMSG_LEN, "%s: Cannot set camera setting (ID: %s=%"PRId32
                            ") because no camera settings are loaded.",
                                                tline->args[0].raw_text,tline->args[1].raw_text, i32);
            goto end_script;
          case CSC_NOID:
            returnvalue = PRUN_ERROR;
            snprintf(errmsg, ERRMSG_LEN, "%s: Cannot set camera setting (ID: %s=%"PRId32
                             ") - there is no setting with that ID.",
                                                tline->args[0].raw_text,tline->args[1].raw_text, i32);
            goto end_script;
          case CSC_RANGE:
            returnvalue = PRUN_ERROR;
            snprintf(errmsg, ERRMSG_LEN, "%s: Cannot set camera setting (ID: %s=%"PRId32
                            ") because the requested value (%s=%"PRId32
                            ") is out of its range.",
                            tline->args[0].raw_text,tline->args[1].raw_text, i32, tline->args[2].raw_text, j32);
            goto end_script;
          default:
            returnvalue = PRUN_ERROR;
            snprintf(errmsg, ERRMSG_LEN, "%s: Cannot set camera setting (ID: %s=%"PRId32
                         ", requested value:%s=%d) due to a programming error.",
                            tline->args[0].raw_text,tline->args[1].raw_text, i32, tline->args[2].raw_text, j32);
            goto end_script;
        }
      // Construct and send the command
      sprintf(cmd_str, "%s %"PRId32" %"PRId32, tline->args[0].raw_text, i32, j32);
