     case OP_EXECUTE_DAEMON: // Local command // Ported
      // execute_daemon <progname> [<arg1> ...]

      // 1. Initialize the global queue safely on its very first invocation
      if (daemon_queue == NULL) daemon_queue = g_queue_new();

      // =======================================================================
      // RECONSTRUCT PDS_LINE LOCALLY FROM MEMORY TOKEN + STRIP
      // =======================================================================
      snprintf(dynamic_cmd_line, sizeof(dynamic_cmd_line), "%s", tline->args[0].raw_text);
      if (tline->raw_path != NULL) {
          strcat(dynamic_cmd_line, " ");
          strcat(dynamic_cmd_line, tline->raw_path);
      }

      // 2. Perform internal substitutions ([img], stripping tline->args[0].raw_text, etc.)
      process_cmdstrline(dynamic_cmd_line, 1); 
  
      // 3. max_daemons set by command max_daemons or default (=1).

      // 4. Duplicate the current line buffer and push it onto the back of the queue
      g_queue_push_tail(daemon_queue, g_strdup(dynamic_cmd_line));

      // 5. Trigger the scheduler loop to execute immediately if slots are open
      pump_daemon_queue();

      // Note: Since this is purely non-blocking and managed asynchronously, 
      // the script execution proceeds immediately to the next line.

      PC++; // Explicitly advance linear index row to process next command
     break;

     case OP_EXECUTE_SYSTEM: // Local command // Ported
      // execute_system <progname> [<arg1> ...]

      // =======================================================================
      // RECONSTRUCT PDS_LINE LOCALLY FROM MEMORY TOKEN + STRIP
      // =======================================================================
      snprintf(dynamic_cmd_line, sizeof(dynamic_cmd_line), "%s", tline->args[0].raw_text);
      if (tline->raw_path != NULL) {
          strcat(dynamic_cmd_line, " ");
          strcat(dynamic_cmd_line, tline->raw_path);
      }

      // 1. Perform internal substitutions ([img], stripping tline->args[0].raw_text, etc.)
      process_cmdstrline(dynamic_cmd_line, 1); 
  
      // 2. Modern GLib Sync Spawn Execution
      GError *error = NULL;
      int exit_status = 0;
  
      // This safely runs the command line synchronously without spawning a shell
      gboolean success = g_spawn_command_line_sync(dynamic_cmd_line, 
                                 NULL,         // Capture stdout (NULL = ignore)
                                 NULL,         // Capture stderr (NULL = ignore)
                                 &exit_status, // Out parameter for return value
                                 &error);      // Out parameter for errors
  
      if(!success){
         // Log the failure to start the program via GTK/GLib logging
         snprintf(errmsg, ERRMSG_LEN,"failed to start: %s", error->message);
         g_error_free(error);
         Sysval = -1; 
         show_message(errmsg,tline->args[0].raw_text,MT_PCS_E,0);
      } else {
         // This native GLib function handles POSIX, MSVC, Pelles C, and MinGW cross-platform parsing automatically!
         GError *exit_error = NULL;
         if (g_spawn_check_wait_status(exit_status, &exit_error)) {
             // The child process exited completely cleanly with code 0
             Sysval = 0;
         } else {
             // The child process returned a non-zero exit code or crashed
             if (exit_error->domain == G_SPAWN_EXIT_ERROR) {
                 // Capture the actual, literal numeric exit code (works universally on Linux & Windows)
                 Sysval = exit_error->code; 
             } else {
                 // Abrupt OS crash or termination signal
                 Sysval = -1; 
             }
             g_error_free(exit_error);
         }
      }

      PC++; // Explicitly advance linear index row to process next command
     break;

