      if(run_pcs_int_check(tline->args[0].raw_text,&tline->args[3], errmsg, &j32,PCS_IGTEQ,0))
                                       { returnvalue = PRUN_ERROR; break; }
      ival = 640 - Trackerlist[vasz].TempDim;
