void set_interrupt_button_font(void)
// Set the colour and weight of the interrupt button according to whether a stop
// script is loaded and set to be used or not.
{
 gchar *btn_markup;
 GtkWidget *btnlabel;
 
 // Using string literals directly allows GCC to verify your format arguments perfectly
 if(Interrupt_script_active) {
  btn_markup = g_markup_printf_escaped(
             "<span foreground=\"red\" weight=\"bold\">%s</span>", "Interrupt");
 } else {
  btn_markup = g_markup_printf_escaped(
         "<span foreground=\"black\" weight=\"normal\">%s</span>", "Interrupt");
 }
 
 btnlabel = gtk_widget_get_first_child(Btn_script_interrupt);
 gtk_label_set_markup(GTK_LABEL(btnlabel), btn_markup);
 g_free (btn_markup);
}

#define FILEDLG_PCS_LOAD   1
#define FILEDLG_XYS_LOAD   2
#define FILEDLG_XYW_LOAD   3
#define FILEDLG_HELP_LOAD  4
#define FILEDLG_XYS_SAVE   5
#define FILEDLG_DARKFIELD  6
#define FILEDLG_FLATFIELD  7
#define FILEDLG_CORR_MASK  8
#define FILEDLG_IMG_DIR    9

static void filedlg_callback (GObject *source_object, GAsyncResult *res, gpointer user_data)
// Open, check and read the file selected from a file choosing dialog for the
// preview master dark or flat field image choices.
{
 GtkFileDialog *file_dialog = GTK_FILE_DIALOG (source_object);
 GError *error = NULL;
 GFile *file;
 int filereq;


 filereq=GPOINTER_TO_INT(user_data);

 switch(filereq){
   case FILEDLG_XYS_SAVE: // Currently the only time I use a 'save' dialog
    file = gtk_file_dialog_save_finish (file_dialog, res, &error);
   break;
   case FILEDLG_IMG_DIR: // Currently the only time I get a directory (not file)
    file = gtk_file_dialog_select_folder_finish (file_dialog, res, &error);
   break;
   default: // All other times I use a load dialog
    file = gtk_file_dialog_open_finish (file_dialog, res, &error);
   break;
 }

 if(error){
   if (error->domain == GTK_DIALOG_ERROR && error->code == GTK_DIALOG_ERROR_DISMISSED){
     g_clear_error (&error);   // The user just closed the dialog without
                               // loading or saving a file. That's not really
                               // an 'error' I want to alert them about.
     switch(filereq){
      case FILEDLG_PCS_LOAD:
        if(Interrupt_script_request){
          if(Interrupt_script_active==0){
             // Block the "toggled" signal handler temporarily
             g_signal_handler_block(G_OBJECT(Chk_stop_pcs), chk_toggle_handler_id);
             // Code to un-check the box
             gtk_check_button_set_active(GTK_CHECK_BUTTON(Chk_stop_pcs), FALSE);
             // Unblock the "toggled" signal handler
             g_signal_handler_unblock(G_OBJECT(Chk_stop_pcs), chk_toggle_handler_id);
           }
          Interrupt_script_request = 0;
          set_interrupt_button_font();
        }
      break;
      default: break;
     }

     return;
    }
   switch(filereq){
     case FILEDLG_IMG_DIR: // Image save path directory
      show_message(error->message,"Save folder: ",MT_ERR,1);
     break;
     case FILEDLG_PCS_LOAD: // Load a PCS
      show_message(error->message,"Script load: ",MT_ERR,1);
     break;
     case FILEDLG_XYS_SAVE: // Save an XYZ-scan PCS
      show_message(error->message,"XYZ Scan script save: ",MT_ERR,1);
     break;
     case FILEDLG_XYS_LOAD: // Load an XYZ-scan
      show_message(error->message,"XYZ Scan load: ",MT_ERR,1);
     break;
     case FILEDLG_XYW_LOAD: // Load weights for an XY scan
      show_message(error->message,"XY Weights load: ",MT_ERR,1);
     break;
     case FILEDLG_HELP_LOAD: // Load a help file
      show_message(error->message,"Help file load: ",MT_ERR,1);
     break;
     case FILEDLG_DARKFIELD: // Load a dark field image
      show_message(error->message,"Dark field load: ",MT_ERR,1);
     break;
     case FILEDLG_FLATFIELD: // Load a flat field image
      show_message(error->message,"Flat field load: ",MT_ERR,1);
     break;
     case FILEDLG_CORR_MASK: // Load a corrections mask
      show_message(error->message,"Mask load: ",MT_ERR,1);
     break;
     default: break; // Only a bug gets here
    }
   g_clear_error (&error);
   return;
  }
 if(file){
   char *filepath = g_file_get_path (file);
   switch(filereq){
     case FILEDLG_IMG_DIR: // Image save directory
       gtk_editable_set_text(GTK_EDITABLE(entry_savepath), filepath);
       sprintf(CPlist[CamIdx].SavePath,"%s", filepath);
       CPlist[CamIdx].Savepath_set = 1;
     break;
     case FILEDLG_DARKFIELD: // Dark field
       gtk_editable_set_text(GTK_EDITABLE(entry_xcoord), filepath);
       sprintf(CPlist[CamIdx].Selected_DF_filename,"%s", filepath);
       dffile_set = 1;
     break;
     case FILEDLG_FLATFIELD: // Flat field
       gtk_editable_set_text(GTK_EDITABLE(entry_xcoord), filepath);
       sprintf(CPlist[CamIdx].Selected_FF_filename,"%s", filepath);
       fffile_set = 1;
     break;
     case FILEDLG_CORR_MASK: // Corrections mask
       gtk_editable_set_text(GTK_EDITABLE(entry_xcoord), filepath);
       sprintf(CPlist[CamIdx].Selected_CM_filename,"%s", filepath);
       cmfile_set = 1;
     break;
     case FILEDLG_XYW_LOAD: // XYS Weights file

       load_and_process_xyw_weights(filepath);

     break;
     case FILEDLG_XYS_LOAD: // XYS file

       load_and_process_xys_scan(filepath);

     break;
     case FILEDLG_PCS_LOAD: // PCS file

       load_and_process_pcs_script(filepath);

     break;
     case FILEDLG_XYS_SAVE: // XYZ Scan PCS file save

      sprintf(xyzs_pcsfile,"%s", filepath);
      save_xyzs_settings();

     break;
     case FILEDLG_HELP_LOAD: // Help file file

        // Read the help file and display it
        load_custom_help_document(filepath);

     break;
     default: break; // Only a bug gets here
    }
   g_free (filepath);
   g_object_unref (file);
  } // If file==NULL the user cancelled the dialog


 return;
}

void send_char_to_pollbox(int dirn)
// send the required character to the user poll entry box in the Script page
// (but only if a script is currently running)
{
 if(script_in_progress==0) return;

 switch(dirn)
 {
  case cX_R: // X Left
    gtk_editable_set_text(GTK_EDITABLE(entry_script_poll), ">");
  break;
  case cX_L: // X Right
    gtk_editable_set_text(GTK_EDITABLE(entry_script_poll), "<");
  break;
  case cY_B: // Y Back
    gtk_editable_set_text(GTK_EDITABLE(entry_script_poll), "v");
  break;
  case cY_F: // Y Forward
    gtk_editable_set_text(GTK_EDITABLE(entry_script_poll), "^");
  break;
  case cZ_D: // Z Down
    gtk_editable_set_text(GTK_EDITABLE(entry_script_poll), "-");
  break;
  case cZ_U: // Z Up
    gtk_editable_set_text(GTK_EDITABLE(entry_script_poll), "+");
  break;
  default: // Programming error
   show_message("Undefined direction button pressed (btn_dirn_click).","Program Error: ",MT_ERR,1);
  break;
 }

 return;
}

static void btn_dirn_click(GtkWidget *widget, gpointer data)
// Manual stage movement command parser function.
{
 char cmd_str[MAX_CMDLEN];
 int32_t reqdirn;
 int have_blob;
 int need_direction_update;
 int returnvalue;
 char errmsg[ERRMSG_LEN];
 uint8_t target_axis=255;

 // Only one GUI message to server at a time.
 if(( BIT_BUSY_RIGHT_NOW ) && (Motion_buttons_diverted==FALSE)) return; 
 if(Motion_buttons_forbidden) return; 
 if(Motion_buttons_insensitive) return;
 
 Manual_movement_active=1; // This is so the motion_ctls_sensitive function is
                           // not activated again till we finish this function
                           // because it may get called by other functions while
                           // run script commands here.
 Motion_buttons_forbidden=TRUE;


 // Set the direction if it has changed from the last used one or is unset.
 switch(*(int *)data)
 {
    case cX_R: // X Left
     reqdirn = !Mv_dir_left;
    break;
    case cX_L: // X Right
     reqdirn = Mv_dir_left;
    break;
    case cY_B: // Y Back
     reqdirn = Mv_dir_back;
    break;
    case cY_F: // Y Forward
     reqdirn = !Mv_dir_back;
    break;
    case cZ_D: // Z Down
     reqdirn = Mv_dir_down;
    break;
    case cZ_U: // Z Up
     reqdirn = !Mv_dir_down;
    break;
    default: // Programming error
     show_message("Undefined direction button pressed (btn_dirn_click).","Program Error: ",MT_ERR,1);
    goto end_btn_dirn_click;
 }

 // Divert to running script if required.
 if(Motion_buttons_diverted){
   switch(*(int *)data){
      case cX_R: // X Left
      case cX_L: // X Right
       if(LK_dir_x<0 || LK_dir_x!=reqdirn){
         LK_dir_x=reqdirn;
         set_curr_xdir(reqdirn);
        }       
      break;
      case cY_B: // Y Back
      case cY_F: // Y Forward
       if(LK_dir_y<0 || LK_dir_y!=reqdirn){
         LK_dir_y=reqdirn;
         set_curr_ydir(reqdirn);
        }        
      break;
      case cZ_D: // Z Down
      case cZ_U: // Z Up
       if(LK_dir_z<0 || LK_dir_z!=reqdirn){        
         LK_dir_z=reqdirn;
         set_curr_zdir(reqdirn);
        }
      break;
      default: // Can't happend as we checked it above.
      break;
   }
   send_char_to_pollbox(*(int *)data);
   goto end_btn_dirn_click;
  }

 // Put this check AFTER the diversion because switching from Script View to
 // Manual tabs will always reset Stage_is_motion_ready to 0. That will avoid
 // a lot of network calls unnecessarily when the using is running a script and
 // just switches over to the manual tab to use the buttons.
 if(!Stage_is_motion_ready){
   // Ensure stage is ready to be moved:
   if(verify_stage_is_ready_for_motion("Motion button",errmsg)){
      show_message(errmsg,"Notice!",MT_INFO,1);
      return;
   } else Stage_is_motion_ready = 1;
  }

 need_direction_update=0;

 switch(*(int *)data)
 {
    case cX_R: // X Left
    case cX_L: // X Right
     if(LK_dir_x<0 || LK_dir_x!=reqdirn){
       sprintf(cmd_str,"act_set 1 0 %"PRId32" %"PRId32,INFO_DIRNC,reqdirn);
       need_direction_update=1;        
      }
    break;
    case cY_B: // Y Back
    case cY_F: // Y Forward
     if(LK_dir_y<0 || LK_dir_y!=reqdirn){
       sprintf(cmd_str,"act_set 1 1 %"PRId32" %"PRId32,INFO_DIRNC,reqdirn);
       need_direction_update=1;        
      }
    break;
    case cZ_D: // Z Down
    case cZ_U: // Z Up
     if(LK_dir_z<0 || LK_dir_z!=reqdirn){
       sprintf(cmd_str,"act_set 1 2 %"PRId32" %"PRId32,INFO_DIRNC,reqdirn);
       need_direction_update=1;        
      }
    break;
    default: // Can't happen as we checked it above.
    break;
 }

 have_blob=0;

 if(need_direction_update){
   returnvalue = effect_script_command(cmd_str, &have_blob);
   // Process the return value (emit standard error messages for errors)
   process_server_returnvalue(returnvalue, have_blob, 1);
   if(returnvalue==TT_OK){ // If the command worked OK, update globals and GUI
     switch(*(int *)data)
      {
       case cX_R: // X Left
       case cX_L: // X Right
         LK_dir_x=reqdirn;
         set_curr_xdir(reqdirn);
       break;
       case cY_B: // Y Back
       case cY_F: // Y Forward
         LK_dir_y=reqdirn;
         set_curr_ydir(reqdirn);
       break;
       case cZ_D: // Z Down
       case cZ_U: // Z Up
         LK_dir_z=reqdirn;
         set_curr_zdir(reqdirn);
       break;
       default: // Can't happend as we checked it above.
       break;
     }
    } else goto end_btn_dirn_click; // No point continuing if there was an error
  }

 // Perform the motion command
 switch(*(int *)data) {
     case cX_R: case cX_L: target_axis = ACT_ID_STAGE_X; break;
     case cY_B: case cY_F: target_axis = ACT_ID_STAGE_Y; break;
     case cZ_D: case cZ_U: target_axis = ACT_ID_STAGE_Z; break;
 }
 if (manage_ena_state("Move button", target_axis, 1, errmsg, 0)) {
     show_message(errmsg, "Error: ", MT_ERR, 1);
     goto end_btn_dirn_click;
 }

 switch(*(int *)data)
 {
    case cX_L: // X Left
    case cX_R: // X Right
       if(client_stage_move("x", Mv_dist_x, errmsg) != TT_OK) {
          show_message(errmsg,"Error!",MT_ERR,1);
          goto end_btn_dirn_click;
         }
    break;
    case cY_F: // Y Forward
    case cY_B: // Y Back
       if(client_stage_move("y", Mv_dist_y, errmsg) != TT_OK) {
          show_message(errmsg,"Error!",MT_ERR,1);
          goto end_btn_dirn_click;
         }
    break;
    case cZ_U: // Z Up
    case cZ_D: // Z Down
       if(client_stage_move("z", Mv_dist_z, errmsg) != TT_OK) {
          show_message(errmsg,"Error!",MT_ERR,1);
          goto end_btn_dirn_click;
         }
    break;
    default: // Programming error
     show_message("Undefined direction button pressed (btn_dirn_click).",
                                                    "Program Error: ",MT_ERR,1);
    goto end_btn_dirn_click;
 }



 end_btn_dirn_click:
 if (target_axis <= ACT_ID_STAGE_Z) {
   if(manage_ena_state("Move button", target_axis, 0, errmsg, 0))
                                        show_message(errmsg,"Error: ",MT_ERR,1);
 }

 update_axis_positions_gui();
 Manual_movement_active=0;
 Motion_buttons_forbidden=FALSE;

 return;
}

