static void btn_XY_getstart_click(GtkWidget *widget, gpointer data)
// Copy the current XYZ stage position into the XYZ-Scan start boxes
{
 gchar *labstr;
 double disp_x;
 double disp_y;
 double disp_z;

 if(units_not_set()){
   show_message("Can't use GUI coordinate processes because the calibration "
                "factors for the stage have not been updated since last login.",
                                                            "FYI: ",MT_INFO, 1);
   return;
  }

 // Scale the variables to match the active user-unit environment
 disp_x = atomic_to_calibunit(PMRep1, ACT_ID_STAGE_X);
 disp_y = atomic_to_calibunit(PMRep2, ACT_ID_STAGE_Y); 
 disp_z = atomic_to_calibunit(PMRep3, ACT_ID_STAGE_Z); 


 labstr = g_strdup_printf("%.9g", disp_x);
 gtk_editable_set_text(GTK_EDITABLE(entry_xyzs_xcoord), labstr);
 g_free(labstr);

 labstr = g_strdup_printf("%.9g", disp_y);
 gtk_editable_set_text(GTK_EDITABLE(entry_xyzs_ycoord), labstr);
 g_free(labstr);

 labstr = g_strdup_printf("%.9g", disp_z);
 gtk_editable_set_text(GTK_EDITABLE(entry_xyzs_zcoord), labstr);
 g_free(labstr);

 return;
}

