static void btn_loadpcs_click(GtkWidget *widget, gpointer data)
// Load and check the script file for syntax and value errors (or decompile .pcl).
{
 GtkFileDialog *file_dialog;
 GListStore *filters;
 GtkFileFilter *all_filter, *pcs_filter, *dove_filter, *pcl_filter;

 // Don't allow a script to be loaded while one is running.
 if (BIT_BUSY_RIGHT_NOW) return;

 filters = g_list_store_new(GTK_TYPE_FILE_FILTER);

 // Combined filter so users see .pcs, .dove, and .pcl files immediately
 all_filter = gtk_file_filter_new();
 gtk_file_filter_add_pattern(all_filter, "*.pcs");
 gtk_file_filter_add_pattern(all_filter, "*.dove");
 gtk_file_filter_add_pattern(all_filter, "*.pcl");
 gtk_file_filter_set_name(all_filter, "All Pardus files (*.pcs, *.dove, *.pcl)");
 g_list_store_append(filters, all_filter);
 g_object_unref(all_filter);

 // .pcs filter
 pcs_filter = gtk_file_filter_new();
 gtk_file_filter_add_pattern(pcs_filter, "*.pcs");
 gtk_file_filter_set_name(pcs_filter, "PCS files (*.pcs)");
 g_list_store_append(filters, pcs_filter);
 g_object_unref(pcs_filter);

 // .dove filter
 dove_filter = gtk_file_filter_new();
 gtk_file_filter_add_pattern(dove_filter, "*.dove");
 gtk_file_filter_set_name(dove_filter, "DOVE files (*.dove)");
 g_list_store_append(filters, dove_filter);
 g_object_unref(dove_filter);

 // .pcl filter
 pcl_filter = gtk_file_filter_new();
 gtk_file_filter_add_pattern(pcl_filter, "*.pcl");
 gtk_file_filter_set_name(pcl_filter, "PCS Library files (*.pcl)");
 g_list_store_append(filters, pcl_filter);
 g_object_unref(pcl_filter);

 file_dialog = gtk_file_dialog_new();
 gtk_file_dialog_set_filters(file_dialog, G_LIST_MODEL(filters));
 gtk_file_dialog_set_title(file_dialog, "Select A Pardus Script (.pcs/.dove) or Library (.pcl)");
 gtk_file_dialog_set_accept_label(file_dialog, "Load File");
 g_object_set(file_dialog, "modal", TRUE, NULL);

 gtk_file_dialog_open(file_dialog,
                      GTK_WINDOW(Win_main),
                      NULL,
                      (GAsyncReadyCallback)filedlg_callback,
                      GINT_TO_POINTER(FILEDLG_PCS_LOAD));

 g_object_unref(filters);
 g_object_unref(file_dialog);
 return;
}

int script_run_timed(PCS_Program *prog, unsigned int *linenum, char *errmsg,
                     void (*sr_callback)(char *))
{
    time_t ts, tf;
    char msgtxt[4500];
    char timestring[512];
    int vtmp, res;

    // Print start banner and capture start time BEFORE running the script
    vtmp = Verbosity;
    Verbosity = default_verbosity();
    snprintf(msgtxt, sizeof(msgtxt), "Running script: %s \n", name_from_path(script_pcsfile));
    show_message(msgtxt, "FYI: ", MT_PCS_I, 0);
    snprintf(msgtxt, sizeof(msgtxt), "Starting Script Execution at: %s",
             (time(&ts) == (time_t)-1) ? "[Time not available]\n" : ctime(&ts));
    show_message(msgtxt, "FYI: ", MT_PCS_I, 0);
    Verbosity = vtmp;

    // Run the script
    script_in_progress = 1;
    res = script_run(prog, linenum, errmsg, sr_callback);
    script_in_progress = 0;

    // Print finish time and elapsed duration
    vtmp = Verbosity;
    Verbosity = default_verbosity();
    snprintf(msgtxt, sizeof(msgtxt), "Finished at: %s",
             (time(&tf) == (time_t)-1) ? "[Time not available]\n" : ctime(&tf));
    show_message(msgtxt, "FYI: ", MT_PCS_I, 0);
    seconds_to_text(elapsed_time(ts, tf), timestring);
    snprintf(msgtxt, sizeof(msgtxt), "That took: %s\n\n", timestring);
    show_message(msgtxt, "FYI: ", MT_PCS_I, 0);
    Verbosity = vtmp;

    if (graphics_mode_active) set_script_console_graphics_mode(false);
    if (!gui_up) cli_reset_print_colour();

    return res;
}

static void btn_runpcs_click(GtkWidget *widget, gpointer data)
// Check and run a script. We check it again in case the user has edited
// the script since it was first successfully loaded and syntax checked.
//
{
 int script_checker_says,sstmp;
 unsigned int linenum;
 FILE *fp = NULL;
 char msgtxt[4500], errmsg[ERRMSG_LEN];
 time_t ts, tf;        // To time how long the script run takes.
 char timestring[512]; // To convert time information into a helpful
                       // string for printing to logs / console.

 // Only one GUI message to server at a time.
 if(BIT_BUSY_RIGHT_NOW) return; 

 // Skip the reading and checking if a compiled main script is ready
 if(program_is_ready(&ProgramSlots[0])){
   goto run_precompiled_script;
  }
 // Do nothing if a syntax-correct script file has not been selected.
 if(script_loaded == 0) return; 
 // However, even if such a script was selected it may have been edited
 // in the interim so check the script again. 

 script_loaded = 0; // This will be set to 1 if successfully checked
 // Disable the 'Run Program' button - it will be re-enabled on success.
 gtk_widget_set_sensitive(widget, FALSE);

 // Read the program file, check it is of correct format and syntax but only if
 // this is a main script (don't do this for the stop script) so we must
 // temporarily set the Interrupt_script_request global to 0 whatever it's value
 // actually is:
 sstmp=Interrupt_script_request;
 Interrupt_script_request = 0;

 fp = fopen(script_pcsfile, "rb");
 if(fp == NULL){
   show_message("Could not read the currently loaded script file."
                                       , "FAILED to Open Program: ", MT_ERR, 1);
   gtk_widget_set_sensitive(widget, TRUE);
   return;
  }
 script_checker_says = script_preprocess(fp, &linenum, errmsg);
 Interrupt_script_request=sstmp; // Restore Interrupt_script_request global value.


    switch(script_checker_says){
    case PCHK_ALL_GOOD: // No errors detected: 
        // Display the newly loaded program name in the script console
        snprintf(msgtxt,4122, "Script pre-processed OK: %s\n", script_pcsfile);
        show_message(msgtxt, "FYI: ", MT_PCS_I, 0);
        fclose(fp); fflush(NULL);
        fp = fopen("_pppcs.pcs", "rb");
        if(fp == NULL){
           show_message("Read access denied to _pppsc.pcs",
                             "FAILED to Load Pre-processed Script: ",MT_ERR, 1);
           goto terminus;
          }
        // =====================================================================
        // NEW STEP: COMPILE DISK FILE INTO IN-MEMORY TOKEN ARRAY
        // =====================================================================
        // This function parses the text stream lines into 'CompiledProgram'
        if (compile_pcs_to_memory(&ProgramSlots[0],fp,errmsg) != PCHK_ALL_GOOD) {
           show_message(errmsg,"FAILED to compile script: ", MT_ERR, 1);
           goto terminus;
        } else {fclose(fp); fflush(NULL); fp=NULL;} // Don't need the file now.
        // =====================================================================
        break;
    case PCHK_TERMINUS: // Program not terminated correctly
        snprintf(msgtxt,sizeof(msgtxt), "[%s][%d]: Failed to terminate correctly.\n",
                                       name_from_path(script_pcsfile), linenum);
        show_message(msgtxt, "FAILED to pre-process script: ", MT_PCS_E, 0);
        break;
    case PCHK_E_SYNTAX: // Syntax error detected
        snprintf(msgtxt,sizeof(msgtxt), "[%s][%d]: Syntax error. %s\n",
                               name_from_path(script_pcsfile), linenum, errmsg);
        show_message(msgtxt, "FAILED to pre-process script: ", MT_PCS_E, 0);
        break;
    case PCHK_E_HEADER_FORMAT: // Incorrect header layout format deep in include stack
        snprintf(msgtxt, sizeof(msgtxt), "%s.\n", errmsg);
        show_message(msgtxt, "FAILED to pre-process script: ", MT_PCS_E, 0);
        break;
    case PCHK_E_COMMND: // Unrecognised command
        snprintf(msgtxt,sizeof(msgtxt), "[%s][%d]: Unrecognised or non-functional command"
                 " \'%s\'.\n", name_from_path(script_pcsfile), linenum, errmsg);
        show_message(msgtxt, "FAILED to pre-process script: ", MT_PCS_E, 0);
        break;
    case PCHK_E_FORMAT: // Incorrect file format
        snprintf(msgtxt,sizeof(msgtxt), "[%s][%d]: Not recognised as a valid Pardus command"
                         " script.\n", name_from_path(script_pcsfile), linenum);
        show_message(msgtxt, "FAILED to pre-process script: ", MT_PCS_E, 0);
        break;
    case PCHK_E_PREPROC: // Pre-processor failed
        snprintf(msgtxt,sizeof(msgtxt), "%s.\n",errmsg);
        show_message(msgtxt, "FAILED to pre-process script: ", MT_PCS_E, 0);
        break;
    case PCHK_E_COMPILE: // Compiler failed
        snprintf(msgtxt,sizeof(msgtxt), "%s.\n",errmsg);
        show_message(msgtxt, "FAILED to compile script: ", MT_PCS_E, 0);
        break;
    default: // This should not happen unless the source code has a bug
        show_message("Script checker returned an unreconised value", 
                                                  "Program Error: ", MT_ERR, 1);
        break;
   }
 if(script_checker_says != PCHK_ALL_GOOD) goto terminus;

 // ============================================================================
 // SCRIPT CHECK NOW RUNS OUT OF A MEMORY ARRAY - NOT READING A THE FILE
 // ============================================================================
run_precompiled_script:
 if(ProgramSlots[0].is_checked) script_checker_says = link_aot_flow_control(&ProgramSlots[0],&linenum, errmsg);
 else script_checker_says = script_check(&ProgramSlots[0],&linenum, errmsg); 
 // ============================================================================

 switch(script_checker_says){
   case PCHK_ALL_GOOD: // No errors detected, so attempt to run it.
    script_loaded = 1;

    // Set up the interrupt button and interactive input controls
    gtk_widget_set_visible(Btn_script_interrupt,TRUE);
    gtk_widget_set_visible(lab_script_poll,TRUE);
    gtk_widget_set_visible(entry_script_poll,TRUE);
    gtk_widget_set_visible(Chk_stop_pcs,FALSE);
    gtk_widget_grab_focus(entry_script_poll);
    UPDATE_GUI

    // Run the script
    // =========================================================================
    // SCRIPT RUN PASSES HANDOFF INTO THE TOKENIZED VIRUAL SCHEDULER
    // =========================================================================
    // script_run discards the file pointer, driving directly through RAM memory
    script_checker_says = script_run_timed(&ProgramSlots[0], &linenum, errmsg, user_callback);
    // =========================================================================

    // Hide the interrupt button and interactive input controls
    gtk_widget_set_visible(Btn_script_interrupt,FALSE);
    gtk_widget_set_visible(lab_script_poll,FALSE);
    gtk_widget_set_visible(entry_script_poll,FALSE);
    gtk_widget_set_sensitive(widget, TRUE);

    // Display the outcome of the script run.
    switch(script_checker_says){
      case PRUN_ALL_GOOD: // Program completed its run with no errors
        show_message("Script completed its run OK.", name_from_path(script_pcsfile), MT_INFO, 1);
        break;
      case PRUN_ERROR: // Program encountered an error
        snprintf(msgtxt,sizeof(msgtxt), "[%s][%d]: %s\n", name_from_path(script_pcsfile), linenum, errmsg);
        show_message(msgtxt, "Script Run-time Error: ", MT_PCS_E, 0);
        show_message(errmsg, "Script Run-time Error: ", MT_ERR, 1);

        if(script_interrupted){
          // If the PRUN_ERROR was due to the user pressing the interrupt button
          // attempt to run a stop script if such a script is set and activated:
          if(Interrupt_script_active){

            // Reset the Verbosity in case the script writer changed it:
            Verbosity = default_verbosity();
            snprintf(msgtxt,sizeof(msgtxt),
                                      "Starting Interrupt Script Execution at: %s\n",
                           ((time(&ts))==-1)?"[Time not available]":ctime(&ts));
            show_message(msgtxt, "FYI: ", MT_PCS_I, 0);

            // Run verification check on the memory-compiled STOP script structures
            if(ProgramSlots[1].is_checked) script_checker_says = link_aot_flow_control(&ProgramSlots[1],&linenum, errmsg);
            else script_checker_says = script_check(&ProgramSlots[1],&linenum, errmsg);
            
            if(script_checker_says == PCHK_ALL_GOOD){
              // Show the interrupt button and interactive input controls
              gtk_widget_set_visible(Btn_script_interrupt,TRUE);
              gtk_widget_set_visible(lab_script_poll,TRUE);
              gtk_widget_set_visible(entry_script_poll,TRUE);
              
              // Run the STOP script from memory out of the array
              script_in_progress = 1;
              script_checker_says = script_run(&ProgramSlots[1],&linenum, errmsg, user_callback);
              script_in_progress = 0;
              
              // Hide the interrupt button and interactive input controls
              gtk_widget_set_visible(Btn_script_interrupt,FALSE);
              gtk_widget_set_visible(lab_script_poll,FALSE);
              gtk_widget_set_visible(entry_script_poll,FALSE);

              if(script_checker_says == PRUN_ALL_GOOD){
                show_message("Interrupt script completed its run OK.","Interrupt script",
                                                                    MT_INFO, 1);
                snprintf(msgtxt,sizeof(msgtxt), "Finished at: %s",
                            ((time(&tf))==-1)?"[Time not available]":ctime(&tf));
                show_message(msgtxt, "FYI: ", MT_PCS_I, 0);
                seconds_to_text(elapsed_time(ts, tf), timestring);
                snprintf(msgtxt,sizeof(msgtxt),"That took: %s\n\n", timestring);
                show_message(msgtxt, "FYI: ", MT_PCS_I, 0);

               } else {
                    snprintf(msgtxt,sizeof(msgtxt), "[Interrupt script][%d]: %s\n",
                                                               linenum, errmsg);
                    show_message(msgtxt, "Script Run-time Error: ", MT_PCS_E,0);
                    show_message(errmsg, "Script Run-time Error: ", MT_ERR, 1);
                   }              
             } else {
              snprintf(msgtxt,sizeof(msgtxt), "[STOP script FAILED][%d]:"
                                        " Syntax error. %s\n", linenum, errmsg);
              show_message(msgtxt, "FAILED to verify script: ", MT_PCS_E, 0);
             }

           }
         }

        break;
      default: // Should not happen unless the source code was altered wrongly
        show_message("Script Interpreter returned an unrecognised value", "Program Error: ", MT_ERR, 1);
        break;
     }

    break;
   case PCHK_TERMINUS: // Program not terminated correctly
    snprintf(msgtxt,sizeof(msgtxt), "[%s][%d]: Failed to terminate correctly.\n", name_from_path(script_pcsfile), linenum);
    show_message(msgtxt, "FAILED to verify script: ", MT_PCS_E, 0);
    break;
   case PCHK_E_SYNTAX: // Syntax error detected
    snprintf(msgtxt,sizeof(msgtxt), "[%s][%d]: Syntax error. %s\n", name_from_path(script_pcsfile), linenum, errmsg);
    show_message(msgtxt, "FAILED to verify script: ", MT_PCS_E, 0);
    break;
   case PCHK_E_COMMND: // Unrecognised command
    snprintf(msgtxt,sizeof(msgtxt), "[%s][%d]: Unrecognised command \'%s\'.\n", name_from_path(script_pcsfile), linenum, errmsg);
    show_message(msgtxt, "FAILED to verify script: ", MT_PCS_E, 0);
    break;
   case PCHK_E_FORMAT: // Incorrect file format
    snprintf(msgtxt,sizeof(msgtxt), "[%s][%d]: Not recognised as a valid Pardus command script.\n", name_from_path(script_pcsfile), linenum);
    show_message(msgtxt, "FAILED to verify script: ", MT_PCS_E, 0);
    break;
   default: // Should not happen unless the source code was altered wrongly
    show_message("Script interpreter returned an unreconised value", "Program Error: ", MT_ERR, 1);
    break;
  }

 terminus:
  // Only close the file descriptor if it hasn't been closed or cleared already
  if (fp != NULL) {
      fclose(fp);
      fp = NULL; 
  }

 // Re-show the stop script loader check box in case it was hidden
 gtk_widget_set_visible(Chk_stop_pcs,TRUE);

 // Reset the Verbosity in case the script writer changed it:
 Verbosity = default_verbosity();
 // Reset the default print formatting in case the script writer changed it:
 Print_overwrite=0; Print_newline=1; Print_debug=1; 


 return;
}

