static void btn_sync_stage_click(GtkWidget *widget, gpointer data)
// Attempt to synchronise the current stage with the settings from the 
// currently rendered scan loaded from file
{
 char errmsg[ERRMSG_LEN];
 GtkAlertDialog *dlg_choice;
 uint8_t syncx,syncy,syncz;

 Coordsync_needed = 0;

 // Do nothing if not logged into a pardserver
 if(!logged_in){
    show_message("You are not logged into a pardserver. Sync actions are only"
                           " avalable to logged in users.","Notice!",MT_INFO,1);
    return;
  }

 // Only one GUI message to server at a time.
 if(BIT_BUSY_RIGHT_NOW) return; 

 if(!Stage_is_motion_ready){
   // Ensure stage is ready to be moved:
   if(verify_stage_is_ready_for_motion("Go To button",errmsg)){
      show_message(errmsg,"Notice!",MT_INFO,1);
      return;
   } else Stage_is_motion_ready = 1;
  }

 // We don't 'sync' to live variables - they are already 'synced':
 if(XYSlist[SC_CURR].RenderIdx < 2){
   show_message("Can't sync stage to a live scan struct. Load a saved scan from"
                      " disc if you want to do a sync.","Notice: ", MT_INFO, 1);
   return;
  }

 //  Check sync status of coordinates if there is a tile selected
 if (CurrSelectedTile.hasselection) {
     // Validate array tracking bounds before lookups
     if (CurrSelectedTile.pdx >= XYSlist[SC_CURR].NSPs) {
        show_message("Active tile selection index out of bounds so coordinate "
                                 "sync cannot be done.","Notice: ", MT_INFO, 1);
        syncx=syncy=syncz=0;
     } else {

      // Compare current postion to the raw microstep coordinates of the tile
      syncx=(PMRep1 == XYSlist[SC_CURR].SPlist[CurrSelectedTile.pdx].x)?0:1;
      syncy=(PMRep2 == XYSlist[SC_CURR].SPlist[CurrSelectedTile.pdx].y)?0:1;
      syncz=(PMRep3 == XYSlist[SC_CURR].SPlist[CurrSelectedTile.pdx].z)?0:1;
     }
  } else syncx=syncy=syncz=0;


 // Update the sync status in case something changed since last we checked:
 update_stage_sync_status(SC_CURR);

 // Is the currently loaded scan synced to this stage?
 if(XYSlist[SC_CURR].Stage.Synced_stage && !(syncx+syncy+syncz)) {
   show_message("Stage is already in sync with current scan parameters.",
                                                        "Notice: ", MT_INFO, 1);
     return;
 }

 
 // Set up the confirmation dialog
 dlg_choice = gtk_alert_dialog_new("%s", "Really sync the stage?");
 if (dlg_choice == NULL) return;

 gtk_alert_dialog_set_buttons(dlg_choice, YNbuttons);
 gtk_alert_dialog_set_default_button(dlg_choice, 1);

 show_message("Stage sync request occurred.","\nNotice!: ",MT_INFO,0);

 gtk_alert_dialog_set_detail(GTK_ALERT_DIALOG(dlg_choice),
                 "Do you really want to sync the stage?\nThis will change stage"
                             " parameters and cannot be automatically undone.");

 if((syncx+syncy+syncz)) Coordsync_needed = 1;


 gtk_alert_dialog_choose (GTK_ALERT_DIALOG(dlg_choice),
                          GTK_WINDOW (Win_main),
                          NULL,
                          (GAsyncReadyCallback) on_choice_response,
                          GINT_TO_POINTER(CHOICE_SYNC_STAGE));

 return;
}

