static void on_choice_response (GObject *source_object, GAsyncResult *res, gpointer user_data)
{
 int asker;
 GtkAlertDialog *dialog = GTK_ALERT_DIALOG(source_object);
 GError *error = NULL;
 GtkApplication *app;

 gint response_id = gtk_alert_dialog_choose_finish(dialog, res, &error);

 asker=GPOINTER_TO_INT(user_data);

 // Process the response_id
 if(error){
   if(!(error->domain == GTK_DIALOG_ERROR && error->code == GTK_DIALOG_ERROR_DISMISSED)){
      show_message(error->message,"Could not process your response: ",MT_ERR,1);
     }
   g_clear_error (&error);
  } else if (response_id == 1) { // YES was index 1
   switch(asker){
      case CHOICE_RELISTEN_SRV:
      break; // Already listenting so just break
      case CHOICE_QUIT_PROGRAM:
       // Need this to log out before gui goes down.
       if(logged_in) update_message_header();
       // Now quit
       app = gtk_window_get_application (GTK_WINDOW(Win_main));
       gtk_window_destroy(GTK_WINDOW(Win_main));
       g_application_quit(G_APPLICATION(app));
      break;
      case CHOICE_SYNC_STAGE:
        effect_stage_sync();
      break;
      case CHOICE_SYNC_CAMERA:
        effect_camera_sync();
      break;
      default:
      break;
     }
  } else { // No
   switch(asker){
      case CHOICE_RELISTEN_SRV: 
       sv_Keep_listening = 0;
      break;
      case CHOICE_QUIT_PROGRAM: 
      break;
      case CHOICE_SYNC_STAGE: 
        Coordsync_needed = 0;
      break;
      case CHOICE_SYNC_CAMERA:
      break;
      default:
      break;
     }
    }
 return;
}

static gboolean on_close_request (GtkWindow *window,  gpointer data)
// Things to do before the GUI goes down
{
 GtkAlertDialog *dlg_choice;
 
 // FIXED: Enforced a clean literal string format mask to protect constructor tracking!
 dlg_choice = gtk_alert_dialog_new("%s", "Quit PARDclient?");
 if (dlg_choice == NULL) return TRUE;

 gtk_alert_dialog_set_buttons(dlg_choice, YNbuttons);
 gtk_alert_dialog_set_default_button(dlg_choice, 1);

 show_message("Close request occurred.","\nNotice!: ",MT_INFO,0);

 gtk_alert_dialog_set_detail(GTK_ALERT_DIALOG(dlg_choice),
             "Do you really want to quit?\nYou will be logged off the server.");

 gtk_alert_dialog_choose (GTK_ALERT_DIALOG(dlg_choice),
                          GTK_WINDOW (Win_main),
                          NULL,
                          (GAsyncReadyCallback) on_choice_response,
                          GINT_TO_POINTER(CHOICE_QUIT_PROGRAM));
 return TRUE;
}

static void btn_interrupt1_click(GtkWidget *widget, gpointer data)
// Interrupt communications with server (if confirmed, user will need to restart
// the program)
{
 GtkAlertDialog *dlg_choice;

 // Enforced a clean literal string format mask to protect constructor tracking.
 dlg_choice = gtk_alert_dialog_new("%s", "Re-Listen for Server Response?");
 
 // INSTANCE GUARD GATE: Abort immediately if the window system fails to build
 // the widget
 if (dlg_choice == NULL) {
     g_printerr("GTK Critical: Failed to instantiate choice dialog.\n");
     return;
 }

 gtk_alert_dialog_set_buttons(dlg_choice, YNbuttons);
 gtk_alert_dialog_set_default_button(dlg_choice, 1);
 gtk_alert_dialog_set_detail(GTK_ALERT_DIALOG(dlg_choice),
  "The server is taking a long time to respond. This may be NORMAL if you"
  " requested a process that takes time to complete so just wait a while then"
  " re-listen for a response. In other cases it may be due to a network"
  " error.\nNOTE: You can ONLY continue with this program if you get a response"
  " from the server. If you repeatedly fail to do so you should save any work"
  " and close this program and try again another time.");

 GtkWindow *parent_win = (Win_main != NULL) ? GTK_WINDOW(Win_main) : NULL;
 gtk_alert_dialog_choose (GTK_ALERT_DIALOG(dlg_choice), parent_win,
                          NULL, // cancellable
                          (GAsyncReadyCallback) on_choice_response, 
                          GINT_TO_POINTER(CHOICE_RELISTEN_SRV)); // user data
 // Keep listening while the user makes up their mind
 sv_Keep_listening = 1;
 return;
}

