gboolean on_search_key_pressed(GtkEventControllerKey *controller, guint keyval, 
                               guint keycode, guint state, gpointer user_data)
// Reverse search ([Shift]+[Enter]) callback for help page
{
 if (user_data == NULL) return FALSE;
 GtkEntry *entry = GTK_ENTRY(user_data);

 // Check if the pressed key is either the standard Enter or keypad Return key
 if(keyval == GDK_KEY_Return || keyval == GDK_KEY_KP_Enter){
   // Explicitly isolate the Shift modifier bit mask state.
   if(state & GDK_SHIFT_MASK){
     // Shift is actively held down -> Search Backward
     execute_document_text_find_backward(entry);
    }

   // Return TRUE to tell GTK we fully handled the key event, 
   // preventing the entry widget from making alert beep sounds.
   return TRUE; 
  }

 return FALSE; // Let all other typing keys pass through safely
}

void on_help_font_size_changed(GtkSpinButton *spin_button, gpointer user_data)
{
 // Retrieve the active point value from the spin button
 int pt_size = (int)gtk_spin_button_get_value(spin_button);
 
 // Construct a clean CSS string specifying the point font-size rule
 char css_buffer[128];
 snprintf(css_buffer, sizeof(css_buffer), 
          "#help-text-canvas {\n"
          "  font-size: %dpt;\n"
          "}", pt_size);
          
 // Overwrite the provider contents with the new size configuration
 gtk_css_provider_load_from_string(Help_Font_Css_Provider, css_buffer);
}

