static void chk_stop_pcs_toggle(GtkCheckButton* toggle_button, gpointer entry_p)
// Toggle whether to use a custom stop script after a main script is interrupted
{
 if(gtk_check_button_get_active(toggle_button)){
  // If the user checks this box we automatically show the file select dialog to
  // load a stop script.
  GtkFileDialog *file_dialog;
  GListStore *filters;
  GtkFileFilter *pcs_filter,*dove_filter;
 
  // This lets the file loader, preprocessor, checker etc. all know we are
  // dealing with a request for a stop script, not a main script.
  Interrupt_script_request = 1;
  Interrupt_script_active=0;
 
 // Set up the 'file load' dialogue with the PCS file filter
  // Create a GListStore to hold the filters
  filters = g_list_store_new (GTK_TYPE_FILE_FILTER);

  // Create the .txt filter
  pcs_filter = gtk_file_filter_new ();
  gtk_file_filter_add_pattern (pcs_filter, "*.pcs");
  gtk_file_filter_set_name (pcs_filter, "PCS files");
  g_list_store_append (filters, pcs_filter); // Add to the list store
  g_object_unref(pcs_filter); // GListStore takes a reference

  // Create the .dove filter
  dove_filter = gtk_file_filter_new ();
  gtk_file_filter_add_pattern (dove_filter, "*.dove");
  gtk_file_filter_set_name (dove_filter, "DOVE files");
  g_list_store_append (filters, dove_filter); // Add to the list store
  g_object_unref(dove_filter); // GListStore takes a reference

  // Create the 'file load' dialogue  
  file_dialog = gtk_file_dialog_new ();
  gtk_file_dialog_set_filters (file_dialog, G_LIST_MODEL (filters));
  // Set the purpose of the dialog
  gtk_file_dialog_set_title(file_dialog, "Select a PCS Interrupt Script");
  // Set the text for the primary action button ("Load").
  gtk_file_dialog_set_accept_label(file_dialog, "Load File");
  g_object_set(file_dialog, "modal", TRUE, NULL); // Ensure it's modal
  // Show the file_dialog
  gtk_file_dialog_open (file_dialog,
                        GTK_WINDOW (Win_main),
                        NULL,
                        (GAsyncReadyCallback) filedlg_callback,
                        GINT_TO_POINTER(FILEDLG_PCS_LOAD));

  // Clean up / free the filters list store and file dialog
  g_object_unref(filters);
  g_object_unref(file_dialog); 
 } else {
  // If the user un-checks this box we disable the use of any stop script.
  Interrupt_script_active = 0;
  Interrupt_script_request = 0;
  set_interrupt_button_font();
 }
}

