static void chk_divert_motion_btns_toggle(GtkCheckButton* toggle_button, gpointer entry_p)
// Toggle whether to divert manual direction button output to script pollbox
{
 int cmdopt;

 if(gtk_check_button_get_active(toggle_button)){
   Motion_buttons_diverted = TRUE;
   Motion_buttons_forbidden=FALSE;
   // If the buttons box is already sensitive, remove the green border
   if(!Motion_buttons_insensitive){
     gtk_widget_remove_css_class(axis_button_box, "active-indicator");
     gtk_widget_remove_css_class(focus_button_box, "active-indicator");
     }
   motion_ctls_sensitive(TRUE);
 } else {
  Motion_buttons_diverted = FALSE;
  // Ensure red border is removed
  gtk_widget_remove_css_class(axis_button_box, "diverted-indicator");
  gtk_widget_remove_css_class(focus_button_box, "diverted-indicator");
  if(!Stage_is_motion_ready) motion_ctls_sensitive(FALSE);
  else {
        cmdopt = (int)(gtk_drop_down_get_selected(GTK_DROP_DOWN(Combo_cmd)));
        if(cmdopt == MOVEBY_DISTANCE){
          if(motion_btns_ok_for_manual()) motion_ctls_sensitive(TRUE);
         } else motion_ctls_sensitive(FALSE);
       }
  // Reset last known directions
  LK_dir_x = -1; // Negative means unset
  LK_dir_y = -1; // Negative means unset
  LK_dir_z = -1; // Negative means unset
 }
}

