void colbtn_voidspace_set(GtkColorDialogButton *button, 
                                         GParamSpec *pspec, 
                                         gpointer user_data)
{
  const GdkRGBA *current_color;

  // Call the function with only ONE argument (the button)
  current_color = gtk_color_dialog_button_get_rgba(button);

  // Copy the returned color data into the global variable
  vs_col.red   = current_color->red;
  vs_col.green = current_color->green;
  vs_col.blue  = current_color->blue;
  vs_col.alpha = current_color->alpha;

  // Re-paint the non-tissue areas with the new colour
  colour_void_tiles();
  
  return;
}

void colbtn_selectile_set(GtkColorDialogButton *button, 
                                         GParamSpec *pspec, 
                                         gpointer user_data)
{
 const GdkRGBA *current_color;
 unsigned char rd,gn,bl;
 
 // Call the function with only ONE argument (the button)
 current_color = gtk_color_dialog_button_get_rgba(button);

 // Copy the returned color data into the global variable
 st_col.red   = current_color->red;
 st_col.green = current_color->green;
 st_col.blue  = current_color->blue;
 st_col.alpha = current_color->alpha;

 rd=(unsigned char)(st_col.red*255.0);
 gn=(unsigned char)(st_col.green*255.0);
 bl=(unsigned char)(st_col.blue*255.0);
 
 CurrSelectedTile.rd=rd;
 CurrSelectedTile.gn=gn;
 CurrSelectedTile.bl=bl;
 
 return;
}

