static void btn_copycoord_click(GtkWidget *widget, gpointer entry_clipboard)
// Concatenates checked target entries safely into the clipboard string
{
 char coordstring[MAX_ARGLEN]; // Expanded to safely hold three high-precision float strings
 const char *tx = NULL;
 const char *ty = NULL;
 const char *tz = NULL;

 // We initialize the string buffer to safe defaults 
 snprintf(coordstring, sizeof(coordstring), "0 0 0");

 switch(clipboard_source){
     case CBS_MXYZ:
        tx = gtk_editable_get_text(GTK_EDITABLE(entry_xcoord));
        ty = gtk_editable_get_text(GTK_EDITABLE(entry_ycoord));
        tz = gtk_editable_get_text(GTK_EDITABLE(entry_zcoord));
        if(nonegfloat(tx, "X") || nonegfloat(ty, "Y") || nonegfloat(tz, "Z")) return;
        snprintf(coordstring, sizeof(coordstring), "%s %s %s", tx, ty, tz);       
     break;
     case CBS_MZ:
        tz = gtk_editable_get_text(GTK_EDITABLE(entry_zcoord));
        if(nonegfloat(tz, "Z")) return;
        snprintf(coordstring, sizeof(coordstring), "0 0 %s", tz);     
     break;
     case CBS_XYS_S:
        tx = gtk_editable_get_text(GTK_EDITABLE(entry_xyzs_xcoord));
        ty = gtk_editable_get_text(GTK_EDITABLE(entry_xyzs_ycoord));
        tz = gtk_editable_get_text(GTK_EDITABLE(entry_xyzs_zcoord));
        if(nonegfloat(tx, "Start X") || nonegfloat(ty, "Start Y") || nonegfloat(tz, "Start Z")) return;
        snprintf(coordstring, sizeof(coordstring), "%s %s %s", tx, ty, tz);       
     break;
     case CBS_XYS_F:
        tx = gtk_editable_get_text(GTK_EDITABLE(entry_xyf_xcoord));
        ty = gtk_editable_get_text(GTK_EDITABLE(entry_xyf_ycoord));
        if(nonegfloat(tx, "End X") || nonegfloat(ty, "End Y")) return;
        snprintf(coordstring, sizeof(coordstring), "%s %s 0", tx, ty);       
     break;
     case CBS_XYS_Z:
        tz = gtk_editable_get_text(GTK_EDITABLE(entry_xyzs_zcoord));
        if(nonegfloat(tz, "Start Z")) return;
        snprintf(coordstring, sizeof(coordstring), "0 0 %s", tz);     
     break;
     default:
     break;
 }
    
 gtk_editable_set_text(GTK_EDITABLE(entry_clipboard), coordstring);
 return;
}

static void btn_copyxysv_click(GtkWidget *widget, gpointer entry_clipboard)
// Copy from the XYZ Scan Viewer 'Go To XYZ' coordinates
{
 char coordstring[MAX_ARGLEN]; // Expanded to prevent string formatting buffer truncation faults
 
 // FIXED: Isolate strings from your true target entry fields cleanly inside stack memory
 const char *tx = gtk_editable_get_text(GTK_EDITABLE(entry_xyzs_x));
 const char *ty = gtk_editable_get_text(GTK_EDITABLE(entry_xyzs_y));
 const char *tz = gtk_editable_get_text(GTK_EDITABLE(entry_xyzs_z));

 if(nonegfloat(tx, "Start X")) return;
 if(nonegfloat(ty, "Start Y")) return;
 if(nonegfloat(tz, "Start Z")) return;
 
 // FIXED: Swapped out the old mismatched entry_xyzs_x/y/z variables and replaced them 
 // with your synchronized, validated local string pointers!
 snprintf(coordstring, sizeof(coordstring), "%s %s %s", tx, ty, tz);        
    
 gtk_editable_set_text(GTK_EDITABLE(entry_clipboard), coordstring);
 return;
}

static void btn_copycpos_click(GtkWidget *widget, gpointer entry_clipboard)
// Copy the current dynamically scaled coordinates to your clipboard entry box
// securely in GTK4
{
 char coordstring[32];

 // Prevent copying unit-stale or zeroed parameters on uncalibrated sessions
 if(units_not_set()){
   show_message("Can't copy coordinates because the calibration factors "
                "for the stage have not been updated since last login.",
                                                            "FYI: ", MT_INFO, 1);
   return;
  }

 //  Isolate memory strings into local frame boundaries to protect against
 //  GTK4 lifecycle drops
 const char *raw_x = gtk_label_get_text(GTK_LABEL(Lab_Xctr));
 const char *raw_y = gtk_label_get_text(GTK_LABEL(Lab_Yctr));
 const char *raw_z = gtk_label_get_text(GTK_LABEL(Lab_Zctr));

 if(nonegfloat(raw_x, "Label X")) return;
 if(nonegfloat(raw_y, "Label Y")) return;
 if(nonegfloat(raw_z, "Label Z")) return;
 
 snprintf(coordstring, sizeof(coordstring), "%s %s %s", raw_x, raw_y, raw_z);       
 gtk_editable_set_text(GTK_EDITABLE(entry_clipboard), coordstring);
 
 return;
}

static void btn_pastecoord_click(GtkWidget *widget, gpointer entry_clipboard)
// Paste checked coordinates to their active target configurations safely under
// GTK4
{
 char coordstring[32];
 gchar xstr[32], ystr[32], zstr[32];
 int argcount;
 size_t len;
 
 // FIXED: Extracted widget return string safely into a localized pointer handle
 const char *clip_text = gtk_editable_get_text(GTK_EDITABLE(entry_clipboard));
 len = strlen(clip_text);   
 if(len > 31){
     show_message("There is too much text in the clipboard"
                       " (max. 31 chars allowed).", "Can't Paste: ", MT_ERR, 1);
     return;
 }
 snprintf(coordstring, sizeof(coordstring), "%s", clip_text);
 
 argcount = arg_count(coordstring);            
 if(argcount != 3){
     show_message("Exactly 3 numbers must be provided in the clipboard.",
                                                    "Can't Paste: ", MT_ERR, 1);
     return;
 }
   
 // Added strict width constraint sizing (%31s) to avoid stack buffer overflows
 sscanf(coordstring, "%31s %31s %31s", xstr, ystr, zstr);
 argcount = 0; 
 if(nonegfloat(xstr, "X")) argcount++;
 if(nonegfloat(ystr, "Y")) argcount++;
 if(nonegfloat(zstr, "Z")) argcount++;
 if(argcount) return;
 
 switch(clipboard_source){
     case CBS_MXYZ:
        gtk_editable_set_text(GTK_EDITABLE(entry_xcoord), xstr);
        gtk_editable_set_text(GTK_EDITABLE(entry_ycoord), ystr);
        gtk_editable_set_text(GTK_EDITABLE(entry_zcoord), zstr);
     break;
     case CBS_MZ:
        gtk_editable_set_text(GTK_EDITABLE(entry_zcoord), zstr);
     break;
     case CBS_XYS_S:
        gtk_editable_set_text(GTK_EDITABLE(entry_xyzs_xcoord), xstr);
        gtk_editable_set_text(GTK_EDITABLE(entry_xyzs_ycoord), ystr);
        gtk_editable_set_text(GTK_EDITABLE(entry_xyzs_zcoord), zstr);
     break;
     case CBS_XYS_F:
        gtk_editable_set_text(GTK_EDITABLE(entry_xyf_xcoord), xstr);
        gtk_editable_set_text(GTK_EDITABLE(entry_xyf_ycoord), ystr);
     break;
     case CBS_XYS_Z:
        gtk_editable_set_text(GTK_EDITABLE(entry_xyzs_zcoord), zstr);
     break;
     default:
     break;
 }
 
 return;
}

void set_label_text(GtkWidget *label, const gchar *text)
// Convenience function to correctly set/change the text in a GTK
// label widget (plain text, without special formatting).
{
 gchar* cbs;
 cbs = g_strdup(text);
 gtk_label_set_text(GTK_LABEL(label), cbs);
 g_free(cbs);

 return;
}

void motion_ctls_sensitive(gboolean vistate)
{

 // Don't enact this if we are in the middle of a manual control movement:
 if(Manual_movement_active) return;
 Motion_buttons_insensitive=!vistate;
 gtk_widget_set_sensitive(btn_send_mc,(vistate==TRUE)?FALSE:TRUE);

 if (vistate) {
   if(Motion_buttons_diverted){
     // Add red border when diverted
     gtk_widget_add_css_class(axis_button_box, "diverted-indicator");
     gtk_widget_add_css_class(focus_button_box, "diverted-indicator");
    } else {
     // Add green border when active
     gtk_widget_add_css_class(axis_button_box, "active-indicator");
     gtk_widget_add_css_class(focus_button_box, "active-indicator");
   }
 } else {
     // Remove border colour when inactive
   if(Motion_buttons_diverted){
     //Remove red border when becomming non-diverted
     gtk_widget_remove_css_class(axis_button_box, "diverted-indicator");
     gtk_widget_remove_css_class(focus_button_box, "diverted-indicator");
    } else {
     // Removed green border when becoming de-active
     gtk_widget_remove_css_class(axis_button_box, "active-indicator");
     gtk_widget_remove_css_class(focus_button_box, "active-indicator");
   }
 }


 return;
}

void hide_all_cmd_ctls(void)
{
    gtk_widget_set_visible(GTK_WIDGET(Combo_axis),FALSE);
    gtk_widget_set_visible(entry_xcoord,FALSE); gtk_editable_set_text(GTK_EDITABLE(entry_xcoord), "");
    gtk_widget_set_visible(entry_ycoord,FALSE); gtk_editable_set_text(GTK_EDITABLE(entry_ycoord), "");
    gtk_widget_set_visible(entry_zcoord,FALSE); gtk_editable_set_text(GTK_EDITABLE(entry_zcoord), "");
    gtk_widget_set_visible(lab_xedit,FALSE);
    gtk_widget_set_visible(lab_yedit,FALSE);
    gtk_widget_set_visible(lab_zedit,FALSE);
    gtk_widget_set_visible(lab_axis,FALSE);
    gtk_widget_set_visible(lab_freeform,FALSE);
    gtk_widget_set_visible(entry_freeform,FALSE);
    gtk_widget_set_visible(btn_corrimg_file,FALSE);
    if(Motion_buttons_diverted==FALSE) motion_ctls_sensitive(FALSE);
    return;
}

int motion_btns_ok_for_manual(void)
// Returns 1 if minimum requirements are met to do manual motion commands
// Returns 0 otherwise
{
 char errmsg[ERRMSG_LEN];

 // These tests only apply when the buttons are configured for manual motion,
 // not diverted to a script:
 if(Motion_buttons_diverted) return 0;

 if(!Stage_is_motion_ready){
   // Ensure stage is ready to be moved:
   if(verify_stage_is_ready_for_motion("motion buttons",errmsg)){
      show_message(errmsg,"Notice!",MT_INFO,1);
      return 1;
   } else Stage_is_motion_ready = 1;
  }

 return 0;
}

void show_cmd_ctls(int cmd)
{
 switch(cmd){
    case MOVEBY_DISTANCE:
    case GOTO_XYZ:
        gtk_widget_set_visible(entry_xcoord,TRUE); gtk_widget_set_visible(lab_xedit,TRUE);
        gtk_widget_set_visible(entry_ycoord,TRUE); gtk_widget_set_visible(lab_yedit,TRUE);
        gtk_widget_set_visible(entry_zcoord,TRUE); gtk_widget_set_visible(lab_zedit,TRUE);
        if(motion_btns_ok_for_manual()) motion_ctls_sensitive(TRUE);
        break;
    case SET_DIRECTIONS:
    case ACT_ACCEL:
        gtk_widget_set_visible(entry_xcoord,TRUE); gtk_widget_set_visible(lab_xedit,TRUE);
        gtk_widget_set_visible(entry_ycoord,TRUE); gtk_widget_set_visible(lab_yedit,TRUE);
        gtk_widget_set_visible(entry_zcoord,TRUE); gtk_widget_set_visible(lab_zedit,TRUE);
        break;
    case MS_DENOM:
        gtk_widget_set_visible(GTK_WIDGET(Combo_axis),TRUE);   gtk_widget_set_visible(lab_axis,TRUE);
        gtk_widget_set_visible(entry_xcoord,TRUE); gtk_widget_set_visible(lab_xedit,TRUE);
        break;
    case TC_THRESHOLD:
        gtk_widget_set_visible(entry_xcoord,TRUE); gtk_widget_set_visible(lab_xedit,TRUE);
        gtk_widget_set_visible(entry_ycoord,TRUE); gtk_widget_set_visible(lab_yedit,TRUE);
        break;
    case FF_CORRECTION:
    case DF_CORRECTION:
    case CORRECTIONS_MASK:
        gtk_widget_set_visible(GTK_WIDGET(Combo_axis),TRUE);   gtk_widget_set_visible(lab_axis,TRUE);
        break;
    case CAMERA_SET:
        gtk_widget_set_visible(GTK_WIDGET(Combo_axis),TRUE);   gtk_widget_set_visible(lab_axis,TRUE);
        gtk_widget_set_visible(entry_xcoord,TRUE); gtk_widget_set_visible(lab_xedit,TRUE);
        break;
    case SAVE_COORDS:
    case SAVE_FORMAT:
    case SAVE_DOUBLES:
    case SAVE_RESOLUTION:
        gtk_widget_set_visible(GTK_WIDGET(Combo_axis),TRUE);  gtk_widget_set_visible(lab_axis,TRUE);
        break;
    case GET_TC_VALUE:
        // The ON/OFF selector and is label
        gtk_widget_set_visible(GTK_WIDGET(Combo_axis),TRUE);  gtk_widget_set_visible(lab_axis,TRUE);
        // We'll use this label to contain the constant 'CurrTC = "
        gtk_widget_set_visible(lab_xedit,TRUE);
        // We'll use this label to print the numerical value of CurrTC
        gtk_widget_set_visible(lab_yedit,TRUE);
        break;
    case GET_PREVIEW:
        gtk_widget_set_visible(GTK_WIDGET(Combo_axis),TRUE);  gtk_widget_set_visible(lab_axis,TRUE);
        gtk_widget_set_visible(entry_xcoord,TRUE); gtk_widget_set_visible(lab_xedit,TRUE);
        gtk_widget_set_visible(entry_ycoord,TRUE); gtk_widget_set_visible(lab_yedit,TRUE);
        break;
    case FRAME_NUMBER:
    case SELECT_CAMERA:
    case SKIP_FRAMES:
    case FRAMES_TO_SKIP:
    case FRAMES_TO_AVG:
    case YUYV_GAIN:
    case YUYV_BIAS:
        gtk_widget_set_visible(entry_xcoord,TRUE);
        gtk_widget_set_visible(lab_xedit,TRUE);
        break;
    case SAVE_ROOT:
        gtk_widget_set_visible(entry_xcoord,TRUE);
        gtk_widget_set_visible(lab_xedit,TRUE);
        if(NCPs)
          if(CPlist[CamIdx].Imroot_set)
            gtk_editable_set_text(GTK_EDITABLE(entry_xcoord), CPlist[CamIdx].ImRoot);
        break;
    case FREE_FORM:
        gtk_widget_set_visible(entry_freeform,TRUE); gtk_widget_set_visible(lab_freeform,TRUE);
        break;
    case GRAB_IMAGE:      // Leave as is
    case AUTOFOCUS:       // Leave as is
    case GET_AXES:        // Leave as is
        break;
    default: // This should not happen unless someone modifies this source code wrongly
        show_message("Unknown command option.", "Program Error: ", MT_ERR, 1);
        break;
  }
 return;
}

static void combo_cmd_changed(GtkDropDown* comcmd, GParamSpec *pspec, gpointer axopt)
{
 gint idx, cmd;
 char msgtxt[32];
 GtkStringList *new_model;

 // Remove all strings from the drip down list
 drop_down_remove_all(GTK_DROP_DOWN(axopt));
 hide_all_cmd_ctls();

 cmd = (int)(gtk_drop_down_get_selected(GTK_DROP_DOWN(comcmd)));

 switch(cmd){
    case MOVEBY_DISTANCE:
    case GOTO_XYZ:
        snprintf(msgtxt,sizeof(msgtxt), "%.9g", Mv_dist_x); gtk_editable_set_text(GTK_EDITABLE(entry_xcoord), msgtxt);
        snprintf(msgtxt,sizeof(msgtxt), "%.9g", Mv_dist_y); gtk_editable_set_text(GTK_EDITABLE(entry_ycoord), msgtxt);
        snprintf(msgtxt,sizeof(msgtxt), "%.9g", Mv_dist_z); gtk_editable_set_text(GTK_EDITABLE(entry_zcoord), msgtxt);
        gtk_label_set_text(GTK_LABEL(lab_xedit), "X-Axis");
        gtk_label_set_text(GTK_LABEL(lab_yedit), "Y-Axis");
        gtk_label_set_text(GTK_LABEL(lab_zedit), "Z-Axis");
        break;
    case SET_DIRECTIONS:
        snprintf(msgtxt,sizeof(msgtxt), "%"PRId32, Mv_dir_left); gtk_editable_set_text(GTK_EDITABLE(entry_xcoord), msgtxt);
        snprintf(msgtxt,sizeof(msgtxt), "%"PRId32, Mv_dir_back); gtk_editable_set_text(GTK_EDITABLE(entry_ycoord), msgtxt);
        snprintf(msgtxt,sizeof(msgtxt), "%"PRId32, Mv_dir_down); gtk_editable_set_text(GTK_EDITABLE(entry_zcoord), msgtxt);
        gtk_label_set_text(GTK_LABEL(lab_xedit), "X-Axis");
        gtk_label_set_text(GTK_LABEL(lab_yedit), "Y-Axis");
        gtk_label_set_text(GTK_LABEL(lab_zedit), "Z-Axis");
        break;
    case ACT_ACCEL:
        // if LK_acc_isd[0] == 0 then all 3 values will be unset:
        if (LK_acc_isd[0] == 0) { 
            // Display the literal text token string as requested
            gtk_editable_set_text(GTK_EDITABLE(entry_xcoord), "[UNSET]");
            gtk_editable_set_text(GTK_EDITABLE(entry_ycoord), "[UNSET]");
            gtk_editable_set_text(GTK_EDITABLE(entry_zcoord), "[UNSET]");
        } else {
          // Otherwise, format and render the acceleration profile values
          snprintf(msgtxt,sizeof(msgtxt),"%.9g",LK_acc_acp);
          gtk_editable_set_text(GTK_EDITABLE(entry_xcoord), msgtxt);
          snprintf(msgtxt,sizeof(msgtxt),"%"PRId32,LK_acc_isd[0]);
          gtk_editable_set_text(GTK_EDITABLE(entry_ycoord), msgtxt);
          snprintf(msgtxt,sizeof(msgtxt),"%"PRId32,LK_acc_isd[1]);
          gtk_editable_set_text(GTK_EDITABLE(entry_zcoord), msgtxt);
        }
        gtk_label_set_text(GTK_LABEL(lab_xedit), "Prop. Acc.");
        gtk_label_set_text(GTK_LABEL(lab_yedit), "ISD min");
        gtk_label_set_text(GTK_LABEL(lab_zedit), "ISD max min");
        break;
    case MS_DENOM:
        // 1. Re-populate the dropdown model dynamically with system axis strings
        new_model = gtk_string_list_new(Axis_options);
        gtk_drop_down_set_model(GTK_DROP_DOWN(axopt), G_LIST_MODEL(new_model));
        
        // 2. Query the active axis index currently highlighted in the GUI
        // This ensures the text field maps perfectly even if the legacy tracker
        // isn't primed yet.
        gint active_axis = 
                    (gint)gtk_drop_down_get_selected(GTK_DROP_DOWN(Combo_axis));
        
        // Safety guard: Limit bounds between valid physical motor array slots
        if (active_axis >= 0 && active_axis < 3) {
            // 3. Evaluate your array initialization rule: 
            if (LK_msdenom[active_axis] == 0) { // 0 means unconfigured/unset
                // Display the literal text token string as requested
                gtk_editable_set_text(GTK_EDITABLE(entry_xcoord), "[UNSET]");
            } else {
              // Otherwise, format and render the microstep denominator
              snprintf(msgtxt,sizeof(msgtxt),"%"PRId32,LK_msdenom[active_axis]);
              gtk_editable_set_text(GTK_EDITABLE(entry_xcoord), msgtxt);
            }
        } else {
            // Fallback protection against out of axis bounds widget positions
            gtk_editable_set_text(GTK_EDITABLE(entry_xcoord), "[UNSET]");
        }

        // Update the descriptive frontend text labels layout safely
        gtk_label_set_text(GTK_LABEL(lab_axis), "Axis");
        gtk_label_set_text(GTK_LABEL(lab_xedit), "Microstep Denominator");
        break;
    case FF_CORRECTION:
        new_model = gtk_string_list_new(Offonfile_options);
        gtk_drop_down_set_model(GTK_DROP_DOWN(axopt), G_LIST_MODEL(new_model));
        gtk_drop_down_set_selected(GTK_DROP_DOWN(Combo_axis), ffcorr_status);
        gtk_label_set_text(GTK_LABEL(lab_axis), "Option");
        gtk_label_set_text(GTK_LABEL(lab_xedit), "Flat Field Image File");
        break;
    case DF_CORRECTION:
        new_model = gtk_string_list_new(Offonfile_options);
        gtk_drop_down_set_model(GTK_DROP_DOWN(axopt), G_LIST_MODEL(new_model));
        gtk_drop_down_set_selected(GTK_DROP_DOWN(Combo_axis), dfcorr_status);
        gtk_label_set_text(GTK_LABEL(lab_axis), "Option");
        gtk_label_set_text(GTK_LABEL(lab_xedit), "Dark Field Image File");
        break;
    case CORRECTIONS_MASK:
        new_model = gtk_string_list_new(Offonfile_options);
        gtk_drop_down_set_model(GTK_DROP_DOWN(axopt), G_LIST_MODEL(new_model));
        gtk_drop_down_set_selected(GTK_DROP_DOWN(Combo_axis), mask_status);
        gtk_label_set_text(GTK_LABEL(lab_axis), "Option");
        gtk_label_set_text(GTK_LABEL(lab_xedit), "Corrections Mask Image File");
        break;
    case TC_THRESHOLD:
        snprintf(msgtxt,sizeof(msgtxt), "%.9g", LK_tctlow);
        gtk_editable_set_text(GTK_EDITABLE(entry_xcoord), msgtxt);
        snprintf(msgtxt,sizeof(msgtxt), "%.9g", LK_tctupp);
        gtk_editable_set_text(GTK_EDITABLE(entry_ycoord), msgtxt);
        gtk_label_set_text(GTK_LABEL(lab_xedit), "Lower");
        gtk_label_set_text(GTK_LABEL(lab_yedit), "Upper");
        break;
    case SAVE_FORMAT:
        gtk_label_set_text(GTK_LABEL(lab_axis), "Format");
        new_model = gtk_string_list_new(Fmt_options);
        gtk_drop_down_set_model(GTK_DROP_DOWN(axopt), G_LIST_MODEL(new_model));
        if(NCPs){
          if(CPlist[CamIdx].Saveas_Fmt>=0)
                           gtk_drop_down_set_selected(GTK_DROP_DOWN(Combo_axis),
                                                     CPlist[CamIdx].Saveas_Fmt);
          else gtk_drop_down_set_selected(GTK_DROP_DOWN(Combo_axis),SAF_UNSET);
         }
        break;
    case SAVE_DOUBLES:
        new_model = gtk_string_list_new(Offonfits_options);
        gtk_drop_down_set_model(GTK_DROP_DOWN(axopt), G_LIST_MODEL(new_model));
        gtk_drop_down_set_selected(GTK_DROP_DOWN(Combo_axis),
                                                     CPlist[CamIdx].Saveas_Dou);
        break;
    case FRAME_NUMBER:
        gtk_label_set_text(GTK_LABEL(lab_xedit), "Frame Number");
        snprintf(msgtxt,sizeof(msgtxt),"%d",NCPs?CPlist[CamIdx].Frame_Number:0);
        gtk_editable_set_text(GTK_EDITABLE(entry_xcoord), msgtxt);
        break;
    case SELECT_CAMERA:
        gtk_label_set_text(GTK_LABEL(lab_xedit), "Camera Number");
        snprintf(msgtxt,sizeof(msgtxt), "%"PRIu32, CurrPS);
        gtk_editable_set_text(GTK_EDITABLE(entry_xcoord), msgtxt);
        break;
    case SKIP_FRAMES:
        gtk_label_set_text(GTK_LABEL(lab_xedit), "No. frames to skip");
        snprintf(msgtxt,sizeof(msgtxt), "%d",LK_skip_frames); 
        gtk_editable_set_text(GTK_EDITABLE(entry_xcoord), msgtxt);
        break;
    case FRAMES_TO_SKIP:
        gtk_label_set_text(GTK_LABEL(lab_xedit), "No. frames to skip");
        snprintf(msgtxt,sizeof(msgtxt), "%d", 
                                          NCPs?CPlist[CamIdx].Frames_to_skip:0); 
        gtk_editable_set_text(GTK_EDITABLE(entry_xcoord), msgtxt);
        break;
    case FRAMES_TO_AVG:
        gtk_label_set_text(GTK_LABEL(lab_xedit), "No. frames to Average");
        snprintf(msgtxt,sizeof(msgtxt), "%d", NCPs?CPlist[CamIdx].Av_denom:1);
        gtk_editable_set_text(GTK_EDITABLE(entry_xcoord), msgtxt);
        break;
    case CAMERA_SET:
        gtk_label_set_text(GTK_LABEL(lab_xedit), "Value");
        gtk_label_set_text(GTK_LABEL(lab_axis), "Camera Setting");
        if(NCPs==0){
           append_item_to_dropdown(GTK_DROP_DOWN(axopt),"None Available");
           break;
         }
        if(CPlist[CamIdx].NCSs == 0){
           append_item_to_dropdown(GTK_DROP_DOWN(axopt),"None Available");
           break;
         }
        for(idx = 0; idx < (int)CPlist[CamIdx].NCSs; idx++){
           snprintf(msgtxt,sizeof(msgtxt), "%s", CPlist[CamIdx].CSlist[idx].name);
           append_item_to_dropdown(GTK_DROP_DOWN(Combo_axis),(const char *)msgtxt);
        }
        gtk_drop_down_set_selected(GTK_DROP_DOWN(Combo_axis),
                                                    CPlist[CamIdx].Curr_cs_idx);
        if(CPlist[CamIdx].NCSs){
          snprintf(msgtxt,sizeof(msgtxt), "%d",
           CPlist[CamIdx].CSlist[(int)(gtk_drop_down_get_selected(GTK_DROP_DOWN(Combo_axis)))].currval);
          gtk_editable_set_text(GTK_EDITABLE(entry_xcoord), msgtxt);
        }
        break;
    case SAVE_RESOLUTION:
        gtk_label_set_text(GTK_LABEL(lab_axis), "W x H");
        if(NCPs==0){
           append_item_to_dropdown(GTK_DROP_DOWN(axopt),"None Available");
           break;
         }
        if(CPlist[CamIdx].res_sz == 0){
           append_item_to_dropdown(GTK_DROP_DOWN(axopt),"None Available");
           break;
         }
        for(idx = 0; idx < CPlist[CamIdx].res_sz; idx++){
          snprintf(msgtxt,sizeof(msgtxt), "%d x %d", CPlist[CamIdx].res_x[idx], CPlist[CamIdx].res_y[idx]);
          append_item_to_dropdown(GTK_DROP_DOWN(axopt), (const char *)msgtxt);
         }
        gtk_drop_down_set_selected(GTK_DROP_DOWN(Combo_axis), CPlist[CamIdx].Curr_res_idx);
        break;
    case GRAB_IMAGE:
    case AUTOFOCUS:       // No options - leave as is
    case GET_AXES:        // No options - leave as is
    case FREE_FORM:// No options - leave as is
        break;
    case SAVE_COORDS:
        gtk_label_set_text(GTK_LABEL(lab_axis), "Mode");
        new_model = gtk_string_list_new(Offon_options);
        gtk_drop_down_set_model(GTK_DROP_DOWN(axopt), G_LIST_MODEL(new_model));
        gtk_drop_down_set_selected(GTK_DROP_DOWN(Combo_axis), write_coords_file);
        break;
    case GET_TC_VALUE:
        gtk_label_set_text(GTK_LABEL(lab_axis), "Mode"); // For the ON/OFF combo
        new_model = gtk_string_list_new(Offon_options); // Fill it with ON, OFF
        gtk_drop_down_set_model(GTK_DROP_DOWN(axopt), G_LIST_MODEL(new_model));
        // Select ON as default
        gtk_drop_down_set_selected(GTK_DROP_DOWN(Combo_axis), 0);
        break;
        gtk_label_set_text(GTK_LABEL(lab_xedit), "CurrTC = ");
        // Print the current tissue content value
        snprintf(msgtxt,sizeof(msgtxt), "%.9g", CurrTC);
        gtk_label_set_text(GTK_LABEL(lab_yedit), msgtxt);
        break;
    case GET_PREVIEW:
        gtk_label_set_text(GTK_LABEL(lab_axis), "Zoom");
        new_model = gtk_string_list_new(Offon_options);
        gtk_drop_down_set_model(GTK_DROP_DOWN(axopt), G_LIST_MODEL(new_model));
        gtk_drop_down_set_selected(GTK_DROP_DOWN(Combo_axis), LK_pzoom);
        snprintf(msgtxt,sizeof(msgtxt),"%"PRId32, LK_pcentx);
        gtk_editable_set_text(GTK_EDITABLE(entry_xcoord), msgtxt);
        snprintf(msgtxt,sizeof(msgtxt),"%"PRId32, LK_pcenty);
        gtk_editable_set_text(GTK_EDITABLE(entry_ycoord), msgtxt);
        gtk_label_set_text(GTK_LABEL(lab_xedit), "Centre X");
        gtk_label_set_text(GTK_LABEL(lab_yedit), "Centre Y");
        break;
    case SAVE_ROOT:
        gtk_label_set_text(GTK_LABEL(lab_xedit), "File name root");
        if(NCPs==0) break;
        if(CPlist[CamIdx].Imroot_set) gtk_editable_set_text(GTK_EDITABLE(entry_xcoord), CPlist[CamIdx].ImRoot);
        break;
    case YUYV_GAIN:
        gtk_label_set_text(GTK_LABEL(lab_xedit), "YUYV Gain");
        snprintf(msgtxt,sizeof(msgtxt), "%.9g", LK_gn); gtk_editable_set_text(GTK_EDITABLE(entry_xcoord), msgtxt);
        break;
    case YUYV_BIAS:
        gtk_label_set_text(GTK_LABEL(lab_xedit), "YUYV Bias");
        snprintf(msgtxt,sizeof(msgtxt), "%.9g", LK_bs); gtk_editable_set_text(GTK_EDITABLE(entry_xcoord), msgtxt);
        break;
    default: // This should not happen unless someone modifies this source code wrongly
        show_message("Unknown command option.", "Program Error: ", MT_ERR, 1);
        break;
  }
 show_cmd_ctls(cmd);

 return;
}

static void combo_axis_changed(GtkDropDown* comaxi, GParamSpec *pspec, gpointer comcmd)
// If a command in the command list uses the axis combo and also uses any edit
// boxes or labels in addition to the axis combo then it must have an entry in
// this function to set those additional controls according to the currently
// selected active selection of the axis combo. Other commands just appear in
// the switch statement and break immediately to prevent an 'unknown command'
// error.
{
 gint adx, cmd;
 char msgtxt[32];

 // Modify GUI to match the requested command type

 adx = (int)(gtk_drop_down_get_selected(GTK_DROP_DOWN(comaxi)));
 cmd = (int)(gtk_drop_down_get_selected(GTK_DROP_DOWN(comcmd)));

 switch(cmd){
    // The entries in this part of the list do nothing - just break.
    case MOVEBY_DISTANCE:
    case GOTO_XYZ:
    case SET_DIRECTIONS:
    case ACT_ACCEL:
    case MS_DENOM:
    case TC_THRESHOLD:
    case SAVE_FORMAT:
    case SAVE_DOUBLES:
    case FRAME_NUMBER:
    case SELECT_CAMERA:
    case SKIP_FRAMES:
    case FRAMES_TO_SKIP:
    case FRAMES_TO_AVG:
    case SAVE_RESOLUTION:
    case GRAB_IMAGE: 
    case AUTOFOCUS: 
    case GET_PREVIEW:
    case GET_AXES:
    case SAVE_ROOT:
    case SAVE_COORDS:
    case YUYV_GAIN:
    case YUYV_BIAS:    
    case FREE_FORM:    
    break;
    // The entries in this part all need to set appropriate controls.
    case GET_TC_VALUE:
        gtk_label_set_text(GTK_LABEL(lab_xedit), "CurrTC = ");
        // Print the current tissue content value
        snprintf(msgtxt,sizeof(msgtxt), "%.9g", CurrTC);
        gtk_label_set_text(GTK_LABEL(lab_yedit), msgtxt);
    break;
    case CAMERA_SET:
        if(NCPs==0){
           snprintf(msgtxt,sizeof(msgtxt), "0");
           gtk_editable_set_text(GTK_EDITABLE(entry_xcoord), msgtxt);
           break;
         }
        if(CPlist[CamIdx].NCSs){
            snprintf(msgtxt,sizeof(msgtxt), "%d", CPlist[CamIdx].CSlist[adx].currval);
            gtk_editable_set_text(GTK_EDITABLE(entry_xcoord), msgtxt);
        }
    break;
    case FF_CORRECTION:
        if(adx < 2){
            gtk_widget_set_visible(btn_corrimg_file,FALSE);
            gtk_widget_set_visible(entry_xcoord,FALSE);
            gtk_widget_set_visible(lab_xedit,FALSE);
            break;
        }
        gtk_widget_set_visible(btn_corrimg_file,TRUE);
        if(fffile_set && NCPs) gtk_editable_set_text(GTK_EDITABLE(entry_xcoord),
                                           CPlist[CamIdx].Selected_FF_filename);
        else gtk_editable_set_text(GTK_EDITABLE(entry_xcoord), "[None]");
        gtk_widget_set_visible(entry_xcoord,TRUE); gtk_widget_set_visible(lab_xedit,TRUE);
        FileChooser_type = cmd;
    break;
    case DF_CORRECTION:
        if(adx < 2){
            gtk_widget_set_visible(btn_corrimg_file,FALSE);
            gtk_widget_set_visible(entry_xcoord,FALSE);
            gtk_widget_set_visible(lab_xedit,FALSE);
            break;
        }
        gtk_widget_set_visible(btn_corrimg_file,TRUE);
        if(dffile_set && NCPs) gtk_editable_set_text(GTK_EDITABLE(entry_xcoord),
                                           CPlist[CamIdx].Selected_DF_filename);
        else gtk_editable_set_text(GTK_EDITABLE(entry_xcoord), "[None]");
        gtk_widget_set_visible(entry_xcoord,TRUE); gtk_widget_set_visible(lab_xedit,TRUE);
        FileChooser_type = cmd;
    break;
    case CORRECTIONS_MASK:
        if(adx < 2){
            gtk_widget_set_visible(btn_corrimg_file,FALSE);
            gtk_widget_set_visible(entry_xcoord,FALSE);
            gtk_widget_set_visible(lab_xedit,FALSE);
            break;
        }
        gtk_widget_set_visible(btn_corrimg_file,TRUE);
        if(cmfile_set && NCPs) gtk_editable_set_text(GTK_EDITABLE(entry_xcoord),
                                           CPlist[CamIdx].Selected_CM_filename);
        else gtk_editable_set_text(GTK_EDITABLE(entry_xcoord), "[None]");
        gtk_widget_set_visible(entry_xcoord,TRUE); gtk_widget_set_visible(lab_xedit,TRUE);
        FileChooser_type = cmd;
    break;
    default: // This should not happen unless there's a bug
        show_message("Unknown command option.", "Program Error: ", MT_ERR, 1);
    break;
 }

 return;
}
/////// ... end of 'modify GUI to match the requested command type'

