static void add_grid(GtkGrid **grd, GtkWidget **ctn)
// Create a new grid (or other containter) using the supplied parameters
 {
    *grd = GTK_GRID(gtk_grid_new());  
    gtk_grid_set_row_spacing(GTK_GRID(*grd), 2);
    gtk_grid_set_column_spacing(GTK_GRID(*grd), 2);

    if (GTK_IS_WINDOW(*ctn)) {
        gtk_window_set_child(GTK_WINDOW(*ctn), GTK_WIDGET(*grd));
    } else if (GTK_IS_FRAME(*ctn)) {
        gtk_frame_set_child(GTK_FRAME(*ctn), GTK_WIDGET(*grd));
    } else {
        // This covers Boxes, ScrolledWindows, etc.
        // In GTK4, most single-child containers use set_child
        g_object_set(*ctn, "child", GTK_WIDGET(*grd), NULL);
    }
}

void load_box_highlight_css(void)
// This loads the box outline colours used to highlight the manual direction
// button group when they are active.
{
 GtkCssProvider *provider;
 GdkDisplay *display;

 // Create a new CSS provider object
 provider = gtk_css_provider_new();
 
 // Get the default display
 display = gdk_display_get_default();
 
 // Add the provider to the default display so the CSS applies to all windows
 gtk_style_context_add_provider_for_display(display, GTK_STYLE_PROVIDER(provider), GTK_STYLE_PROVIDER_PRIORITY_APPLICATION);
 
 // Load the CSS data from a string literal
 gtk_css_provider_load_from_string(provider,
     ".axis-frame { border: 2px solid #ccc; padding: 5px; margin: 5px; }"
     ".axis-frame.active-indicator { border: 2px solid green; }"
     ".axis-frame.diverted-indicator { border: 2px solid red; }");
 
 // Decrease the reference count of the provider, as the display now holds a reference
 g_object_unref(provider);
}

