     // Use the native header bar style of the OS. Only do this for macOS
     // because on Windows and Linux it forces the GNOME-style header to be
     // used so it kind of has the opposite effect.
#ifdef __APPLE__
     GtkWidget *header_bar_viewer;
     header_bar_viewer = gtk_header_bar_new ();
     gtk_header_bar_set_use_native_controls (GTK_HEADER_BAR (header_bar_viewer), TRUE);
     gtk_window_set_titlebar (GTK_WINDOW (Win_viewer), header_bar_viewer);
#endif // __APPLE__

     // This signal is emitted when the user tries to close the window.
     g_signal_connect (Win_viewer, "close-request", G_CALLBACK (on_viewer_close_request), NULL);
