     // --- Set the border/margins on the grid ---
     gtk_widget_set_margin_start(GTK_WIDGET(grid_viewer), 5);
     gtk_widget_set_margin_end(GTK_WIDGET(grid_viewer), 5);
     gtk_widget_set_margin_top(GTK_WIDGET(grid_viewer), 5);
