     gtk_grid_set_row_spacing(GTK_GRID(grid_viewer), 2);
     gtk_grid_set_column_spacing(GTK_GRID(grid_viewer), 5);

     // Attaches Img_viewer at column 0, row 0, spanning 1 column wide and 1 row high.
