     g_signal_connect(Btn_login, "clicked", G_CALLBACK(btn_login_click), Btn_login);
     add_button(&Btn_logout, "Log Out", GTK_ALIGN_START);
     g_signal_connect(Btn_logout, "clicked", G_CALLBACK(Btn_logout_click), Btn_logout);
     add_button(&btn_change_pwd, "Change Password", GTK_ALIGN_START);
     g_signal_connect(btn_change_pwd, "clicked", G_CALLBACK(btn_change_pwd_click), btn_change_pwd);

     // Contruct entry boxes

     // Entry box for the server IP address

     // 1. Extract the string pointer from GLib's application metadata
     const char *cli_ip = (const char *)g_object_get_data(G_OBJECT(app),
                                                             "cli_ipv4_string");
     // 2. Set up a single local buffer for the destination
     //    (max domain length is 253)
     char ip_text[256] = "127.0.0.1"; 
     
     if(cli_ip != NULL && strlen(cli_ip) > 0){
         
        // Set up hints to tell the OS what network formats we are interested in
        struct addrinfo hints;
        struct addrinfo *result = NULL;
        
        memset(&hints, 0, sizeof(hints));
        hints.ai_family = AF_UNSPEC;    // Accept IPv4 (AF_INET) or 6 (AF_INET6)
        hints.ai_socktype = SOCK_STREAM;// TCP protocol matching ZeroMQ
        hints.ai_flags = AI_ADDRCONFIG; // Only return addresses the client
                                        // machine can actually route to
    
        // 3. Perform the check. This handles IPv4 octets, IPv6, and Domains.
        // We pass NULL for the port since we only care about verifying the host
        // string here.
        int s = getaddrinfo(cli_ip, NULL, &hints, &result);
    
        if (s == 0) {
            // SUCCESS: The OS confirmed this is a valid IP or a resolvable
            // domain name.
            snprintf(ip_text, sizeof(ip_text), "%s", cli_ip);
            freeaddrinfo(result); // Free the memory alloced by getaddrinfo
        } else {
            // FAIL: The input string was garbage or an unresolvable domain
            show_message("Invalid server address or domain name."
                         " Defaulting to 127.0.0.1.",
                         "Address Format Error", MT_INFO, 0);
        }
     }
     
     // 4. Pass the address string into a single GTK entry box routine
     // Purpose is FREE_FORM to allow alphabetic domain name characters
     add_entrybox(&entry_server_address, &ebuff_server_address,
                     GTK_INPUT_PURPOSE_FREE_FORM, ip_text, "myserver.com", 28);
    


     // Entry box for port

     // 1. Extract the string pointer from GLib's application object metadata
     const char *cli_port = (const char *)g_object_get_data(G_OBJECT(app),
                                                             "cli_port_string");
     
     // 2. Set up a local character array to hold the final displayed string
     char initial_port_text[16];
    
     // 3. Fallback to default, or validate the user-supplied string argument
     if(cli_port != NULL){

       // Validate that the string contains ONLY numbers
       int is_numeric = 1;
       for(int i = 0; cli_port[i] != '\0'; i++){
           if(!isdigit((unsigned char)cli_port[i])){
               is_numeric = 0;
               break;
           }
       }
      
       if(!is_numeric){
         show_message("Invalid characters detected. Defaulting to 5555.",
                                         "Supplied <port> value: ", MT_INFO, 0);
         goto default_port;
       }

       int parsed_port = atoi(cli_port);
       
       if(parsed_port < 1024 || parsed_port > 65535) {
         // Safe bounds check faile: Revert to default
         show_message("Invalid range detected (not within 1024 - 65535)."
                  " Defaulting to 5555.","Supplied <port> value: ", MT_INFO, 0);
         goto default_port;
       } else {
         snprintf(initial_port_text,sizeof(initial_port_text),"%d",parsed_port);
       }
     } else {
         // No (or invalid) command line <port> argument provided: Load default
         default_port:
         strncpy(initial_port_text, "5555", sizeof(initial_port_text));
     }
 
     // 4. Pass the dynamically constructed string variable into port entry box
     add_entrybox(&entry_port, &ebuff_port, GTK_INPUT_PURPOSE_NUMBER,
                                            initial_port_text, "[Port No.]", 5);
     fix_entrybox_width_chars(entry_port,5);

     // Entry box for server's public key
     add_entrybox(&entry_key, &ebuff_key, GTK_INPUT_PURPOSE_PASSWORD, "", "Public key", 12);
     gtk_widget_set_name(entry_key, "Key");
     fix_entrybox_width_chars(entry_key,12);
    
     // Entry box for user name
     const char *cli_usr = (const char *)g_object_get_data(G_OBJECT(app),
                                                             "cli_user_string");
     if (cli_usr == NULL) cli_usr = "";

     add_entrybox(&entry_usr, &ebuff_usr, GTK_INPUT_PURPOSE_FREE_FORM,
                                                     cli_usr, "User name", 28);

     // Entry box for password
     add_entrybox(&Entry_pwd, &ebuff_pwd, GTK_INPUT_PURPOSE_PASSWORD, "", "Password", 26);
     gtk_widget_set_name(Entry_pwd, "Password");

     // Entry box for client ID
     add_entrybox(&entry_cid, &ebuff_cid, GTK_INPUT_PURPOSE_FREE_FORM, "", "[To be assigned]", 28);
     // Entry box for server name
     // 1. Extract the string pointer from GLib's application object metadata
     const char *cli_name = (const char *)g_object_get_data(G_OBJECT(app),
                                                             "cli_name_string");
     // 2. Fallback to default if NULL
     if (cli_name == NULL) cli_name = "Pardus1";

     add_entrybox(&entry_srv, &ebuff_srv, GTK_INPUT_PURPOSE_FREE_FORM,
                                                             cli_name, "", 4);
     gtk_widget_set_name(entry_srv, "Server");

    // Make a horizontal separator line (server id vs the rest)
    GtkWidget *separator = gtk_separator_new(GTK_ORIENTATION_HORIZONTAL);
    gtk_widget_set_hexpand(separator, TRUE);
    gtk_widget_set_halign(separator, GTK_ALIGN_FILL);
    gtk_widget_set_margin_top(separator, 10);    // 10 pixels of space ABOVE the line
    gtk_widget_set_margin_bottom(separator, 10); // 10 pixels of space BELOW the line
   

     // Entry box for message index
     add_entrybox(&entry_mdx, &ebuff_mdx, GTK_INPUT_PURPOSE_NUMBER,"0","0", 12);
     fix_entrybox_width_chars(entry_mdx,12);


     // Callback for when user hits return in the password box:
     g_signal_connect(Entry_pwd, "activate", G_CALLBACK(on_entry_pwd_activate), NULL);

     // Construct check boxes
     chk_passwd_show = gtk_check_button_new_with_label("Show password");
     gtk_check_button_set_active(GTK_CHECK_BUTTON(chk_passwd_show), FALSE);
     g_signal_connect(GTK_CHECK_BUTTON(chk_passwd_show), "toggled", G_CALLBACK(chk_passwd_show_toggle), Entry_pwd);

     // Construct labels
     lab_mdx = gtk_label_new("Message index");
