int non_gui_init(void)
// Initialise things that are not used in the GUI processes.
// Return 0 on success
// Return 1 on failure (a terminal event)
{
 uint8_t ui8;

 // Inititalise log file name
 sprintf(LogFilename, "Log_PARDcli.txt");

 // The default 'last image saved'  file name
 sprintf(ImgFilename, "NoTissue");

 // The currently selected XYZ-Scan tile
 CurrSelectedTile.hasselection=0;
 CurrSelectedTile.memfail=0;
 CurrSelectedTile.origtile = calloc(2, sizeof(unsigned char));
 if(CurrSelectedTile.origtile == NULL){
     show_message("Could not allocate RAM for the currently selected XY-scan tile.", "Error: ", MT_ERR, 0);
     return 1;
 }
// Re-establish my default colours because GTK4 will have set them to default:
    st_col.red =   255.0/255.0;
    st_col.green = 128.0/255.0;
    st_col.blue =   0.0/255.0;
    st_col.alpha =   1.0;
 // Now set the current tile to those colours
 CurrSelectedTile.rd=(unsigned char)(st_col.red*255.0);
 CurrSelectedTile.gn=(unsigned char)(st_col.green*255.0);
 CurrSelectedTile.bl=(unsigned char)(st_col.blue*255.0);

 // Allocate memory for server triad and the argument pointer - this is just an initial allocation
 // because I always free(triad); before doing a new allocation.
 triad = calloc(2, sizeof(char));
 if(triad == NULL){
     show_message("Could not allocate RAM for the server triad.", "Error: ", MT_ERR, 0);
     return 1;
 }
 triadarg = calloc(2, sizeof(char));
 if(triadarg == NULL){
     show_message("Could not allocate RAM for the server triad argument pointer.", "Error: ", MT_ERR, 0);
     return 1;
 }

 // Allocate memory for Blob - this is just an initial allocation
 // because I always free(Blob); before doing a new allocation.
 Blobsize = 4;
 Blob = calloc(Blobsize, sizeof(unsigned char));
 if(Blob == NULL){
     show_message("Could not allocate RAM for the Blob.", "Error: ", MT_ERR, 0);
     return 1;
 }

 // Allocate memory for XYS_Blob - this is just an initial allocation
 // because I always free(XYS_Blob); before doing a new allocation.
 XYS_Blobsize = 4;
 XYS_Blob = calloc(XYS_Blobsize, sizeof(unsigned char));
 if(XYS_Blob == NULL){
     show_message("Could not allocate RAM for the XYS_Blob.", "Error: ",
                                                                    MT_ERR, 0);
     return 1;
 }

 // Initialise the first two XY scan render struct.
 // Here the index will be SC_CURR because this is the first time we call the
 // function since the program began.
 if(xyzs_new() != XYE_SUCCESS){
      show_message("Could not get RAM for XYZ Scan current render struct",
                                                          "Error: ", MT_ERR, 0);
      return 1;
     }
 // Here the index will be SC_LIVE because this is the second time.
 if(xyzs_new() != XYE_SUCCESS){
      show_message("Could not get RAM for XYZ Scan live render struct",
                                                          "Error: ", MT_ERR, 0);
      return 1;
     }
 // Now divest XYSlist[SC_CURR] of its native memory blocks:
 free(XYSlist[SC_CURR].ImRoot);
 XYSlist[SC_CURR].ImRoot=NULL;


 // Initialise the XYZ-Scan tile image space
 xyzs_tile = calloc(2, sizeof(unsigned char));
 if(xyzs_tile == NULL){
     show_message("Could not allocate RAM for the XY-scan tile.", "Error: ", MT_ERR, 0);
     return 1;
 }

 // Initialise the available camera resolutions lists
 res_x = NULL;
 res_y = NULL;
 res_sz = 0;

 // We start off without a flat field or dark field file
 do_ff_correction=DOFC_NO;
 do_df_correction=DOFC_NO;

 // Initialise GUI motion parameters
 Mv_dist_x = 10.0;
 Mv_dist_y = 10.0; 
 Mv_dist_z = 10.0;
 Mv_dir_left = 0;
 Mv_dir_back = 0; 
 Mv_dir_down = 0;
 LK_dir_x = -1; // Negative means unset
 LK_dir_y = -1; // Negative means unset
 LK_dir_z = -1; // Negative means unset

 GUI_StageUnitType = -1; // Undefined.
 sprintf(GUI_unitname,"Unknown"); 
 Manual_movement_active = 0;
 Stage_is_motion_ready = 0; // Can't use GUI motion buttons unless an XYZ stage
                            // exists and is mature to move.

 LK_msdenom[0]=LK_msdenom[1]=LK_msdenom[2]=0;
 LK_maxmsdenom[0]=LK_maxmsdenom[1]=LK_maxmsdenom[2]=0;

 LK_acc_isd[0]=LK_acc_isd[1]=0;
 LK_acc_acp = 0.0;

 // Initialise the Fourier subsystem
 ft_init();

 // Initialise tissue content values:
 image_has_tissue = 0;
 CurrTC = -1.0;

 // Set null user name
 sprintf(username, "Caller");
 
 // Some default global values
 Writeas_Fmt = SAF_BMP;

 // Initialise Actuator list IDs and pointers
 for(ui8=0;ui8<STEPPERSMAX;ui8++){
   StepperID[ui8]=STEPPER_ID_FREE;
   Stepperlist[ui8]=NULL;
  }
 StageStatus=0;
 for(ui8=0;ui8<BINARIESMAX;ui8++){
   BinaryID[ui8]=BINARY_ID_FREE;
   Binarylist[ui8]=NULL;
  }
 for(ui8=0;ui8<MLEVELSMAX;ui8++){
   MlevelID[ui8]=MLEVEL_ID_FREE;
   Mlevellist[ui8]=NULL;
  }
 for(ui8=0;ui8<SERVOSMAX;ui8++){
   ServoID[ui8]=SERVO_ID_FREE;
   Servolist[ui8]=NULL;
  }
 for(ui8=0;ui8<SENSORSMAX;ui8++){
   SensorID[ui8]=SENSOR_ID_FREE;
   Sensorlist[ui8]=NULL;
  }

return 0;
}

////////////////////////////////////////////////////////////////////////
//                                                                    //
//      MAIN                                                          //
//                                                                    //
////////////////////////////////////////////////////////////////////////


int main(int argc, char *argv[])
{
 // INSTALL LOG FILTER FIRST
 // This ensures warnings during setup are also caught.
 install_log_suppression();

 GtkApplication *app;
 int status;

 #if IS_WINDOWS_NATIVE || defined(_WIN32)
 WSADATA wsaData;
 if(WSAStartup(MAKEWORD(2, 2), &wsaData) != 0){
   // If the OS network stack fails, fallback before GTK allocates resources
   fprintf(stderr, "CRITICAL ERROR: Windows Network Subsystem failed to start.\n");
   return -1;
  }
 #endif

 // For cross-plaform compiles, tells GTK to prefer the native OS styles for
 // window decoration. 
 g_setenv("GTK_CSD", "0", TRUE);
 
#if defined(_WIN32) || IS_WINDOWS_NATIVE
 // Choose the renderer you prefer:
 // Cairo is a software (slower) renderer but usually works on any system
 // g_setenv("GSK_RENDERER", "cairo", TRUE);

 // Set the high-performance hardware backend
  g_setenv("GSK_RENDERER", "opengl", TRUE);
 // g_setenv("GSK_RENDERER", "ngl", TRUE);
 // g_setenv("GSK_RENDERER", "vulkan", TRUE);
#endif


 // Generate the program's icon
 create_icon();

 // 1. Create a new GtkApplication instance
 // The unique ID is important for single-instance behavior and desktop
 // integration. Don't need to dynamically allocate a process-specific ID for
 // this program because, unlike PARDcap, only one instance would normally be
 // used at a time.
 // 1. Create a new GtkApplication instance
 app = gtk_application_new("com.TadPath.PardClient", G_APPLICATION_HANDLES_COMMAND_LINE);

 // 2. Connect the "command-line" signal to override file-parsing loops
 g_signal_connect(app, "command-line", G_CALLBACK(main_gui_command_line), NULL);

 // AUDIT FIX 40: put the decimal point back after GTK's setlocale(LC_ALL, "").
 // g_signal_connect_after runs this once GtkApplication's own "startup"
 // handler (which initialises GTK) has finished.
 g_signal_connect_after(app, "startup", G_CALLBACK(pcs_numeric_locale_C), NULL);
 
  // Load the graphics font
#if !(defined(_WIN32) || IS_WINDOWS_NATIVE)
  // 🐧 Linux loads early at boot with no arguments needed
  load_embedded_graphics_font();
#endif
 
 // Re-register the activate signal wrapper! This bridges your 
 // g_application_activate() launch call straight to your main_gui_activate function!
 g_signal_connect(app, "activate", G_CALLBACK(main_gui_activate), NULL);

 // Do some initialisations
 if(non_gui_init()) exit(1);

 // Start the GUI main loop - no code beyond this point will be executed
 // until the main window is closed.
 gui_up = 1;    // Let all functions know the GUI is up

 // 3. Run the application event loop
 // This replaces the old gtk_init() and gtk_main() calls
 status = g_application_run(G_APPLICATION(app), argc, argv);

 if(status != 2 && status){
   fprintf(stderr,"\nPardClient quit with a non-zero status = %d\n",status);
  } 

 if(status == 2) Verbosity = 0;

 // The main GUI has been quit.
 // Now run any tidy up code prior to exiting completely.
 gui_up = 0; // Let functions know they can't address any widgets.
 tidy_up();

 // 4. Clean up the application object
 g_object_unref(app);

 return 0;
}




